void dfs(int x) {
    if (x >= a.size()) {
        //if (cx < cy) return;
        if (cx == 1 || cy == 1) return;
            ll cur = inv(cy, cx) * cy - 1;
           // write(cx), putchar(' '), write(cy), putchar(' '), write(cur), putchar('\n');
            res = std::min(res, cur);

        return;
    }
    cx = cx * a[x]; dfs(x + 1); cx = cx / a[x];
    cy = cy * a[x]; dfs(x + 1); cy = cy / a[x];
}

bool prime(ll t) {
    if (t < 2) return 0;
    for (ll i = 2; i * i <= t; ++i)
        if (t % i == 0) return 0;
    return 1;
}

