__int128 gcd128(__int128 a,__int128 b){
    if(a==0) return b;
    if(b==0) return a;
    return b>0?gcd128(b,a%b):a;
}

vector<int128> divisor(int128 n) {
    vector<int128> ret;
    for(int128 i=1; i*i<=n; i++) {
        if(n%i==0) {
            ret.push_back(i);
            if(n / i != i) ret.push_back(n/i);
        }
    }
    return ret;
}


