#include <bits/extc++.h>

template <class T, class U, class BinaryOperation = std::multiplies<>>
constexpr T power(T a, U n, T init = 1,
                  BinaryOperation binary_op = BinaryOperation{}) {
  static_assert(std::is_integral_v<U> and not std::is_same_v<U, bool>);
  assert(n >= 0);
  while (n) {
    if (n & 1) init = binary_op(init, a);
    if (n >>= 1) a = binary_op(a, a);
  }
  return init;
}

template <class T>
std::map<T, int> factorize(T n) {
  std::map<T, int> res;
  for (T i = 2; i * i <= n; ++i)
    while (n % i == 0) ++res[i], n /= i;
  if (n != 1) ++res[n];
  return res;
}

template <class T>
std::tuple<T, T, T> extgcd(T a, T b) {
  static_assert(std::is_integral_v<T> and std::is_signed_v<T>);
  std::array<T, 2> x{1, 0}, y{0, 1};
  while (b) {
    T q = a / b;
    std::swap(x[0] -= q * x[1], x[1]);
    std::swap(y[0] -= q * y[1], y[1]);
    std::swap(a -= q * b, b);
  }
  if (a < 0) x[0] = -x[0], y[0] = -y[0], a = -a;
  return {x[0], y[0], a};
}

int main() {
  using namespace std;
