  n *= 2;
  vector<int64_t> v;
  for (auto [p, e] : factorize(n)) v.push_back(power(p, e));
  int m = size(v);
  auto ans = n - 1;
  for (int bt = 1; bt < (1 << m) - 1; ++bt) {
    int64_t a = 1, b = 1;
    for (int i = 0; i < m; ++i)
      if (bt >> i & 1)
        a *= v[i];
      else
        b *= v[i];
    auto [x, y, g] = extgcd(a, b);
    assert(g == 1);
    if (x < 0) {
      x += b;
      y -= a;
    }
    y = -y;
