struct Ret {
  ll x;
  ll y;
  ll d;

  Ret (ll x = -1, ll y = -1, ll d = -1) {
    this->x = x;
    this->y = y;
    this->d = d;
  }
};

Ret extgcd(ll a, ll b) {
  if (b == 0) {
    return Ret(1LL, 0LL, a);
  } else {
    Ret ret = extgcd(b, a % b);

    return Ret(ret.y, ret.x - (a / b) * ret.y, ret.d);
  }
}

map<ll, ll> prime_division(ll n) {
  map<ll, ll> res;

  for (ll p = 2; p <= sqrt(n); ++p) {
    if (n % p != 0) continue;

    while (n % p == 0) {
      ++res[p];
      n /= p;
    }
  }

  if (n != 1) {
    res[n] = 1;
  }

  return res;
}

bool is_prime(ll n) {
  if (n <= 1) return false;

  for (ll p = 2; p <= sqrt(n); ++p) {
    if (n % p != 0) return false;
  }

  return true;
}

