    } else {
      cout << N - 1 << endl;
    }
  } else {
    map<ll, ll> primes = prime_division(2 * N);

    if (primes.size() == 1) {
      cout << 2 * N - 1 << endl;
      return 0;
    }

    ll cnt = primes.size();
    ll ans = LLONG_MAX;
