namespace tk {
template<typename T>
T gcd(const T & a, const T &b) {
	if (b == 0) return a;
	return gcd(b, a % b);
}

template<typename T>
T lcm(const T & a, const T & b) {
	return a / gcd(a, b) * b;
}

template<typename T>
T extgcd(const T & a, const T & b, T &x, T &y) {
	T a0 = a, a1 = 1, a2 = 0, b0 = b, b1 = 0, b2 = 1;
	while (b0 > 0) {
		T q = a0 / b0, r = a0 % b0;
		T nb1 = a1 - q * b1, nb2 = a2 - q * b2;
		a0 = b0; b0 = r;
		a1 = b1; b1 = nb1;
		a2 = b2; b2 = nb2;
	}
	x = a1;
	y = a2;
	return a0;
}
}

using pll = pair<ll, ll>;
vector<pll> prime_factorization(ll n) {
	vector<pll> res;

	for (ll i = 2; i * i <= n; i++) {
		if (n % i == 0) res.emplace_back(i, 0);
		while (n % i == 0) {
			n /= i;
			res.back().second++;
		}
	}
	if (n > 1) res.emplace_back(n, 1);

	return res;
}

