	vector<ll> powpf(pf.size(), 1);
	REP(i, pf.size()) {
		REP(j, pf[i].second) powpf[i] *= pf[i].first;
	}

	ll ans = longINF;
	REP(s, 1 << pf.size()) {
		ll alpha = 1, beta = 1;
		REP(i, pf.size()) {
			if (s >> i & 1) alpha *= powpf[i];
			else beta *= powpf[i];
		}
		// ここで gcd(alpha, beta) = 1
		// k = m1 alpha
		// k + 1 = m2 beta
		// 1 = m2 beta - m1 alpha
		ll m1, m2;
		tk::extgcd(beta, alpha, m2, m1);
		m1 = abs(m1);
		m2 = abs(m2);

		// cout << m1 << ", " << m2 << endl;

		if (m1 > 0 && m2 > 0 && m1 * alpha == m2 * beta - 1) {
			ll k = m1 * alpha;
			chmin(ans, k);
