#include<bits/stdc++.h>
#define int long long
using namespace std; 

int ans = 1e18, k=1, inp, n, m;
int a[18],r[18];

int min(int a, int b)
{
    if (a<b)
        return a;
    return b;
}

// Returns modulo inverse of a with respect to m using extended 
// Euclid Algorithm. Refer below post for details: 
// https://www.geeksforgeeks.org/multiplicative-inverse-under-modulo-m/ 
int inv(int a, int m) 
{ 
    int m0 = m, t, q; 
    int x0 = 0, x1 = 1; 

    if (m == 1) 
       return 0; 

    // Apply extended Euclid Algorithm 
    while (a > 1) 
    { 
        // q is quotient 
        q = a / m; 

        t = m; 

        // m is remainder now, process same as 
        // euclid's algo 
        m = a % m, a = t; 

        t = x0; 

        x0 = x1 - q * x0; 

        x1 = t; 
    } 

    // Make x1 positive 
    if (x1 < 0) 
       x1 += m0; 

    return x1; 
} 

// k is size of num[] and rem[].  Returns the smallest 
// number x such that: 
//  x % num[0] = rem[0], 
//  x % num[1] = rem[1], 
//  .................. 
//  x % num[k-2] = rem[k-1] 
// Assumption: Numbers in num[] are pairwise coprime 
// (gcd for every pair is 1) 
int findMinX(int num[], int rem[], int k) 
{ 
    // Compute product of all numbers 
    int prod = 1; 
    for (int i = 0; i < k; i++) 
        prod *= num[i]; 

    // Initialize result 
    int result = 0; 

    // Apply above formula 
    for (int i = 0; i < k; i++) 
    { 
        int pp = prod / num[i]; 
        result += rem[i] * inv(pp, num[i]) * pp; 
    } 

    return result % prod; 
} 

void findAll(int done)
{
    if (done==k)
    {
        inp=findMinX(a,r,k);
        --inp;
        if (inp==0)
            inp=m;
        else if (inp==-1)
            inp=m-1;
        ans=min(ans,inp);
        return;
    }
    r[done]=0;
    findAll(done+1);
    r[done]=1;
    findAll(done+1);
}

