int mod_pow(int n, int e, int mod){
    int ans = 1;
    n = n % mod;
    while(e != 0){
        if(e % 2 == 1){
            ans = (ans * n) % mod;
        }
        e /= 2;
        n = (n * n) % mod;
    }
    return ans;
}

int mod_inv(int n, int mod){
    return mod_pow(n, mod-2, mod);
}

int sieve(int p, int q){
    // ax + bz = a, ay + bw = b からスタートして
    // 右辺について互除法して係数を変えていく
    // (x, y) -> (y, x-y*(a/b)), (z, w) -> (w, z-w*(a/b))
    // 最終的に ax + bz = gcd(a, b) となるので a, b が互いに素なら x が逆元
    // z と w を覚えておく必要はない
    int a = p, b = q, x = 1, y = 0;
    while(b){
        x -= y * (a/b); swap(x, y);
        a -= b * (a/b); swap(a, b);
    }
    while(x < 0) x += q;
    return x;
}

