vector<pair<int,ll>> factorization(ll N) {
    vector<pair<int,ll>> ans;
    for (ll i = 2;i*i <= N; ++i) {
        ll e = 1;
        while (N%i == 0) {
            e *= i;
            N /= i;
        }
        if (e > 1) ans.emplace_back(i,e);
    }
    if (N > 1) ans.emplace_back(N,N);
    return ans;
}

template<class T> T gcd(T a,T b) {return (b ? gcd(b,a%b): a);}
long long x,y;
long long extGCD(long long a,long long b,long long &x,long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b,a%b,y,x);
    y -= a/b * x;
    return d;
}

