long long exgcd(long long a, long long b, long long &x, long long &y) {
	if (!b) {
		x = 1, y = 0;
		return a;
	}
	long long g = exgcd(b, a % b, y, x);
	y -= a / b * x;
}

void get_prime(int n) {
	for (int i = 2; i <= n; i++) {
		if (!vis[i]) prime[tot++] = i;
		for (int j = 0; j < tot && 1ll * i * prime[j] <= n; j++) {
			vis[i * prime[j]] = 1;
			if (i % prime[j] == 0) break;
		}
	}
}

int main () {
	get_prime(31622776);
	long long n; cin >> n; n *= 2;
	vector <long long> all;
	for (int i = 0; i < tot; i++) {
		long long pw = prime[i];
		while (n % pw == 0) pw *= prime[i];
		pw /= prime[i];
		if (pw != 1) all.push_back(pw);
	}
	int m = all.size();
	long long ans = 900000000000000000;
	for (int mask = 0; mask < (1 << m); mask++) {
		long long x = 1, y = 1, k1, k2;
		for (int i = 0; i < m; i++) {
			if (mask >> i & 1) x *= all[i];
			else y *= all[i];
		}
		exgcd(x, y, k1, k2);
		k2 = -k2;
		long long tmp = max((max(0ll, 1 - k1) + y - 1) / y, (max(0ll, 1 - k2) + x - 1) / x);
		k1 += tmp * y, k2 += tmp * x;
		if (ans / k2 >= y) ans = min(ans, k2 * y);
		k1 = -k1, k2 = -k2;
		tmp = max((max(0ll, 1 - k1) + y - 1) / y, (max(0ll, 1 - k2) + x - 1) / x);
		k1 += tmp * y, k2 += tmp * x;
		if (ans / k1 >= x) ans = min(ans, k1 * x);
	}
	cout << ans << endl;
	return 0;
}

