	{
		ll mid=(l+r)/2;
		if(l>r)	return (ll)-1;
		if(a[mid]==b||l==r)	return mid;
		if(a[mid]>b)	return bs(a,b,l,mid-1);
		else return bs(a,b,mid+1,r);
	}

