        if(n%i==0){
            auto x = ChineseRem(0ll,i,-1,n/i);
            auto y = ChineseRem(0ll,n/i,-1,i);
            if(x.second>0){
                if(x.first == 0) x.first += x.second;
                chmin(ans,x.first);
            }
            if(y.second>0){
                if(y.first == 0) y.first += y.second;
                chmin(ans,y.first);
            }
        }
    }
    cout << ans << endl;
}

