// 初項:a, 公差:a で, 上限:lim の数列の総和を返す関数
int sn(int a, int lim)
{
    int n = lim / a;         // 項数:n  =  上限:lim / 公差:a
    int l = n * a;           // 末項:l  =  項数:n   * 公差:a
    return (a + l) * n / 2;  // 総和:sn = (初項:a   + 末項:l) * 項数:n / 2
}


long long inv_mod(long long x, long long mod)
{
    long long y = mod;
    long long u = 1;
    long long v = 0;
    while (y)
    {
        long long t = x / y;
        x -= t * y;
        swap(x, y);
        u -= t * v;
        swap(u, v);
    }
    u %= mod;
    if (u < 0)
        u += mod;
    return u;
}

