// ax+by=gcd(a,b)
// |x|+|y| -> min
// x <= y
ll extgcd(ll a, ll b, ll& x, ll& y) {
  ll g = a; x = 1; y = 0;
  if (b) g = extgcd(b, a%b, y, x), y -= (a / b) * x;
  return g;
}

constexpr ll INF = 1e16;

ll calc(ll a, ll b) {
  ll x,y;
  ll g = extgcd(a, b, x, y);
  if (g != 1) return INF;
  if (x < 0) {
    ll tmp = -x * a;
    if (x+b >= 0) {
      tmp = min(tmp, b*(a-y));
    }
    return tmp;
  } else {
    ll tmp = -y * b;
    if (y+a >= 0) {
      tmp = min(tmp, a*(b-x));
    }
    return tmp;
  }
}

