	auto [f, phi] = fact(n);
	for(int msk = 0; msk < 1<<f.size(); msk++) {
		ll d = 1, nd = 1, dphi = 1, ndphi = 1;
		for(int j = 0; j < f.size(); j++) {
			if((msk>>j)&1) swap(d, nd), swap(dphi, ndphi);
			d *= f[j];
			dphi *= phi[j];
			if((msk>>j)&1) swap(d, nd), swap(dphi, ndphi);
		}
		ll k = (nd-bp(d, ndphi-1, nd))%nd;
		if(k == 0) k = nd;
		//cout << k << " " << d << endl;
		ans = min(ans, k*d);
	}
	cout << ans << '\n';
}

