array<vector<ll>, 2> fact(ll n) {
	vector<ll> f, phi;
	for(ll d = 2; d*d <= n; d++) {
		ll t = 1;
		while(n%d == 0) n/=d, t*=d;
		if(t>1) f.push_back(t), phi.push_back(t - (t/d));
	}
	if(n>1) f.push_back(n), phi.push_back(n-1);
	return {f, phi};
}
ll bp(ll a, ll p, ll m) {
	ll r = 1;
	while(p) {
		if(p&1) r = r*a%m;
		a = a*a%m, p>>=1;
	}
	return r;
}
