using namespace atcoder;
ll codeforces = 1;
string S, T;
vl insuu;
void insuubunkai(ll n) {
    ll a = n;
    for(ll i = 2; i * i <= a; i++) {
        if(a % i == 0) {
            t = 1;
            while(a % i == 0) {
                a = a / i;
                t *= i;
            }
            insuu.pb(t);
        }
    }

    if(a != 1)
        insuu.pb(a);
}
vl A, B;
void input() { cin >> n; }
void solve() {
    n *= 2;
    insuubunkai(n);

    k = insuu.size();
    ans = INF;
    rep(i, (1 << k)) {
        A.clear();
        rep(j, k) {
            if(i & 1 << j) {
                A.pb(0);
            } else
                A.pb(insuu[j] - 1);
        }
        p = crt(A, insuu).fi;
        if(p)
            ans = min(ans, p);
    }

    print(ans);
}
int main() {
    // cout<<fixed<<setprecision(15);
    cin.tie(0);
    ios::sync_with_stdio(false);
    input();
    while(codeforces--) {
        solve();
        a = 1;
    }
}

