ll inv(ll a, ll m){ 
    ll m0 = m, t, q; 
    ll x0 = 0, x1 = 1; 

    if (m == 1) return 0; 
    while (a > 1){
        q = a / m; 

        t = m;
        m = a % m, a = t; 

        t = x0; 

        x0 = x1 - q * x0; 

        x1 = t; 
    } 
    if (x1 < 0) 
       x1 += m0; 

    return x1; 
} 

ll findMinX(vll num, vll rem){
    ll prod = 1;
    for(int i = 0; i < 2; i++) 
        prod = prod * num[i];
    ll result = 0;
    for(int i = 0; i < 2; i++){
        ll pp = prod / num[i]; 
        result = (result + rem[i] * inv(pp, num[i]) % prod * pp % prod) % prod;
    }
    return result % prod;
}

void solve(){
    cin >> n;
    ll ans = INF, m = 2*n;
    for(ll i = 1; i <= m; i *= 2){
    	if(n == i){
    		deb1(i*2 - 1)
    		return;
    	}
    }
    for(ll i = 2; i*i <= m; i++){
    	if(m % i == 0){
    		if(__gcd(i, m / i) == 1){
    			vll num(2), rem(2);
    			num[0] = i;
    			num[1] = m / i;
    			rem[0] = 0;
    			rem[1] = m / i - 1;
    			ans = min(ans, findMinX(num, rem));
    			num[0] = m / i;
    			num[1] = i;
    			rem[0] = 0;
    			rem[1] = i - 1;
    			ans = min(ans, findMinX(num, rem));
    		}
    	}
    }
    deb1(ans)
}

