signed main() {
    int n; cin >> n;
    if (n == 1) {
        cout << 1 << endl;
        return 0;
    }
    if (n == 2) {
        cout << 1 << endl;
        return 0;
    }
    vi v;
    n *= 2;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            int sum = 1;
            while (n % i == 0) {
                n /= i;
                sum *= i;
            }
            v.pb(sum);
        }
    }
    if (n > 1) v.pb(n);

    ll ans = 0;
    rep(i, (1ll << siz(v))) {
        vi r, m;
        rep(j, siz(v)) {
            if ((i >> j) & 1) {
                r.pb(0);
                m.pb(v[j]);
            }
            else{
                r.pb(v[j] - 1);
                m.pb(v[j]);
            }
        }
        auto res = crt(r, m);
        if (res != H{ 0,0 }) {
            if (res.fs == 0) res.fs = res.sc;
            if (!ans) ans = res.fs;
            else chmin(ans, res.fs);
        }
    }
    cout << ans << endl;
}

