llint n;
bool prime[50000005];
map<llint, llint> mp;

llint gcd(llint a, llint b)
{
	if(b == 0) return a;
	return gcd(b, a%b);
}

//ax+by = gcd(a, b)を満たす(x, y)を求めgcd(a, b)を返す
llint extgcd(llint a, llint b, llint &x, llint &y)
{
	if(b == 0){
		x = 1, y = 0;
		return a;
	}
	llint xx, yy;
	llint d = extgcd(b, a%b, xx, yy);
	x = yy, y = xx-(a/b)*yy;
	return d;
}

//a^{-1} (mod m)を求める。存在しない場合(gcd(a, m)!=1)は-1を返す
llint mod_inverse(llint a, llint m)
{
	llint x, y;
	if(extgcd(a, m, x, y) != 1) return -1;
	return (x%m + m) % m;
}

int main(void)
{
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n;
	n *= 2;

	for(int i = 2; i < 8005; i++){
		if(prime[i]) continue;
		for(int j = 2*i; j < 50000005; j+=i) prime[j] = true;
	}

	for(int i = 2; i < 50000005; i++){
		if(prime[i]) continue;
		while(n % i == 0){
			mp[i]++;
			n /= i;
		}
	}
	if(n > 1) mp[n]++;

	vector<llint> vec;
	for(auto it = mp.begin(); it != mp.end(); it++){
		llint mul = 1;
		for(int i = 0; i < it->second; i++) mul *= it->first;
		vec.push_back(mul);
	}

	llint ans = inf, m = vec.size(), M = 1<<m;
	for(int i = 0; i < M; i++){
		llint mul = 1, mul2 = 1;
		for(int j = 0; j < m; j++){
			if(i & (1<<j)) mul *= vec[j];
			else mul2 *= vec[j];
		}
		llint res = mod_inverse(mul, mul2);
		llint y = (mul*res-1)/mul2;
		if(y <= 0) res +=((-y+1)+mul*mul2-1)/(mul*mul2) * mul2;
		//cout << mul << " " << mul2 << " " << res << endl;
		ans = min(ans, mul*res-1);
	}
	cout << ans << endl;

	return 0;
}

