long long modinverse(long long a, long long b, long long s0 = 1, long long s1 = 0) { return b == 0 ? s0 : modinverse(b, a % b, s1, s0 - s1 * (a / b)); }
long long gcd(long long a, long long b) { return b == 0 ? a : gcd(b, a % b); }
long long mul(long long a, long long b, long long m) {
	long long q = (long double) a * (long double) b / (long double) m;
	long long r = a * b - q * m;
	return (r + m) % m;
}

struct Equation {
	Equation(long long a, long long m) { mod = m, ans = a, valid = true; }
	Equation() { valid = false; }
	Equation(Equation a, Equation b) {
		ans = -1;
		if(!a.valid || !b.valid) {
			valid = false;
			return;
		}
		long long g = gcd(a.mod, b.mod);
		if((a.ans - b.ans) % g != 0) {
			valid = false;
			return;
		}
		valid = true;
		mod = a.mod * (b.mod / g);
		ans = a.ans +
			  mul(
					mul(a.mod, modinverse(a.mod, b.mod), mod),
					(b.ans - a.ans) / g
			  , mod);
		ans = (ans % mod + mod) % mod;
	}
	long long mod, ans;
	bool valid;
};

int main() {
	std::ios_base::sync_with_stdio(false); std::cin.tie(NULL);
	long long x;
	std::cin >> x;
	long long ans = x;
	std::vector<long long> primes;
	{
		long long m = x;
		for(long long l = 2; l * l <= m; l++) {
			long long e = 1;
			while(m % l == 0) {
				e *= l;
				m /= l;
			}
			if(e > 1) primes.push_back(e);
		}
		if(m > 1) {
			primes.push_back(m);
		}
	}
	auto test = [&](long long val) {
		//std::cout << "testing " << val << '\n';
		if(val <= 1) return;
		if((val % 2 == 0 ? mul(val/2, val-1, x) : mul((val-1)/2, val, x)) == 0) ans = std::min(ans, val-1);
	};
	int n = (int) primes.size();
	for(int i = 0; i < (1 << n); i++) {
		long long a = 1, b = 1;
		for(int j = 0; j < n; j++) {
			if(i & (1 << j)) {
				a *= primes[j];
			} else {
				b *= primes[j];
			}
		}
		assert(a * b == x);
		if(0){
			// val % (2*a) == 0
			// val % b == b-1
			auto eq = Equation(Equation(0, 2*a), Equation(b-1, b));
			test(eq.ans);
		}
		{
			// val % a == 0
			// val % b == b-1
			auto eq = Equation(Equation(0, 2*a), Equation(b-1, b));
			test(eq.ans);
			test(eq.ans*2);
			test(eq.ans+1);
			test(eq.ans*2+1);
		}
	}
	std::cout << ans << '\n';
}

