std::pair<int, int> extgcd(int a, int b) {

  int s = a, sx = 1, sy = 0, t = b, tx = 0, ty = 1;

  while (s % t != 0) {

    int temp = s / t;
    int u = s - t * temp;
    int ux = sx - tx * temp;
    int uy = sy - ty * temp;

    s = t;
    sx = tx;
    sy = ty;
    t = u;
    tx = ux;
    ty = uy;
  }

  return {tx, ty};
}
