pair<ll, pair<ll, ll>> gcd(ll a, ll b) {
    if (b == 0) {
        return {a, {1, 0}};
    }
    auto p = gcd(b, a % b);
    // a % b = a - (a / b) * b
    // b * k1 + (a - (a / b) * b) * l1 = g
    // b * k1 + a * l1 - (a/b) * b * l1 = g
    // b * (k1 - (a/b) * l1) + a * l1 = g
    return {p.first, {p.second.second, p.second.first - (a/b) * p.second.second}};
}

pair<ll, ll> solve_diof(ll a, ll b, ll c) {
    auto p = gcd(abs(a), abs(b));
    if (a < 0) p.second.first *= -1;
    if (b < 0) p.second.second *= -1;
    if (c % p.first != 0) return {INF, INF};
    p.second.first *= c / p.first;
    p.second.second *= c / p.first;
    ll b1 = b / p.first, a1 = a / p.first;
    if (p.second.first < 0) {
        ll k = (-p.second.first) / b1 + 1;
        p.second.first += b1 * k;
        p.second.second -= a1 * k;
    }
    ll k = p.second.first / b1;
    p.second.first -= b1 * k;
    p.second.second += a1 * k;
    return p.second;
}

