//ax+by=gcd(a,b)の解
LL extgcd(LL a, LL b, LL& x, LL& y) {
	LL d = a;
	if (b != 0) {
		d = extgcd(b, a % b, y, x);
		y -= (a / b) * x;
	}
	else {
		x = 1; y = 0;
	}
	return d;
}

//約数列挙(重複分も個数回追加)
void enumerateFactors(LL N, vector<LL>& V) {
	LL p = 2;
	while (N > 1) {
		if (p * p > N) {
			V.push_back(N);
			return;
		}
		if (N % p == 0) {
			V.push_back(p);
			N /= p;
		}
		else p++;
	}
	return;
}

bigint solve(LL u, LL v) {
	LL x;
	LL y;
	extgcd(u, v, x, y);
	LL t1 = x / v;
	LL t2 = (-y) / u;
	bigint t(max(t1, t2));
	bigint vb(v);
	bigint ub(u);
	bigint xb(x);
	bigint yb(y);
	while (v * t <= x || u * t <= -y)t++;
	bigint a = vb * t - xb;
	bigint k = a * ub;
	return k;
}

void solve() {
	vector<PLL> primes;   //(prime,time)
	{
		VLL V;
		enumerateFactors(2*N, V);
		primes.push_back(PLL(V[0], 1));
		for (int n = 1; n < V.size(); n++) {
			LL p = V[n];
			if (primes.back().first == p)primes.back().second++;
			else primes.push_back(PLL(p, 1));
		}
	}
	for (PLL& pll : primes) {
		LL p = pll.first;
		LL ans = 1;
		for (int t = 0; t < pll.second; t++) {
			ans *= p;
		}
		pll.first = ans;
	}
	bigint ans(1e15);
	ans *= ans;
	for (int code = 0; code < ((LL)1 << primes.size()); code++) {
		LL first = 1;
		LL second = 1;
		for (int b = 0; b < primes.size(); b++) {
			if (((1 << b) & code) != 0)first *= primes[b].first;
			else second *= primes[b].first;
		}
		bigint k = solve(first, second);
		if (ans > k)ans = k;
	}
	cout << ans << "\n";
}

