long long naive(long long N) {
    N *= 2;
    for (long long k = 1; k <= N; ++k) {
        if (k * (k + 1) % N == 0) return k;
    }
}


vector<long long> prime_factorize(long long n) {
    vector<long long> res;
    for (long long p = 2; p * p <= n; ++p) {
        if (n % p != 0) continue;
        int num = 0;
        long long val = 1;
        while (n % p == 0) { ++num; n /= p; val *= p; }
        res.push_back(val);
    }
    if (n != 1) res.push_back(n);
    return res;
}

long long solve(long long N) {
    N *= 2;
    auto pf = prime_factorize(N);
    int M = pf.size();
    long long res = N-1;
    for (int bit = 0; bit < (1<<M); ++bit) {
        long long left = 1;
        for (int i = 0; i < M; ++i) if (bit & (1LL<<i)) left *= pf[i];
        long long right = N / left;

        if (left > right) {
            // find k
            for (long long tmp = left; tmp < res; tmp += left) {
                long long k = tmp, pk = tmp + 1;
                if (pk % right == 0) chmin(res, k);
            }
        }
        else {
            // find k + 1
            for (long long tmp = right; tmp - 1 < res; tmp += right) {
                long long k = tmp - 1, pk = tmp;
                if (k % left == 0) chmin(res, k);
            }
        }
    }
    return res;
}

