typedef long long int ll;
constexpr ll kInf = ll(1E18 + 10);

ll extgcd(ll a, ll b, ll &x, ll &y) { // a * x - b * y = gcd
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}
	else {
		ll tx, ty;
		ll gcd = extgcd(b, a % b, tx, ty);
		// b * tx - (a % b) * ty = gcd
		// b * tx - (a - a / b * b) * ty = gcd
		// b * tx - a * ty + a / b * b * ty = gcd
		// a * -ty + b * (tx + a / b * ty) = gcd
		x = -ty;
		y = -(tx + a / b * ty);

		y %= a;
		x = (gcd + b * y) / a;
		if (y <= 0) {
			x += b;
			y += a;
		}
		return gcd;
	}
}

ll check(ll p, ll q) {
	//p * x - q * y = 1
	ll x, y;
	if (extgcd(p, q, x, y) > 1) return kInf;
	else {
		return q * y;
	}
}

