inline __int128 mod(__int128 a, __int128 m) {
    return (a % m + m) % m;
}

__int128 extGcd(__int128 a, __int128 b, __int128 &p, __int128 &q) {  
    if (b == 0) { p = 1; q = 0; return a; }  
    __int128 d = extGcd(b, a%b, q, p);  
    q -= a/b * p;  
    return d;  
}

pair<__int128, __int128> ChineseRem(__int128 b1, __int128 m1, __int128 b2, __int128 m2) {
  __int128 p, q;
  __int128 d = extGcd(m1, m2, p, q); // p is inv of m1/d (mod. m2/d)
  if ((b2 - b1) % d != 0) return make_pair(0, -1);
  __int128 m = m1 * (m2/d); // lcm of (m1, m2)
  __int128 tmp = (b2 - b1) / d * p % (m2/d);
  __int128 r = mod(b1 + m1 * tmp, m);
  return make_pair(r, m);
}

