vector<pll> pf(ll x) {
	vector<pll> res;
	ll p = 2;
	while (p * p <= x) {
		if (x % p == 0) {
			ll d = 0;
			while (x % p == 0) {
				x /= p;
				d++;
			}
			res.push_back(pll(p, d));
		}
		p++;
	}
	if (x > 1) res.push_back(pll(x, 1));
	return res;
}

ll solve(int i, vl &m) {
	vl r; // 余り(0 or -1)
	rep(j, m.size()) {
		if (i & (1 << j)) {
			r.push_back(m[j] - 1);
		} else {
			r.push_back(0);
		}
	}
	// dbl(i); dbl(r);
	auto [res, M] = crt(r, m);
	// dbs(res, M);
	return res;
}

