i64 gcd (i64 a, i64 b, i64 & x, i64 & y) {
	if (a == 0) {
		x = 0; y = 1;
		return b;
	}
	i64 x1, y1;
	i64 d = gcd (b%a, a, x1, y1);
	x = y1 - (b / a) * x1;
	y = x1;
	return d;
}

bool find_any_solution (i64 a, i64 b, i64 c, i64 & x0, i64 & y0, i64 & g) {
	g = gcd (abs(a), abs(b), x0, y0);
	if (c % g != 0)
		return false;
	x0 *= c / g;
	y0 *= c / g;
	if (a < 0)   x0 *= -1;
	if (b < 0)   y0 *= -1;
	return true;
}

void shift_solution (i64 & x, i64 & y, i64 a, i64 b, i64 cnt) {
	x += cnt * b;
	y -= cnt * a;
}

i64 find_all_solutions (i64 a, i64 b, i64 c, i64 minx, i64 maxx, i64 miny, i64 maxy) {
	i64 x, y, g;
	if (! find_any_solution (a, b, c, x, y, g))
		return 0;
	a /= g;  b /= g;

	i64 sign_a = a>0 ? +1 : -1;
	i64 sign_b = b>0 ? +1 : -1;

	shift_solution (x, y, a, b, (minx - x) / b);
	if (x < minx)
		shift_solution (x, y, a, b, sign_b);
	if (x > maxx)
		return 0;
	i64 lx1 = x;

	shift_solution (x, y, a, b, (maxx - x) / b);
	if (x > maxx)
		shift_solution (x, y, a, b, -sign_b);
	i64 rx1 = x;

	shift_solution (x, y, a, b, - (miny - y) / a);
	if (y < miny)
		shift_solution (x, y, a, b, -sign_a);
	if (y > maxy)
		return 0;
	i64 lx2 = x;

	shift_solution (x, y, a, b, - (maxy - y) / a);
	if (y > maxy)
		shift_solution (x, y, a, b, sign_a);
	i64 rx2 = x;

	if (lx2 > rx2)
		swap (lx2, rx2);
	i64 lx = max (lx1, lx2);
	i64 rx = min (rx1, rx2);

    logss(lx, rx);
    logss(a, b);
    return lx;
	// return (rx - lx) / abs(b) + 1;
}

