}

ll a[5], m[5];

ll mul(ll x, ll y, ll P) {
    return (x * y - (ll) (x / (long double) P * y + 1e-3) * P + P) % P;
}

template<class T>
void CRT(T &ans, T &M, T a[], T m[], int k) {
    M = 1, ans = 0;
    T x, y, Mi;
    for (int i = 0; i < k; i++) M *= m[i];
    for (int i = 0; i < k; i++) {
        Mi = M / m[i];
        ExGcd(m[i], Mi, x, y);
        ans = (ans + mul(mul(y, Mi, M), a[i], M)) % M;
        // ans = (ans + y * Mi * a[i]) % M
    }
    if (ans <= 0) ans += M;
}

