int128 extgcd(int128 a, int128 b, int128& x, int128& y) {
    if(b==0){
        x=1;
        y=0;
        return a;
    }
    int128 d=extgcd(b,a%b,y,x);
    y-=a/b*x;
    return d;
}


signed main(){
    int128 n;cin>>n;
    // naive(n);

    // 2*n*t=k*(k+1)
    n*=2;
    auto d=divisor(n);


    int128 res=LINF;
    for(auto x:d){
        auto y=n/x;
        if(gcd128(x,y)!=1) continue;



        // minimize a*b (=t)
        // ax=by+1
        {
            int128 adash,bdash;
            extgcd(x,-y,adash,bdash);// ax-by=1

            // a = adash + y * u
            // b = bdash + x * u

            int128 minu=-LINF;
            {
                if(adash<0){
                    auto ab=abs128(adash);
                    chmax(minu,(ab+y-1)/y);
                }else{
                    chmax(minu,adash/y);
                }
                if(bdash<0){
                    auto bb=abs128(bdash);
                    chmax(minu,(bb+x-1)/x);
                }else{
                    chmax(minu,bdash/x);
                }
            }
            int128 a=adash+y*minu;
            int128 b=bdash+x*minu;
            if(a==0 or b==0){
                a+=y;b+=x;
            }
            chmin(res,a*x);
        }   
    }
    cout<<res<<endl;
    return 0;
}

