//返り値:aとbの最大公約数
//ax+by=gcd(a,b)を満たす(x,y)が格納される
ll ext_gcd(ll a,ll b,ll &x,ll & y){
    if(b==0){
        x=1;
        y=0;
        return a;
    }
    ll d=ext_gcd(b,a%b,y,x);
    y-=a/b*x;
    return d;
}

//リターン値を(r,m)とすると解はx=r(mod. m)
//解なしの場合は(0,-1)をリターン
pair<ll,ll> chi_rem(ll b1,ll m1,ll b2,ll m2){
    ll p,q;
    ll d=ext_gcd(m1,m2,p,q);
    if((b2-b1)%d!=0)return make_pair(0,-1);
    ll m=m1*(m2/d);
    ll tmp=(b2-b1)/d*p%(m2/d);
    ll r=mod(b1+m1*tmp,m);
    return make_pair(r,m);
}

vector<ll> func(ll n){
    vector<ll> ans;
    for(int i=2;i*i<=n;i++){
        if(n%i==0){
            ans.push_back(i);
            if(i*i!=n)ans.push_back(n/i);
        }
    }

    return ans;
}


/*方針
k(k+1)が2nの倍数であるような最小の自然数kを求める
nの各約数xについて、kがxの倍数でありk+1が2n/xの倍数であるような最小のkを求める: O(logn)
各xに対し行い、その最小値を求める: nの各約数を求めるのにO(ルートn)
*/
int main(){
    int n;cin>>n;
    n*=2;
    vector<ll> a=func(n);
    int l=a.size();
    ll ans=INF;
    //rep(i,l)cout<<a[i]<<endl;
    rep(i,l){
        ll m1=a[i];
        ll m2=n/a[i];
        if(chi_rem(0,m1,-1,m2).first!=0)ans=min(ans,chi_rem(0,m1,-1,m2).first);
        //printf("%lld %lld %lld %lld\n",m1,m2,chi_rem(0,m1,-1,m2).first,chi_rem(0,m1,-1,m2).second);
    }
    cout<<ans<<endl;


    return 0;
}

