    std::cin.tie(nullptr);

    int64_t n;
    std::cin >> n;
    n *= 2;

    std::vector<int64_t> p;
    int64_t x = n;
    for (int64_t i = 2; i * i <= x; ++i) {
        if (x % i == 0) {
            int64_t v = 1;
            while (x % i == 0) {
                x /= i;
                v *= i;
            }
            p.push_back(v);
        }
    }
    if (x > 1)
        p.push_back(x);

    int64_t ans = n;

    std::function<void(int, int64_t)> dfs = [&](int x, int64_t a) {
        if (x == int(p.size())) {
            int64_t b = n / a;
            int64_t y = a - inv_mod(b, a);
            ans = std::min(ans, b * y);
            return;
        }
        dfs(x + 1, a);
        dfs(x + 1, a * p[x]);
    };
    dfs(0, 1);

    std::cout << ans << "\n";

    return 0;
}

