			if(mask & (1LL << i)) {
				x *= div[i].fi;
				phi *= (div[i].fi - (div[i].fi / div[i].se));
			}
			else {
				y *= div[i].fi;
			}
		}
		if(y != 1) {
			int z = modpow(y, phi - 1, x);
			ans = min(ans, y * z - 1);
		}
	}
	cout << ans;

	return 0;
}

