        is >> N;
        return !!is;
    }

    vector<ll> fc(ll x){
        vector<ll> r;
        for (ll i = 1; i*i <= x; ++i) {
            if(x % i == 0){
                r.push_back(i);
                r.push_back(x);
            }
        } // end i
        return r;
    }

    vector<ll> fp(ll x){
        vector<ll> w;
        for (ll i = 2; i*i <= x; ++i) {
            if(x % i == 0){
                ll p = 1;
                while(x % i == 0){
                    x /= i;
                    p *= i;
                }
                w.emplace_back(p);
            }
        } // end i
        if(x > 1) w.emplace_back(x);
        return w;
    }

    void run();
};

void solver::run(){
    if(!input()) return;
    if(N == 1) {
        cout << 1 << endl;
        return;
