typedef __int128 num;

// returns g,s,t such that gcd(a,b) == g == s*a + t*b
tuple<num,num,num> eea(num a, num b) {
	if (b == 0) return {a, 1, 0};
	auto [g,s,t] = eea(b,a%b);
	return {g, t, s-t*(a/b)};
}

struct eqn { num a, m; }; // x == a (mod m)

eqn operator*(eqn C, eqn D) {
	auto [g,s,t] = eea(C.m,D.m); t = t;
	if (g == 1) {
		num b = ((D.a-C.a) * s) % D.m;
		if (b < 0) b += D.m;
		return {C.a + b*C.m, C.m*D.m};
	} else {
		if ((C.a - D.a) % g) return {0,0};
		eqn E = eqn{C.a/g, C.m/g} * eqn{D.a/g, D.m/g};
		return {E.a*g + C.a%g, E.m*g};
	}
}

ll solve(num n) {
	num res = LLONG_MAX;
	auto consider = [&](num d) {
		num m = 2*n/d;
		num g, s, t;
		tie(g,s,t) = eea(d,m);
		if (g != 1) return;
		ll a = -s % m;
		if (a <= 0) a += m;
		assert((d*a+1)%m == 0);
		assert(get<0>(eea(a,m)) == 1);
		num k = d*a;
		// cerr << ll(k) << endl;
		assert((k*(k+1)) % (2*n) == 0);
		assert((k*(k+1)/2) % n == 0);
		res = min(res, k);
	};

	for (num d = 1; d*d <= 2*n; d++) if (2*n%d == 0) {
		consider(d);
		consider(2*n/d);
	}
	return res;
}

