void exgcd(LL A,LL B,LL &X,LL &Y){// AX-BY=1
	if(!B){
		X=1;Y=0;
		return;
	}
	exgcd(B,A%B,X,Y);
	LL nX=-Y,nY=-X-(A/B)*Y;
	if(nX<0){
		LL mtp=(-nX+B-1)/B;
		nX+=B*mtp;
		nY+=A*mtp;
	}
	if(nY<0){
		LL mtp=(-nY+A-1)/A;
		nX+=B*mtp;
		nY+=A*mtp;
	}
	LL mtp=min(nX/B,nY/A);
	nX-=B*mtp;
	nY-=A*mtp;
	X=nX;Y=nY;
}
void exgcd2(LL A,LL B,LL &X,LL &Y){
	if(A==1){
		X=B+1;
		Y=1;
		return;
	}
	if(B==1){
		X=1;
		Y=A-1;
		return;
	}
	exgcd(A,B,X,Y);
}
