template <class SignedInteger>
unsigned long long gcd_extended(unsigned long long a, unsigned long long b, SignedInteger &x, SignedInteger &y)
{
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    SignedInteger x0, y0;
    unsigned long long d = gcd_extended(b, a % b, x0, y0);
    x = y0;
    y = x0 - a / b * y0;
    return d;
}

