ll extGCD(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

ll solve(ll N) {
    // 素因数分解 O(x^(1/2))
    auto PrimeFactor = [](ll x) {
        map<ll, ll> pr;
        for ( ll k = 2; k * k <= x; k++ ) {
            while ( x % k == 0 ) {
                pr[k]++;
                x /= k;
            }
        }
        if ( x > 1 ) pr[x]++;
        return pr;
    };
    map<ll,ll> pr = PrimeFactor(N);
    vector<ll> ps,as;
    for ( auto pp : pr ) {
        ps.push_back(pp.first);
        as.push_back(pp.second);
    }
    ll ans = 1LL<<60;
    int bm = ps.size();
    for ( int b = 0; b < 1<<bm; b++ ) {
        for ( int ii = 0; ii < bm; ii++ ) {
            ll p1 = 1, p2 = 1;
            if ( (b >> ii) & 1 ) {
                for ( int i = 0; i < as[ii]; i++ ) p1 *= ps[ii];
            } else {
                for ( int i = 0; i < as[ii]; i++ ) p2 *= ps[ii];
            }
            ll x, y;
            extGCD(p1,p2,x,y);
            if ( x < 0 ) {
                x += p2;
                y -= p1;
            }
            ans = min(ans,p1*x);
        }
    }

    return ans;
}

