template<class Integer>
inline Integer get_power(Integer base, ull exponential)
{
	Integer result = 1;
	while (exponential >= 1)
	{
		if (exponential & 1)
		{
			result = result * base;
		}
		base = base * base;
		exponential >>= 1;
	}

	return result;
}

// computational complexity: o(log(max(a, b))) 
inline pair<ll, ll> getBezoutsIdentitySolution(ll a, ll b)
{
	if (b == 0)
	{
		return { 1, 0 };
	}
	auto sol = getBezoutsIdentitySolution(b, a % b);
	return { sol.second, sol.first - (a / b) * sol.second };
}

int solve() {
	ll n;
	cin >> n;
	n *= 2LL;

	ll sqrtn = 1;
	REPD(i, 1, n) {
		if (i * i > n) break;
		sqrtn = i;
	}
	map<ll, ll> factors;
	vector<bool> is_primes(sqrtn + 1LL, true);
	ll quot = n;
	REPD(p, 2, sqrtn + 1) {
		if (!is_primes[p]) continue;
		while (quot % p == 0LL) {
			quot /= p;
			if (factors.count(p) == 0) factors[p] = 0;
			++factors[p];
		}
		for (ll i = 2; i * p <= sqrtn; ++i) {
			is_primes[i * p] = false;
		}
	}
	if (quot != 1LL) factors[quot] = 1;

	ll res = MAX_VALUE;
	ll prime_count = factors.size();
	REPD(bit, 0, 1LL << prime_count) {
		ull target = 0;
		ll a = 1, b = 1;
		for (auto iter = factors.begin(); iter != factors.end(); ++iter) {
			if ((bit >> target) % 2LL == 1LL) a *= get_power(iter->first, iter->second);
			else b *= get_power(iter->first, iter->second);
			++target;
		}
		ll x, y;
		tie(y, x) = getBezoutsIdentitySolution(b, -a);
		if (b * y - a * x == -1LL) x *= -1LL;
		if (x < 0) {
			x += ((-x) / b + 1LL) * b;
		}
		x %= b;
		if (x == 0) x = b;
		res = min(res, a * x);
	}

	cout << res << endl;

	return 0;
}

