vll divisor(ll x) {
    map<ll, ll> mp;
    for(ll i = 2; i * i <= x; i++) {
        while(x % i == 0) {
            mp[i]++;
            x /= i;
        }
    }
    if(x > 1) mp[x]++;
    vll ret(1, 1);
    for(auto i = mp.begin(); i != mp.end(); i++) {
        ll base = 1;
        ll size = ret.size();
        for(ll j = 1; j <= i->second; j++) {
            base *= i->first;
            for(ll k = 0; k < size; k++) {
                ret.push_back(ret[k] * base);
            }
        }
    }
    sort(ret.begin(), ret.end());
    return ret;
}

