template<class T>
std::tuple<T,T,T> ext_gcd(T a,T b){
  if(b==0){
    return {a,1,0};
  }
  auto [d,y,x] = ext_gcd(b,a%b);
  y -= a/b * x;
  return {d,x,y};
}

std::pair<int64_t,int64_t> crt1(int64_t b1,int64_t m1,int64_t b2,int64_t m2){
  auto [d,p,q] = ext_gcd(m1,m2);
  if((b2-b1)%d)return {0,-1};
  int64_t lcm_m = m1/d*m2;
  int64_t s = (b2-b1)/d;
  int64_t x = b1+s*m1*p;
  return {x,lcm_m};
}
std::vector<int64_t> divisor(int64_t n){
  std::vector<int64_t> div;
  for(int64_t p=1;p*p<=n;++p){
    if(n%p==0){
     div.push_back(p);
     if(p*p!=n)div.push_back(n/p);
    }
  }
  std::sort(div.begin(),div.end());
  return div;
}
