tuple<ll, ll, ll> ExtGcd(ll a, ll b){
	if (b == 0) return tuple<ll,ll,ll>(1LL, 0LL, a);
	ll x, y, d;
	tie(y, x, d) = ExtGcd(b, a%b);
	return tuple<ll,ll,ll>(x, y - a/b * x, d);
}

