	rep(aa,1,2*n){
		if (aa*aa>2*n)break;
		if ((2*n)%aa!=0)continue;

		ll b=(2*n)/aa;
		ll a=aa;

		ll y,z;
		tie(y,z)=crt({0,-1},{a,b});
		if (y!=0)chmin(ans,y);

		tie(y,z)=crt({0,-1},{b,a});
		if (y!=0)chmin(ans,y);
	}
	cout << ans << '\n';
}


