ll answer(ll N){
    if(__builtin_popcountll(N) == 1){
        return 2*N-1;
    }

    ll T = N;


    map<ll,ll> primes;
    for(ll i = 2; i*i <= N; i++){
        while(T%i == 0){
            primes[i]++;
            T/=i;
        }
    }
    if(primes.empty()){
        return N-1;
    }

    vector<pll> vs;
    for(auto p:primes){
        ll mul = 1;

        if(p.first == 2) mul = 2;
        while(p.second--){
            mul *= p.first;
        }
        vs.emplace_back(p.first,mul);
    }

    ll base,V; tie(base,V) = vs.back();

    ll ans = numeric_limits<ll>::max();

    while(V <= N){
        ll sum = V*(V+1)/2;

        if(sum%N == 0){
            ans = V;
            break;
        }

        V += base;
    }
    assert(ans != numeric_limits<ll>::max());
    return ans;

}
