typedef pair<i64, i64> pii;

class numberTheory{

public:
    numberTheory(){}

    pii extendedEuclid(i64 a, i64 b) { // returns x, y | ax + by = gcd(a,b)

        if(b == 0) return pii( a >= 0 ? 1 : -1 , 0LL);
        else {
            pii d = extendedEuclid(b, a % b);
            return pii(d.yy, d.xx - d.yy * (a / b));
        }
    }

    i64 modularInverse(i64 a, i64 n) {
        pair<i64,i64> ret = extendedEuclid(a, n);
        return ((ret.xx % n) + n) % n;
    }


    i64 bigMod(i64 a, i64 n , i64 m)
    {
        if(n==0) return 1 ;
        i64 ret = bigMod(a,n/2,m) ;
        ret = (ret*ret)%m ;
        if(n%2) ret = (ret*a)%m ;
        return ret ;
    }
};

i64 mulmod(i64 x , i64 y , i64 m)
{
    if( x==0 ) return 0 ;
    i64 r = (mulmod(x/2,y,m)*2)%m ;
    if( x%2 ) r = (r+y)%m ;
    return r ;
}

i64 gcd(i64 x, i64 y)
{
    if(y==0) return x ;
    return gcd( y , x%y ) ;
}

void Try(i64 x, i64 y , i64 &ans)
{
    if(y%2==0) return ;
    numberTheory nt ;

    i64 xinv = nt.modularInverse(x,y) ;
    i64 inv2 = nt.modularInverse(2,y) ;

    i64 n = x*y ;

    i64 ret = mulmod(xinv,x,n) ;
    ret = mulmod(ret,inv2,n) ;

    i64 ret1 = ret , ret2 = n-ret ;
    if(ret1==0) ret1 = n ;
    if(ret2==0) ret2 = n ;

//    printf("%lld %lld %lld %lld %lld\n",ret1,x,y, ret1%x , (2*ret1-1)%y ) ;
//    printf("%lld %lld %lld %lld %lld\n",ret2,x,y, ret2%x , (2*ret2+1)%y ) ;
//    printf("\n") ;

    ans = min( ans , min( 2*ret2 , 2*ret1-1 ) ) ;
}

i64 solve( i64 n )
{
    i64 ans = INF ;

    for(int i=1 ; i<=100 ; i++)
    {
        if( ((i*(i+1))/2)%n == 0 )
        {
            return i ;
        }
    }

    for(int i=1 ; 1LL*i*i<=n ; i++)
    {
        if(n%i !=0 ) continue ;

        if(  gcd(i,n/i) == 1 )
        {
            i64 x = i , y = (n/i) ;
            Try(x,y,ans) ;
            Try(y,x,ans) ;
        }
    }

    if(ans==INF) ans = n-1 ;
    return ans ;
}

