using namespace utils;


class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    ll N;
    bool input() {
        is >> N;
        return !!is;
    }

    vector<ll> fc(ll x){
        vector<ll> r;
        for (ll i = 1; i*i <= x; ++i) {
            if(x % i == 0){
                r.push_back(i);
                r.push_back(x);
            }
        } // end i
        return r;
    }

    vector<ll> fp(ll x){
        vector<ll> w;
        for (ll i = 2; i*i <= x; ++i) {
            if(x % i == 0){
                ll p = 1;
                while(x % i == 0){
                    x /= i;
                    p *= i;
                }
                w.emplace_back(p);
            }
        } // end i
        if(x > 1) w.emplace_back(x);
        return w;
    }

    void run();
};

void solver::run(){
    if(!input()) return;
    if(N == 1) {
        cout << 1 << endl;
        return;
    }
    if(fc(N).size() == 2){
        cout << N-1 << endl;
        return;
    }
    auto f = fc(2*N);
    ll ans = INFLL;
//    ll mod1 = 1'000'000'009;
//    ll mod0 = 1'000'000'007;
//    nv[1] = mod1;
    for (auto &&x : f) {
        auto nv = VEC(2, 2*N / x);
        nv[1] = x;
        auto v = VEC(2, 0ll);
        v[1] = x-1;
        auto s = atcoder::crt(v, nv);
        if(s.first == 0 and s.second == 0) continue;
        ll cand = s.first;
        if(cand <= 0)  continue;
        ll rem = 2*N / gcd(2*N, cand);
//        if((cand + 1) % rem == 0){
//            CHMIN(ans, cand+1);
//        }
        if((cand - 1) % rem == 0){
            CHMIN(ans, cand-1);
        }
    } // end x
    cout << ans << endl;



}

