typedef long long ll;

long long ext_gcd(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1, y = 0;
        return a;
    }
    long long x2, y2;
    long long d = ext_gcd(b, a%b, x2, y2);
    x = y2;
    y = x2 - (a / b)*y2;
    return d;
}

int main()
{
    ll n;
    cin >> n;
    if(n == 1){
        cout << 1 << endl;
        return 0;
    }
    if(n == 2){
        cout << 3 << endl;
        return 0;
    }
    ll m = n;
    vector<int> v;
    ll p = 1;
    for(ll i = 2; i * i <= n; i++){
        if(m % i == 0){
            ll s = 1;
            while(m % i == 0){
                m /= i;
                s *= i;
            }
            v.push_back(s);
            if(i == 2) p = s;
        }
    }
    if(m > 1) v.push_back(m);
    int k = v.size();
    ll ans = n - 1;
    for(int i = 0; i < (1 << k); i++){
        ll l = 1, r = 1;
        for(int j = 0; j < k; j++){
            if((i >> j) & 1) l *= v[j];
            else r *= v[j];
        }
        ll x = 1, y = 0;
        if(l > r){
            ext_gcd(l, r, x, y);
            x = abs(x);
            y = abs(y);
            if(x == 0 || y == 0){
                x += r;
                y += l;
            }
            while(true){
                if(l * x % 2 == 0){
                    if(l * x / 2 % p == 0) break;
                }
                if(l * y % 2 == 0){
                    if(l * y / 2 % p == 0) break;
                }
                x += r;
                y += l;
            }
            ans = min(ans, min(l * x, r * y));
        }
    }
    cout << ans << endl;
}

