  auto f2 = [&](ll x, ll y) {
    auto p = crt({x-1,0},{x,y});
    // cerr<<x<<" "<<y<<" "<<p<<endl;
    if (p.fi > 1) mins(ans, p.fi);
  };
  auto f = [&](ll x) {
    ll y = n/x;
    x *= 2;
    if (gcd(x,y) != 1) return;
    f1(x,y);
    f2(x,y);
  };
  for (ll i = 1; i*i <= n; ++i) {
    if (n%i == 0) {
      f(i);
      f(n/i);
    }
  }
  cout<<ans<<endl;
  return 0;
}

