const int mod = 1e9 + 7;
const int inf = INT_MAX;

vector<ll> prime_factorize(ll n) {
    vector<ll> res;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            res.emplace_back(1);
            while (n % i == 0) {
                n /= i;
                res.back() *= i;
            }
        }
    }
    if (n > 1) {
        res.emplace_back(n);
    }
    return res;
}

ll extended_euclid(ll a, ll b, ll& x, ll& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll x1, y1;
    ll d = extended_euclid(b, a % b, x1, y1);
    x = y1;
    y = x1 - y1 * (a / b);
    return d;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n; n *= 2;

    auto factor = prime_factorize(n);

    ll min_k = LLONG_MAX;
    for (int mask = 0; mask < (1 << factor.size()); mask++) {
        ll a = 1, b = 1;
        for (int i = 0; i < factor.size(); i++) {
            if (mask & (1 << i)) {
                b *= factor[i];
            } else a *= factor[i]; //p1, p2, b*p2 = a*p1 + 1 = by - ax = 1
        }
        //-a(x - k*b) + b(y - k*a) = 1, ax + by = 1
        ll x0, y0;
        extended_euclid(a, b, x0, y0);
        x0 = -x0;

        ll limit = (ll)1e18 / max(a, b);
        ll lo = -limit, hi = limit;
        while (lo < hi) {
            ll mid = lo + (hi - lo + 1) / 2;
            if (x0 - mid * b > 0 and y0 - mid * a > 0)
                lo = mid;
            else hi = mid - 1;
        }
        min_k = min(min_k, b * (y0 - lo * a) - 1);
    }
    cout << min_k << '\n';
    return 0;
}

