ll gcd(ll a, ll b) {return b ? gcd(b, a % b) : a;}
ll lcm(ll a, ll b) { return a / gcd(a, b) * b; }

// calculate ap + bq = gcd(a, b)
// return d = gcd(a, b)
ll extGcd(ll a, ll b, ll& p, ll& q) {
    if(b == 0) {
        p = 1;
        q = 0;
        return a;
    }
    ll d = extGcd(b, a % b, q, p);
    q -= a / b * p;
    return d;
}

// let return val be (r, m),
// x == r (mod. m)
// (r, m) == (0, -1) if not exist
pair<ll, ll> ChineseRem(ll b1, ll m1, ll b2, ll m2) {
    ll p, q;
    ll d = extGcd(m1, m2, p, q); // p is inv of m1/d (mod. m2/d)
    if((b2 - b1) % d != 0) return {0, -1};
    ll m = m1 * (m2 / d); // lcm of (m1, m2)
    ll tmp = (b2 - b1) / d * p % (m2 / d);
    ll r = ((b1 + m1 * tmp) % m + m) % m;
    return {r, m};
}

