		}
		ll s = 0, t = 0;
		vector<pii> crt;
		for (int j = 0; j < psz; j++) {
			if (!((i >> j) & 1)) {
				extgcd(mul, primes[j], s, t);
				s = -s;
				s %= primes[j];
				if (s < 0)s += primes[j];
				crt.pb(mp(primes[j], s));
			}
		}
		bst = min(bst, solveCrt(crt)*mul);
	}
	cout << bst << endl;
	return 0;
}

