// enum_div 約数列挙O(√N)
// 順番はバラバラ
template<typename T>
vector<pair<T,T>> enum_div(T n) {
    vector<pair<T,T>> ret;
    for (T i = 1; i * i <= n; ++i)
    {
        if (n % i == 0)
        {
            if (i * i != n)
            {
                ret.push_back({i,n/i});
            }
        }
    }
    return ret;
}

//gcd
template<typename T>
T gcd(T a, T b) {
    return b ? gcd(b, a%b) : a;
}

// ax + by = gcd(a,b)
template<typename T>
T extgcd(T a, T b, T &x, T &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    T d = extgcd(b, a%b, y, x);
    y -= a / b * x;
    return d;
}

