vector<ll> decom(ll n) {
	vector<ll> ans;
	for (ll i = 2; i * i <= n; i++) {
		if (n%i == 0) {
			ll tmp = 1;
			while (n%i == 0) {
				tmp *= i;
				n /= i;
			}
			ans.pb(tmp);
		}
	}
	if (n != 1)ans.pb(n);
	return ans;
}
ll extgcd(ll a, ll b, ll& x, ll& y) { if (b == 0) { x = 1; y = 0; return a; } else { int g = extgcd(b, a%b, y, x); y -= a / b * x; return g; } }

ll modpow(ll a, ll b, ll m) {
	if (!b)return 1;
	ll tmp = modpow(a, b >> 1, m);
	tmp *= tmp;
	tmp %= m;
	if (b & 1) {
		tmp *= a;
		tmp %= m;
	}
	return tmp;
}

ll solveCrt(vector<pii> v) {
	if (v.empty())return 1;
	ll prod = 1;
	for (pii x : v)prod *= x.first;
	ll ret = 0;
	for (pii x : v) {
		ll dv = prod / x.first;
		ret += x.second * dv * modpow(dv, x.first - 2, x.first);
	}
	return ret % prod;
}

