//ax + by = gcd(a,b)を求める. 返り値はgcd(a,b)
ll extgcd(ll a, ll b, ll &x, ll &y){
    if(b==0){
        x = 1; y = 0;
        return a;
    }
    ll d = extgcd(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

pair<ll,ll> ChineseRem(ll b1, ll m1, ll b2, ll m2){
    ll p,q;
    ll d = extgcd(m1,m2,p,q);
    if((b2-b1)%d != 0){
        return pair<ll,ll>(0,-1);
    }
    ll m = m1*(m2/d);
    ll tmp = (b2-b1)/d * p %(m2/d);
    ll r = b1+m1*tmp;
    r = (r%m + m)%m;
    return pair<ll,ll>(r,m);
}

