int main(){

    ll N;
    cin >> N;

    ll prin = 1000000000000000000;

    rep(i,1,31622778){

        if ((2*N) % i != 0) continue;
        ll a = i;
        ll b = (2*N) / i;
        if (gcd(a,b) != 1) continue;

        vector<ll> r = {0,1};
        vector<ll> m = {b,a};
        auto ans = crt(r,m);

        if (ans.second != 0){
            ll L = -1;
            ll R = inf/ans.second;
            while (R-L != 1){
                ll mid = (L+R)/2;
                ll now = ans.second*mid + ans.first;
                if (now >= 2*N || now*(now-1) >= 2*N){
                    R = mid;
                }else{
                    L = mid;
                }
            }
            //cout << ans.second << " " << R << " " << ans.first << endl;
            prin = min(prin,ans.second*R+ans.first);
        }

        r = {0,1};
        m = {a,b};
        ans = crt(r,m);
        if (ans.second != 0){
            ll L = -1;
            ll R = inf/ans.second;
            while (R-L != 1){
                ll mid = (L+R)/2;
