ll mostp(ll n){
	ll k=2;
	ll ans=-1;
	while(1){
		int s=0;
		for(ll i=k;i*i<=n;i++){
			if(n%i==0){
				k=i;//次はここから素因数かを考えればいい
				ans=max(ans,i);//最大の素因数の更新
				s=1;//自分以外の素因数があった
				n/=i;//その素因数を除いたものについてまた素因数を考える
				break;
			}
		}
		if(s==0){ans=max(ans,n);break;}
	}
	return ans;
}

