pii ext_gcd(int a, int b) {
    if (b == 0) {
        return {1, 0};
    }
    pii cur = ext_gcd(b, a % b);
    return {cur.second, cur.first - (a/b) * cur.second};
}
int gcd(int a, int b) {
    return (b == 0?a:gcd(b, a % b));
}

pii diof(int a,int b, int c) {
    int d = gcd(a, b);
    if (c % d != 0) {
        return {0, 0};
    }
    pii res = ext_gcd(a, b);
    res.first = res.first * (c/d)% (b/d);
    if (res.first < 0)res.first += b/d;
    res.second = (c - a * res.first) / b;
    return res;
}
void solve() {
    int n;
