    if (n == 2) {
        put(1);
        return;
    }
    int ans = n;
    for (int i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            int j = n / i;
            pii c = diof(i, j, 1);
            if (c.first == 0 || c.second == 0)continue;
            chkmin(ans, max(c.first * i, c.second * j) - 1);
            int t = (-c.second + i - 1) / i;
            c.first -= j * t;
            c.second += i * t;
            if (c.first == 0 || c.second == 0)continue;
            chkmin(ans, max(c.first * i, c.second * j) - 1);
        }
    }
    put(ans);
}


