            phi/=p[i].fi;
            phi*=p[i].fi-1;
        }
        ll now=b-1;
        now=(now*bin_pow(a,phi-1,b))%b;
        if (now==0)
            ans=min(ans,a*b);
        else {
            ans = min(ans, now * a);
        }
