        ll b2 = b0 - ret.quot * b1;
        a0 = a1; b0 = b1;
        a1 = a2; b1 = b2;
	}
	return {xx, a0, b0};
}

map<ll, int> factorization(ll n){
    map<ll, int> fs;
    auto sq = sqrt(n);
    for(int i = 2; i <= sq; i++){
        while(n % i == 0){
            fs[i]++;
            n /= i;
        }
    }
    if(n > 1){
        fs[n]++;
    }
    return fs;
}

