vector<pair<ll, int>> prime_factor(ll n) {
  vector<pair<ll, int>> res;
  for (ll p = 2; p*p <= n; ++p) {
    if (n % p != 0) continue;
    int num = 0;
    while (n % p == 0) { ++num; n /= p; }
    res.emplace_back(p, num);
  }
  if (n != 1) res.emplace_back(n, 1);
  return res;
}


