    n *= 2;
    ll ans = n-1;
    for (ll i=1; i*i<=n; i++) {
        if (n % i) continue;
        ll q = n / i;
        if (std::gcd(q, i) != 1) continue;
        ll x, y;
        extGCD(i, q, x, y);
        ll lcm = std::lcm(i, q);
        ll val = std::min(abs(i * x), abs(q * y));
        val %= lcm;
        amin(val, lcm - val - 1);
        if (val == 0) val = lcm;
        // std::cerr << val << ' ' << val * (val + 1) % n << std::endl;
        amin(ans, val);
    }
    std::cout << ans << '\n';
    return 0;
}

