vector<ll> divisor(ll n){
    vector<ll> res;
    for(ll i=1; i*i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n / i) res.push_back(n / i);
        }
    }
    return res;
}

void solve(){
    ll N;
    cin >> N;
    ll ans = 2 * N;
    for(auto d : divisor(2*N)){
        ll x = 2 * N / d;
        auto [y, z] = crt({0, x-1}, {d, x});
        if(y == 0 and z == 0) continue;
        if(y == 0) y += z;
        chmin(ans, y);
    }
    cout << ans << endl;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
