    }
    auto [d,y,x] = ext_gcd(b,a%b);
    y -= a/b * x;
    return {d,x,y};
  }
  std::pair<i64,i64> crt1(i64 b1,i64 m1,i64 b2,i64 m2){
    auto [d,p,q] = ext_gcd(m1,m2);
    if((b2-b1)%d)return {0,-1};
    i64 lcm_m = m1/d*m2;
    i64 s = (b2-b1)/d;
    i64 x = b1+s*m1*p;
    return {x,lcm_m};
  }
  std::pair<i64,i64> crt(std::vector<i64> const& b,std::vector<i64> const& m){
    assert(std::size(b)==std::size(m));
    i64 r = 0, lcm_m = 1;
    for(int i=0;i<std::size(b);++i){
      auto const& b_i = b[i], m_i = m[i];
      auto [d,p,q] = ext_gcd(lcm_m,m_i);
      if((b_i-r)%d)return {-1,-1};
      i64 tmp = (b_i-r)/d*p%(m_i/d);
      r += lcm_m*tmp;
      lcm_m *= m_i/d;
    }
    r = (r%lcm_m+lcm_m)%lcm_m;
    return {r,lcm_m};
  }
}

std::vector<int64_t> divisor(int64_t n){
  std::vector<int64_t> div;
  for(int64_t p=1;p*p<=n;++p){
    if(n%p==0){
     div.push_back(p);
     if(p*p!=n)div.push_back(n/p);
    }
  }
  std::sort(div.begin(),div.end());
  return div;
}

signed main(){

  ll n;
  cin>>n;
  ll ans = INF;
  for(ll x:divisor(2*n)){
    ll y = 2*n/x;
    auto[k,mod] = ate::crt1(0,x,-1,y);
    if(k>0)chmin(ans,k);
    if(k<0)chmin(ans,k+mod);
  }
  cout<<ans<<endl;

}

