tuple<ll, ll, ll> ExtGcd(ll a, ll b){
	if (b == 0) return tuple<ll,ll,ll>(1LL, 0LL, a);
	ll x, y, d;
	tie(y, x, d) = ExtGcd(b, a%b);
	return tuple<ll,ll,ll>(x, y - a/b * x, d);
}

void solve()
{
	ll n;  cin >> n;
	ll ans=INF;
	rep(aa,1,2*n){
		if (aa*aa>2*n)break;
		if ((2*n)%aa!=0)continue;

		ll b=(2*n)/aa;
		ll a=aa;
		{
			ll x,y,d;
			tie(x,y,d) = ExtGcd(a,b); //6x+10y=dの解x,y,dが得られる
			if (d!=1)continue;

			x=-x;
			if (x<=0){
				x+=b;
				y+=a;
			}
			if (y>0){
				ll k=a*x;
				chmin(ans,k);
			}

			ll k=a*x;
			chmin(ans,k);
		}
		swap(a,b);
		{
			ll x,y,d;
			tie(x,y,d) = ExtGcd(a,b); //6x+10y=dの解x,y,dが得られる
			if (d!=1)continue;

