uint64_t DynamicMod::default_mod_m = 1;

DynamicMod::DynamicMod()
	: value_m(0), mod_m(default_mod_m) {
}

DynamicMod::DynamicMod(int32_t value, uint64_t mod) 
	: DynamicMod(int64_t(value), mod) {
}

DynamicMod::DynamicMod(uint32_t value, uint64_t mod)
	: DynamicMod(uint64_t(value), mod) {
}

DynamicMod::DynamicMod(int64_t value, uint64_t mod) {
	assert(mod != 0);

	const uint64_t thres = uint64_t(1) << 63;
	if (mod >= thres) {
		// mod >= 2^63 のとき
		if (mod == thres && uint64_t(value) == thres) {
			// mod == 2^63, value = -2^63 のときは例外として 0
			value_m = 0;
		} else {
			// それ以外の場合は正ならそのまま、負なら mod を足す (キャスト注意, 規格にはあっているはず)
			value_m = value >= 0 ? uint64_t(value) : uint64_t(value) + mod;
		}
	} else {
		// mod を符号付きにキャストできるならキャストして剰余を計算
		int64_t tmp = value % int64_t(mod);
		value_m = tmp >= 0 ? tmp : mod - uint64_t(-tmp);
	}
	mod_m = mod;
}

DynamicMod::DynamicMod(uint64_t value, uint64_t mod)
	: value_m(value % mod), mod_m(mod) {
	assert(mod != 0);
}

const DynamicMod& DynamicMod::operator+() const {
	return *this;
}

DynamicMod DynamicMod::operator-() const {
	DynamicMod ret;
	ret.mod_m = mod_m;
	if (value_m == 0) {
		ret.value_m = 0;
	} else {
		ret.value_m = mod_m - value_m;
	}
	return ret;
}

DynamicMod& DynamicMod::operator++() {
	++value_m;
	if (value_m == mod_m) {
		value_m = 0;
	}
	return *this;
}

DynamicMod& DynamicMod::operator--() {
	if (value_m == 0) {
		value_m = mod_m;
	}
	--value_m;
	return *this;
}

DynamicMod DynamicMod::operator++(int dummy) {
	DynamicMod ret(*this);
	++*this;
	return ret;
}

DynamicMod DynamicMod::operator--(int dummy) {
	DynamicMod ret(*this);
	--*this;
	return ret;
}

DynamicMod& DynamicMod::operator+=(const DynamicMod& right) {
	if (!hasSameMod(*this, right)) throw std::runtime_error("not compatible with different mods");

	if (mod_m - value_m <= right.value_m) {
		value_m -= mod_m;
	}
	value_m += right.value_m;
	return *this;
}

DynamicMod& DynamicMod::operator-=(const DynamicMod& right) {
	if (!hasSameMod(*this, right)) throw std::runtime_error("not compatible with different mods");

	if (value_m < right.value_m) {
		value_m += mod_m;
	}
	value_m -= right.value_m;
	return *this;
}

DynamicMod& DynamicMod::operator*=(const DynamicMod& right) {
	if (!hasSameMod(*this, right)) throw std::runtime_error("not compatible with different mods");
	*this = multiply(*this, right);
	return *this;
}

bool DynamicMod::hasSameMod(const DynamicMod& a, const DynamicMod& b) {
	return a.mod_m == b.mod_m;
}

DynamicMod DynamicMod::add(const DynamicMod& a, const DynamicMod& b) {
	if (!hasSameMod(a, b)) throw std::runtime_error("not compatible with different mods");

	DynamicMod ret(a);
	ret += b;
	return ret;
}

DynamicMod DynamicMod::subtract(const DynamicMod& a, const DynamicMod& b) {
	if (!hasSameMod(a, b)) throw std::runtime_error("not compatible with different mods");

	DynamicMod ret(a);
	ret -= b;
	return ret;
}

DynamicMod DynamicMod::multiply(const DynamicMod& a, const DynamicMod& b) {
	if (!hasSameMod(a, b)) throw std::runtime_error("not compatible with different mods");

	auto multiply32 = [](uint64_t a, uint64_t b, uint64_t mod) -> uint64_t {
		return a * b % mod;
	};

	auto multiply64 = [](uint64_t a, uint64_t b, uint64_t mod) -> uint64_t {
		auto assignAdd = [mod](uint64_t& a, uint64_t b) -> void {
			if (mod - a <= b) {
				a -= mod;
			}
			a += b;
		};

		uint64_t product = 0;
		uint64_t addend = a;
		uint64_t multiplier = b;
		while (multiplier > 0) {
			if (multiplier & 1) {
				assignAdd(product, addend);
			}
			assignAdd(addend, addend);
			multiplier >>= 1;
		}
		return product;
	};

	const uint64_t threshold = uint64_t(1) << 32;
	const uint64_t mod = a.mod_m;
	DynamicMod ret;
	if (mod < threshold) {
		ret.value_m = multiply32(a.value_m, b.value_m, mod);
	} else {
		ret.value_m = multiply64(a.value_m, b.value_m, mod);
	}
	ret.mod_m = mod;
	return ret;
}

/* bx = a (mod m) を満たす x の条件を与える (引数と戻り値の mod は一致するとは限らない) */
DynamicMod DynamicMod::divide(const DynamicMod& a, const DynamicMod& b) {
	if (!hasSameMod(a, b)) throw std::runtime_error("not compatible with different mods");
	if (b.getValue() == 0) throw std::runtime_error("division by zero");

	const uint64_t va = a.value_m;
	const uint64_t vb = b.value_m;
	const uint64_t mod = a.mod_m;

	const uint64_t gcd = ::gcd(vb, mod);
	if (va % gcd != 0) throw std::runtime_error("no solution");

	auto pair = extendedGcdUnsigned(vb, mod);
	return (va / gcd) * DynamicMod(pair.first, mod / gcd);
}

int DynamicMod::compare(const DynamicMod& a, const DynamicMod& b) {
	if (a.mod_m < b.mod_m) return -1;
	if (a.mod_m > b.mod_m) return 1;
	if (a.value_m < b.value_m) return -1;
	if (a.value_m > b.value_m) return 1;
	return 0;
}

/* mod_m must be a prime. */
DynamicMod DynamicMod::inverse() const {
	assert(value_m != 0);
	return power(mod_m - 2);
}

DynamicMod DynamicMod::power(uint64_t exp) const {
	DynamicMod product(1, mod_m);
	DynamicMod factor(*this);
	while (exp > 0) {
		if (exp & 1) {
			product *= factor;
		}
		factor *= factor;
		exp >>= 1;
	}
	return product;
}

uint64_t DynamicMod::getValue() const {
	return value_m;
}

uint64_t DynamicMod::getMod() const {
	return mod_m;
}

/* 中国剰余定理により a と b の条件に共通して当てはまる条件を求める O(log(mod)) */
/* mod がオーバーフローしたとき mod = 0 にすることも考えている */
DynamicMod DynamicMod::conjunction(const DynamicMod& a, const DynamicMod& b) {
	/* 後の計算の都合上 a.value_m <= b.value_m としておく */
	if (a.value_m > b.value_m) return conjunction(b, a);

	const uint64_t ma = a.mod_m;
	const uint64_t mb = b.mod_m;
	const uint64_t va = a.value_m;
	const uint64_t vb = b.value_m;

	const uint64_t gcd = ::gcd(ma, mb);
	const uint64_t lcm = ma / gcd * mb;
	const uint64_t diff = vb - va;

	/* 例外ではなく mod_m == 0 のオブジェクトを返すなども考えている */
	if (diff % gcd != 0) throw std::runtime_error("no solution");

	/* 方程式 ma * x - mb * y = gcd の解を求める */
	auto pair = extendedGcdUnsigned(ma, mb);
	DynamicMod x(pair.first, mb / gcd);			// mod に注意

	/* 答えは va + ma * (diff / gcd) * x となる */
	x *= DynamicMod(diff / gcd, x.mod_m);
	return DynamicMod(va + ma * x.value_m, lcm);
}

/* 中国剰余定理により複数の条件に共通して当てはまるものを求める */
DynamicMod DynamicMod::conjunction(const std::vector<DynamicMod>& values) {
	DynamicMod product(0, 1);
	for (const DynamicMod& value : values) {
		product = conjunction(product, value);
	}
	return product;
}

/* mod の初期値を設定 */
void DynamicMod::setDefaultMod(uint64_t mod) {
	assert(mod != 0);
	default_mod_m = mod;
}

DynamicMod operator+(const DynamicMod& left, const DynamicMod& right) {
	return DynamicMod::add(left, right);
}

DynamicMod operator-(const DynamicMod& left, const DynamicMod& right) {
	return DynamicMod::subtract(left, right);
}

DynamicMod operator*(const DynamicMod& left, const DynamicMod& right) {
	return DynamicMod::multiply(left, right);
}

bool operator==(const DynamicMod& left, const DynamicMod& right) {
	return DynamicMod::compare(left, right) == 0;
}

bool operator!=(const DynamicMod& left, const DynamicMod& right) {
	return DynamicMod::compare(left, right) != 0;
}

bool operator<(const DynamicMod& left, const DynamicMod& right) {
	return DynamicMod::compare(left, right) < 0;
}

bool operator<=(const DynamicMod& left, const DynamicMod& right) {
	return DynamicMod::compare(left, right) <= 0;
}

bool operator>(const DynamicMod& left, const DynamicMod& right) {
	return DynamicMod::compare(left, right) > 0;
}

bool operator>=(const DynamicMod& left, const DynamicMod& right) {
	return DynamicMod::compare(left, right) >= 0;
}

