//拡張ユークリッド
//ax+by=gcd(a,b)の解
ll extgcd(ll a,ll b,ll &x,ll &y){
	ll d=a;
	if(b){
		d=extgcd(b,a%b,y,x);
		y-=(a/b)*x;
	}else{
		x=1,y=0;
	}
	return d;
}

//中国剰余定理
//https://qiita.com/drken/items/ae02240cd1f8edfc86fd
//リターン値 (r,m) x¥equiv r (mod m)
P CRT (const vector<ll> &b,const vector<ll> &m){
	ll r=0,M=1;
	rep(i,b.size()){
		ll p,q;
		ll d=extgcd(M,m[i],p,q);
		if((b[i]-r)%d) return P(0,-1);
		ll tmp=(b[i]-r)/d*p%(m[i]/d);
		r+=M*tmp;
		M*=m[i]/d;
	}
	return P((r%M+M)%M,M);
}

