class BSumIsMultiple {
public:
    void solve() {
        ll n = in.readLong();

        if (n == 1) {
            out.printLine(1);
            return;
        }
        li answer = numeric_limits<ll>::max();
        auto d = divisors(n);
        for (unsigned i : range(1 << (d.size()))) {
            ll d1 = 1;
            ll d2 = 1;
            for (int j : range(d.size())) {
                if (isSet(i, j)) {
                    d1 *= power(d[j].first, d[j].second);
                } else {
                    d2 *= power(d[j].first, d[j].second);
                }
            }
            if (d1 % 2 == 0) {
                d1 *= 2;
            }
            if (d2 % 2 == 0) {
                d2 *= 2;
            }
            mod = d1;
            bigmod times = bigmod(d2).inverse();
            li realTimes = times.n;
            if (realTimes <= 1) {
                realTimes += d1;
            }
            li cur = realTimes * d2 - 1;
            minim(answer, cur);
        }
        out.printLine(ll(answer));
    }
};


