    if (b == 0) {
        x = 1, y = 0;
        return a;
    } else {
        long long r = exgcd(b, a % b, x, y);
        long long t = x;
        x = y;
        y = t - a / b * y;
        return r;
    }
}

int main() {
    long long n;
    cin >> n;
    if (n == 1) printf("1\n"), exit(0);
    long long ans = LLONG_MAX;
    if (n & 1) ans = n - 1;
    else ans = 2 * n - 1;
    n *= 2;
    auto chk = [&](long long x) {
        long long y = n / x;
        if (x == 1 || y == 1 || __gcd(x, y) > 1)
            return;
        long long t1, t2;
        assert(exgcd(x, y, t1, t2) == 1);
        t1 *= -1, t2 *= -1;
        if (t1 > 0) ans = min(ans, t1 * x);
        if (t2 < 0) ans = min(ans, -t2 * y - 1);
    };
    for (long long i = 1; i * i <= n; i++) {
        if (!(n % i)) {
            chk(i), chk(n / i);
        }
    }
    cout << ans << endl;
    return 0;
}

