// floor(整数の平方根)を返す with めぐる式二分探索
// llの上限までok（llの上限:9223372036854775807）
// llの上限値付近で、766ms/100万回で早い。値小さければニュートン法のが早い

// 今回は val*val が n を超えない ことが true の条件
bool isOK(ll val, ll key) {
  if (val * val <= key) return true;
  else return false;
}

ll ll_sqrtf(ll key) {
  ll ng = 3037000500; //「index = 0」が条件を満たすこともあるので、初期値は -1
  ll ok = 0;
  // ngの初期値は「決して条件が満たされない値」に設定
  // 3037000500 は ceil(llの上限値のsqrt) のため、条件を満たすことはない
  // okの初期値は「常に条件が満たされる値」に設定

  /* ok と ng のどちらが大きいかわからないことを考慮 */
  while (abs(ok - ng) > 1) {
    ll mid = (ok + ng) / 2;

    if (isOK(mid, key)) ok = mid;
    else ng = mid;
  }
  return ok;
}

