void solve() {
	ll n;
	cin >> n;
	n *= 2;
	ll esh = n;
	vector <ll> v;
	map <ll, int> cnt;
	for (ll i = 2; i * i <= n; ++i) {
		if (n % i == 0)
			v.push_back(i);
		while (n % i == 0) {
			++cnt[i];
			n /= i;
		}
	}	
	if (n > 1) {
		++cnt[n];
		v.push_back(n);
	}
	int sz = v.size();
	ll res = INF;
	for (int mask = 0; mask < (1 << sz); ++mask) {
		ll x = 1, y = 1;
		for (int i = 0; i <	sz; ++i) {
			if ((mask >> i) & 1) {
				for (int j = 0; j < cnt[v[i]]; ++j) x *= v[i];
			}
			else {
				for (int j = 0; j < cnt[v[i]]; ++j) y *= v[i];
			}
		}
		for (ll j = 1; j < min(x, y); ++j) {
			if ((j * x + 1) % y == 0) {
				res = min(res, j * x);
			}
			if ((j * x - 1) % y == 0) {
				res = min(res, j * x - 1);
			}
		}
		swap(x, y);
		for (ll j = 1; j < min(x, y); ++j) {
			if ((j * x + 1) % y == 0) {
				res = min(res, j * x);
			}
			if ((j * x - 1) % y == 0) {
				res = min(res, j * x - 1);
			}
		}
	}
	cout << res;
}

