constexpr long long safe_mod(long long x, long long m) {
    x %= m;
    if (x < 0) x += m;
    return x;
}

constexpr std::pair<long long, long long> inv_gcd(long long a, long long b) {
    a = safe_mod(a, b);
    if (a == 0) return {b, 0};

    // Contracts:
    // [1] s - m0 * a = 0 (mod b)
    // [2] t - m1 * a = 0 (mod b)
    // [3] s * |m1| + t * |m0| <= b
    long long s = b, t = a;
    long long m0 = 0, m1 = 1;

    while (t) {
        long long u = s / t;
        s -= t * u;
        m0 -= m1 * u;  // |m1 * u| <= |m1| * s <= b

        // [3]:
        // (s - t * u) * |m1| + t * |m0 - m1 * u|
        // <= s * |m1| - t * u * |m1| + t * (|m0| + |m1| * u)
        // = s * |m1| + t * |m0| <= b

        auto tmp = s;
        s = t;
        t = tmp;
        tmp = m0;
        m0 = m1;
        m1 = tmp;
    }
    // by [3]: |m0| <= b/g
    // by g != b: |m0| < b/g
    if (m0 < 0) m0 += b / s;
    return {s, m0};
}

i64 gcd(i64 a, i64 b) {
  if(b == 0) return a;
  return gcd(b, a % b);
}

int main() {
  i64 N;
  cin >> N;
  i64 ans = N * 2;
  N *= 2;
  for(i64 p = 1; p * p <= N; p++) {
    if(N % p == 0) {
      i64 q = N / p;
      if(gcd(p, q) != 1) continue;
      // 2kp * (2kp + 1) / 2
      // 2kp + 1 === 0 (mod q)
      // -2kp === 1
      i64 tk = inv_gcd(p, q).second;
      if(tk != 0 && !(p == 1 && tk == 1)) {
        ans = std::min(ans, tk * p);
      }
      tk = inv_gcd(-p, q).second;
      if(tk != 0) {
        ans = std::min(ans, tk * p);
      }
      std::swap(p, q);
      tk = inv_gcd(p, q).second;
      if(tk != 0) {
        ans = std::min(ans, tk * p);
      }
      tk = inv_gcd(-p, q).second;
      if(tk != 0) {
        ans = std::min(ans, tk * p);
      }
      std::swap(p, q);
    }
  }
  cout << ans << endl;
}

