ll exgcd(ll a, ll b, ll &x, ll &y){
	if(!b){
		x = 1; y = 0;
		return a;
	}
	ll g = exgcd(b, a % b, y, x);
	y -= a / b * x;
	return g;
}

inline void solve(ll a, ll b){ // min x satisfying ax - by = 1, x, y \in \Z, a < b
	ll x, y, g = exgcd(a, b, x, y);
//	printf("a = %lld b = %lld x = %lld y = %lld\n", a, b, x, y);
	if(g != 1)
		return;
	// now we get ax + by = 1
	y = -y;
	// now we get ax - by = 1
	if(y <= 0){
		ll k = (abs(y) + a / g) / (a / g);
		y += k * (a / g);
		x -= k * (b / g);
	}
	if(x <= 0)
		return;
	ll k = x / (b / g);
	x -= k * (b / g);
	y += k * (a / g);
	if(log10(a) + log10(x) <= 17 && (ans == -1 || ans > a * x - 1))
		ans = a * x - 1;
	return;
}

