	n <<= 1;
	for(ll a = 1; 1ll * a * a <= n; ++a) if(!(n % a)){
		ll b = n / a;
		solve(a, b);
		if(a != b)
			solve(b, a);
	}
	printf("%lld\n", ans);
	return 0;
}

