class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    ll N;
    bool input() {
        is >> N;
        return !!is;
    }

    vector<ll> fc(ll x){
        vector<ll> r;
        for (ll i = 1; i*i <= x; ++i) {
            if(x % i == 0){
                r.push_back(i);
                r.push_back(x);
            }
        } // end i
        return r;
    }

    ll gcd(ll a, ll b){
        if(b == 0) return a;
        return gcd(b, a%b);
    }


    void run();
};

void solver::run(){
    if(!input()) return;
    if(N == 1) {
        cout << 1 << endl;
        return;
    }
    auto fv = fc(2*N);
    ll ans = INFLL;
    for (auto &&x : fv) {
        ll a = 2*N/x;
        if(gcd(a, x) != 1) continue;
        auto r = VEC(2, 0ll);
        r[1] = x-1;
        auto m = VEC(2, 0ll);
        m[0] = a; m[1] = x;
        auto s = atcoder::crt(r, m);

        if(s.first != 0){
            CHMIN(ans, s.first);
        }
        r[0] = a-1; r[1] = 0;
        s = atcoder::crt(r, m);

        if(s.first != 0){
            CHMIN(ans, s.first);
        }
    } // end x
    cout << ans << endl;

}

