using namespace std;
const long long INF = (1ull<<63) - 1;

long long extgcd(long long a, long long b, long long &x, long long &y) {
	x = 1; y = 0;
	long long u = 0, v = 1;
	while (b != 0) {
		long long r = a % b, q = a / b;
		a = b; b = r;
		long long nu = x - q*u, nv = y - q*v;
		x = u; y = v;
		u = nu; v = nv;
	}
	return a;
}

pair<long long, long long> crt(const vector<long long> &r, const vector<long long> &m) {
	long long x = 0, l = 1;
	for (int i = 0; i < r.size(); i++) {
		long long m0 = l, m1 = m[i];
		long long r0 = x, r1 = r[i] % m1;
		if (r1 < 0) r1 += m1;
		if (m0 < m1) {
			swap(m0, m1);
			swap(r0, r1);
		}
		long long k0, k1;
		const long long g = extgcd(m0, m1, k0, k1);
		if ((r1 - r0) % g != 0) return {0, -1};
		const long long m1_g = m1 / g;
		x = (r1 - r0) / g % m1_g * (k0 % m1_g) % m1_g * m0 + r0;
		l = m0 * m1_g;
		if (x < 0) x += l;
	}
	return {x, l};
}

vector<pair<long long, int>> prime_factorization(long long n) {
	vector<pair<long long, int>> v;
	for (long long i = 2; i * i <= n; ++i) {
		int e = 0;
		while (n % i == 0) {
			++e;
			n /= i;
		}
		if (e != 0) v.emplace_back(i, e);
	}
	if (n != 1) v.emplace_back(n, 1);
	return v;
}

long long pow(long long a, long long n) {
	long long res = 1;
	while (n > 0) {
		if (n & 1) res = (res * a);
		n >>= 1;
		a = (a * a);
	}
	return res;
}

int main() {
	long long n;
	cin >> n;
	auto v = prime_factorization(2*n);
	vector<long long> r(v.size()), m(v.size());
	for (int i = 0; i < m.size(); i++) {
		m[i] = pow(v[i].first, v[i].second);
	}
	long long ans = INF;
	for (int bits = 0; bits < (1<<r.size()); bits++) {
		bitset<32> t(bits);
		for (int i = 0; i < r.size(); i++) {
			r[i] = t[i] ? 0 : m[i]-1;
		}
		long long now = crt(r, m).first;
		if (now == 0) now = 2*n;
		ans = min(ans, now);
	}
	cout << ans << endl;
	return 0;
}

