long long int  euc(long long int a, long long int b, long long int &x, long long int &y) {
  long long int xx = y = 0; long long int yy = x = 1;
  while (b) {
    long long int q = a / b; long long int t = b; b = a % b;
    a = t; t = xx; xx = x - q * xx; x = t;
    t = yy; yy = y - q * yy; y = t;
  }
  return a;
}

long long int mod_inverse(long long int a, long long int n) {
  long long int x, y;
  if (euc(a,n,x,y) > 1) return -1;
  return ((x % n) + n) % n;
}

