template<typename T>
class prime {
    T n;
public:
    prime(T n) : n(n) {}

    map<T, int> factorlist() {
        if (n == 1) return {};
        T nn = n;
        map<T, int> ret;
        for (int i = 2; (ll) i * i <= n; i++) {
            if (nn % i != 0) continue;
            int cnt = 0;
            while (nn % i == 0) {
                cnt++;
                nn /= i;
            }
            ret[i] = cnt;
        }
        if (nn != 1) ret[nn]++;
        return ret;
    }

    vector<T> unique_factor() {
        map<T, int> m = factorlist();
        vector<T> ret;
        for (auto p : m) ret.pb(p.first);
        return ret;
    };

    bool isPrime() {
        auto v = factorlist();
        return v.size() == 1 && v.begin()->second == 1;
    }

    int count_divisor() {
        int ret = 1;
        map<int, int> fl = factorlist(n);
        for (auto p : fl) ret *= p.second + 1;
        return ret;
    };

    vector<T> enum_divisors() {
        vector<T> res;
        for (T i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                res.pb(i);
                if (n / i != i) res.pb(n / i);
            }
        }
        sort(all(res));
        return res;
    }
};

long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

