	vector<ll> divisor;

	ll i = 1;
	for (; i * i <= n; i++) if (n % i == 0) divisor.push_back(i);
	i--;
	if (i * i == n) i--;
	for (; i >= 1; i--) if (n % i == 0) divisor.push_back(n / i);

	return divisor;
}

int main() {
	ll N;
	cin >> N;
	N *= 2;

	ll ans = longINF;
	auto div = find_divisor(N);

	for (auto x : div) {
		ll y = N / x;
		// k(k + 1) \equiv 0 (mod. N)
		// x | k, y | k + 1
		// k \equiv 1 (mod. x)
		// k \equiv -1 (mod. y)
		std::vector<ll> b(2), m(2);
		b[0] = 0; m[0] = x;
		b[1] = y - 1; m[1] = y;
		auto res = atcoder::crt(b, m);
		if (res.second == 0) continue;

		ll p = res.first;
		if (p == 0) p += x * y;
		chmin(ans, p);
	}

	cout << ans << endl;
	return 0;
}

