using namespace std;
typedef long long ll;

vector<bool> furui_bool(ll n) {
  vector<bool> fu(n + 1, 1);
  fu.at(0) = 0; fu.at(1) = 0;
  for (ll i=2; i <= n/2 + 1; i++) {
    if (fu.at(i) == 1) {
      ll j = 2 * i;
      while (j <= n) {
        fu.at(j) = 0;
        j += i;
      }
    }
  }
  return fu;
}

vector<ll> prime_fac(ll n, ll &mx) {
  ll sq = sqrt(n);
  vector<ll> pr(sq + 1, 0);
  vector<bool> fu = furui_bool(sq + 2);
  for (ll i=2; i <= sq; i++) {
    if (fu.at(i)) {
      while (n % i == 0) {
        n /= i;
        mx = i;
        pr.at(i)++;
      }
    }
  }
  if (n > 1) {
    mx = n;
  }
  return pr;
}

int main(){
  ll n,ans=(ll)1e18;
  cin>>n;
  if(n%2==0)n*=2;
  ll mx=1;
  vector<ll> facpow(0);
  vector<ll> out = prime_fac(n,mx);
  for(ll i=2; i <= sqrt(n); i++){
    if(out.at(i) >= 1)facpow.push_back((ll)pow(i,out.at(i)));
  }
  if(mx>sqrt(n))facpow.push_back(mx);
  for(ll i=0;i<(1<<facpow.size());i++){
    ll d1=1;
    for(ll j=0;j<(ll)facpow.size();j++){
      if((i&(1<<j)))d1*=facpow[j];
    }
    ll d2=n/d1;
    vector<ll> rem={0,-1},div={d1,d2};
    pair<ll,ll> preans=atcoder::crt(rem,div);
    if(preans.first==0)preans.first=preans.second;
    ans=min(ans,preans.first);
  }
  cout<<ans<<endl;
}

