    ll a=1, b=1;
    rep(j, ps) {
      if(choose[j]) a *= P[j];
      else b *= P[j];
    }

    chmin(ans, extended_euclidian(a, b));
    chmin(ans, extended_euclidian(b, a));
  }
  cout << ans << newl;
  return 0;
}

