void primefactor(ll n)
{
    ll b=1;
    while (n % 2 == 0)  
    {  
        b*=2ll;
        n = n/2;  
    }  
    if(b>1)
        vec.pb(b);
    b=0;
    for (ll i = 3; i*i <= n; i = i + 2)  
    {   
        b=1;
        while (n % i == 0)  
        {  
            b*=i;
            n = n/i;  
        }  
        if(b>1)
            vec.pb(b);
    }  
    if (n > 2)  
        vec.pb(n);
}

ll gcd(ll a, ll b, ll& x, ll& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll x1, y1;
    ll d = gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - y1 * (a / b);
    return d;
}

bool fs(ll a, ll b, ll c, ll &x0, ll &y0, ll &g) {
    g = gcd(abs(a), abs(b), x0, y0);
    if (c % g) {
        return false;
    }

    x0 *= c / g;
    y0 *= c / g;
    if (a < 0) x0 = -x0;
    if (b < 0) y0 = -y0;
    return true;
}

