//ax+by=gcd(a,b)の解
ll extgcd(ll a,ll b,ll &x,ll &y){
	ll d=a;
	if(b){
		d=extgcd(b,a%b,y,x);
		y-=(a/b)*x;
	}else{
		x=1,y=0;
	}
	return d;
}

//中国剰余定理
//https://qiita.com/drken/items/ae02240cd1f8edfc86fd
//リターン値 (r,m) x¥equiv r (mod m)
pair<long long, long long> ChineseRem(const vector<long long> &b, const vector<long long> &m) {
  long long r = 0, M = 1;
  for (int i = 0; i < (int)b.size(); ++i) {
    long long p, q;
    long long d = extgcd(M, m[i], p, q); // p is inv of M/d (mod. m[i]/d)
    if ((b[i] - r) % d != 0) return make_pair(0, -1);
    long long tmp = (b[i] - r) / d * p % (m[i]/d);
    r += M * tmp;
    M *= m[i]/d;
  }
  return make_pair((r%M+M)%M, M);
}

P CRT (const vector<ll> &b,const vector<ll> &m){
	ll r=0,M=1;
	rep(i,b.size()){
		ll p,q;
		ll d=extgcd(M,m[i],p,q);
		if((b[i]-r)%d!=0) return P(0,-1);
		ll tmp=(b[i]-r)/d*p%(m[i]/d);
		r+=M*tmp;
		M*=m[i]/d;
	}
	return P((r%M+M)%M,M);
}

//約数列挙
template <class T>
vector<T> divisor(T x){
    vector<T> res;
    for(T i=1;i*i<=x;i++){
        if(x%i==0){
            res.push_back(i);
            if(i!=x/i){
                res.push_back(x/i);
            }
        }
    }
    return res;
}

