    } else {
        return a * b;
    }
}

void solve() {
    ll n;
    cin >> n;
    if (n == 2) {
        p(3);
        return;
    }
    vec v;
    for(int i=2;i*i<=n;i++){
        ll res = 1ll;
        if (n % i == 0) {
            while(n % i == 0) {
                res *= i;
                n /= i;
            }
        }
        if (i == 2) res *= 2;
        if (res != 1ll) v.pb(res);
    }
    if (n != 1) v.pb(n);
    ll m = v.size();
    ll mbit = (1ll << m);
    ll ans = INF;
    for(int i=0;i<mbit;i++){
        ll ka = 1ll, kb = 1ll;
