int euclid(int a, int b, int& x, int& y) {
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}
	int x1, y1;
	int d = euclid(b, a % b, x1, y1);
	x = y1;
	y = x1 - y1 * (a / b);
	return d;
}

int chinese(int a, int m, int b, int n) { //x = a % m, x = b % n, gcd(m, n) = 1
	int x, y;
	euclid(m, n, x, y);
	int ret = a * (y + m) % m * n + b * (x + n) % n * m;
	if (ret >= m * n)
		ret -= m * n;
	return ret;
}

