	vector<pii> div;
	int tmp = 2 * n;
	for(int i = 2; i * i <= tmp; i++) {
		if(tmp % i == 0) {
			int cur = 1;
			while(tmp % i == 0) {
				tmp /= i;
				cur *= i;
			}
			div.pb({cur, i});
		}
	}
	if(tmp > 1) {
		div.pb({tmp, tmp});
	}
	int sz = div.size();
	int ans = 2 * n;
	for(int mask = 1; mask < (1LL << sz); mask++) {
		int x = 1, y = 1;
		for(int i = 0; i < sz; i++) {
			if(mask & (1LL << i)) {
				x *= div[i].fi;
			}
			else {
				y *= div[i].fi;
			}
		}
		if(y != 1) {
			ans = min(ans, chinese(0, x, y - 1, y));
		}
	}
	cout << ans;

	return 0;
}

