class BSumIsMultiple {
    class Solver {
    public:
        io::input_reader in;
        io::output_writer out;

        Solver(std::istream &in, std::ostream &out) : in(in), out(out) {}

        void solve() {
            // <code here>
            ll n;
            in >> n;
            ll cur_rem = 0;
            ll cur_k = 1;

            auto sum = [](ll k) { return (k * (k + 1)) / 2; };
            auto rsum = [&](ll l, ll r) { return sum(r) - sum(l - 1); };

            do {
                ll need_to_complete_round = n - cur_rem;
                ll l = cur_k, r = cur_k + need_to_complete_round / cur_k;
                while (l < r) {
                    ll m = (l + r) / 2;
                    if (rsum(cur_k, m) >= need_to_complete_round) {
                        r = m;
                    } else {
                        l = m + 1;
                    }
                }
                cur_rem += rsum(cur_k, l);
                cur_k = l + 1;
            } while ((cur_rem %= n) != 0);

            // </code here>
            out.println(cur_k - 1);
        }
    };

public:
    static void solve(std::istream &in, std::ostream &out) {
        Solver(in, out).solve();
    }
};

int main() {
	std::ios_base::sync_with_stdio(false), cin.tie(0);
	BSumIsMultiple solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

