struct Ret {
  ll x;
  ll y;
  ll d;

  Ret (ll x = -1, ll y = -1, ll d = -1) {
    this->x = x;
    this->y = y;
    this->d = d;
  }
};

Ret extgcd(ll a, ll b) {
  if (b == 0) {
    return Ret(1LL, 0LL, a);
  } else {
    Ret ret = extgcd(b, a % b);

    return Ret(ret.y, ret.x - (a / b) * ret.y, ret.d);
  }
}

map<ll, ll> prime_division(ll n) {
  map<ll, ll> res;

  for (ll p = 2; p <= sqrt(n); ++p) {
    if (n % p != 0) continue;

    while (n % p == 0) {
      ++res[p];
      n /= p;
    }
  }

  if (n != 1) {
    res[n] = 1;
  }

  return res;
}

bool is_prime(ll n) {
  if (n <= 1) return false;

  for (ll p = 2; p <= sqrt(n); ++p) {
    if (n % p == 0) return false;
  }

  return true;
}

int main() {
  ll N;
  cin >> N;

  if (is_prime(N)) {
    if (N == 1) {
      cout << 1 << endl;
    } else if (N == 2) {
      cout << 3 << endl;
    } else {
      cout << N - 1 << endl;
    }
  } else {
    map<ll, ll> primes = prime_division(2 * N);

    if (primes.size() == 1) {
      cout << 2 * N - 1 << endl;
      return 0;
    }

    ll cnt = primes.size();
    ll ans = LLONG_MAX;
    ll min_val = LLONG_MAX;
    vector<ll> values;

    for (auto it : primes) {
      ll val = 1;
      for (int i = 0; i < it.second; ++i) {
        val *= it.first;
      }
      values.push_back(val);
    }

    for (int mask = 0; mask < (1 << cnt); ++mask) {
      ll a = 1;
      ll b = 1;

      for (int i = 0; i < cnt; ++i) {
        if (((mask >> i) & 1) == 0) {
          a *= values[i];
        } else {
          b *= values[i];
        }
      }

      Ret ret = extgcd(a, b);
      ll v1 = a * abs(ret.x);
      ll v2 = b * abs(ret.y);
      ll s = v1 * v2;

      if (s > 0 && min_val > s) {
        min_val = s;
        ans = min(v1, v2);
      }
    }

    cout << ans << endl;
  }

  return 0;
}

