    if(v[0] % 2 == 0){
        ans = n * 2 - 1;
    }
    for(int i = 0; i < (1 << k); i++){
        ll l = 1, r = 1;
        for(int j = 0; j < k; j++){
            if((i >> j) & 1) l *= v[j];
            else r *= v[j];
        }
        if(l % 2) r *= 2;
        else l *= 2;
        ll x = 1, y = 0;
        if(l > r){
            ext_gcd(l, r, x, y);
            x = abs(x);
            y = abs(y);
            if(x == 0 || y == 0){
                x += r;
                y += l;
            }
            ans = min(ans, min(l * x, r * y));
        }
    }
    cout << ans << endl;
}

