  REP(i, M) {
    REP(j, div[i].sc)
      pp[i] *= div[i].fs;
  }
  int64 res = N-1;
  REP(i, 1 << M) {
    int64 p = 1, q = 1;
    REP(j, M) {
      if (i >> j & 1)
        p *= pp[j];
    }
    q = N / p;
    PLL ret = extgcd(p, q);
    if (ret.fs == 0 || ret.sc == 0) continue;

    chmin(res, abs(ret.fs * p));
    chmin(res, abs(ret.sc * q));
	}
	cout << res << endl;
}

