long long mygcd(long long a, long long b, long long& x, long long& y) {
  long long d = a;
  if (b != 0) {
    d = mygcd(b, a % b, y, x);
    y -= (a / b) * x;
  } else {
    x = 1;
    y = 0;
  }
  return d;
}

