long long calc(long long a, long long b) {
  long long x, y, g;
  g = mygcd(a, b, x, y);
  if (g != 1) return n;
  if (x > 0) {
    swap(a, b);
    swap(x, y);
  }
  long long num = -x / b, res = n;
  x %= b;
  y -= a * num;
  if (x == 0) {
    x -= b;
    y += a;
  }
  res = min(res, -a * x * g);
  y -= a;
  x += b;
  if (y == 0) {
    x += b;
    y -= a;
  }
  res = min(res, -b * y * g);
  return res;
}

