// returns d = gcd(a,b); finds x,y such that d = ax + by
ll extended_euclid(ll a, ll b, ll &x, ll &y) {
  ll xx = y = 0; ll yy = x = 1;
  while (b) {
    ll q = a / b; ll t = b; b = a % b;
    a = t; t = xx; xx = x - q * xx; x = t;
    t = yy; yy = y - q * yy; y = t;
  }
  return a;
}

ll mod(ll a, ll b) {
  return ((a % b) + b) % b;
}

ll mod_inverse(ll a, ll n) {
  ll x, y;
  ll d = extended_euclid(a, n, x, y);
  if(d > 1) return -1;
  return mod(x, n);
}

void upd(ll& ans, ll x, ll y, ll a, ll n) {
  if (__gcd(x, y) != 1) return;
  ll l = mod_inverse((1ll << (a+1)) * x, y);
  if (l <= 0) return;
  ans = min(ans, l * x * (1ll << (a+1)) - 1);
  l = !l ? l : y - l;
  ans = min(ans, l * x * (1ll << (a+1)));
}

