ll n,ans;
ll p[N],tot,c[1<<16];

void exgcd(ll &x,ll &y,ll a,ll b) {
	if(!a) {x=0; y=1; return ;}
	exgcd(y,x,b%a,a); x -= b/a*y;
}
ll inv(ll a,ll b) {
	a=(2*b-a)%b;
	ll x,y; exgcd(x,y,a,b);
	return (x%b+b)%b;
}

void div(ll x) {
	for(ll i=2;i*i<=x;i++) if(x%i == 0) {
		p[tot]=x;
		while(x%i==0) x/=i;
		p[tot++] /= x;
	}
	if(x>1) p[tot++]=x;
}

