	qr(n); div(n*2); c[0]=1;
	for(int i=0;i<tot;i++) c[1<<i]=p[i];
	if(n==1) puts("1"),exit(0);
	if(n&1) ans=n-1;
	else ans=n;
	for(int i=1;i+1<(1<<tot);i++) {
		c[i]=c[i&(i-1)]*c[i&(-i)];
		ll x=c[i],y=2*n/x;
		ans=min(ans,x*inv(x,y));
	}
	pr2(ans);
}

