lnt ipow(lnt v,lnt k) { lnt r(1),t(v); while(k){ if(k&1) r*=t; t*=t; k>>=1; } return r; }


void prime_factorize(lnt n, std::map<lnt,lnt>& prime_factors) {
	for(lnt i=2;i*i<=n;i++) {
		while(n%i==0) {
			prime_factors[i]++;
			n/=i;
		}
	}
	if(n!=1) prime_factors[n]++;
}


lnt solve(lnt n) {
	n*=2;
	std::map<lnt,lnt> pf;
	prime_factorize(n,pf);
	V<std::pair<lnt,lnt> > v;
	for(auto e:pf) v.emplace_back(e);
	int m=v.size();
	lnt min=2*n;
	rep(s,1<<m) {
		lnt a=1,b=1;
		rep(j,m) {
			if(s>>j&1) a*=ipow(v[j].first,v[j].second);
			else b*=ipow(v[j].first,v[j].second);
		}
		if(a<b) std::swap(a,b);
		lnt ta=a,tb=b;
		std::pair<lnt,lnt> A={1,0},B={0,1};
		if(b==1) {
			B={1,-a+1};
		}
		while(a%b) {
			// A-=a/b*B;
			A.first-=a/b*B.first;
			A.second-=a/b*B.second;
			a%=b;
			std::swap(a,b);
			std::swap(A,B);
		}
		min=std::min({min,std::abs(ta*B.first),std::abs(tb*B.second)});
	}
	return min;
}

lnt checker(lnt n) {
	for(lnt k=1;;k++) {
		if(((k+1)*k/2)%n==0) return k;
	}
	return 0;
}

