#define amax(a, b) a = std::max(a, b)
#define amin(a, b) a = std::min(a, b)

using ll = long long;

long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

int main() {
    ll n;
    std::cin >> n;
    ll n2 = n * 2;
    ll ans = n-1;
    for (ll i=2; i*i<=n2; i++) {
        if (n2 % i != 0) continue;
        ll q = n2 / i;
        ll x, y;
        ll gcd = extGCD(i, q, x, y);
        if (gcd != 1) continue;
        x = abs(x) % q, y = abs(y) % i;
        ll val = std::min(i * x, q * y);
        val %= n2;
        amin(val, n2 - val - 1);
        amin(ans, val);
    }
    std::cout << ans << '\n';
    return 0;
}

