//ax + by = gcd(a, b) �ƂȂ�x, y�����Ƃ߂�
ll extgcd(ll a, ll b, ll& x, ll& y) {
  ll d = a;
  if (b != 0) {
    d = extgcd(b, a%b, y, x);
    y -= (a / b)*x;
  }
  else {
    x = 1; y = 0;
  }
  return d;
}

ll solve(ll n) {
    n *= 2;
    vector<pll> yaku;
    for (ll x = 2; x * x <= n; x++) {
        int cnt = 0;
        while (n % x == 0) {
            cnt++;
            n /= x;
        }
        if (cnt > 0) {
            yaku.push_back(pll(x, cnt));
        }
    }
    if (n > 1) yaku.push_back(pll(n, 1));
    vl yaku2;
    int m = yaku.size();
    rep (i, m) {
        ll res = 1;
        rep (_, yaku[i].second) res *= yaku[i].first;
        yaku2.push_back(res);
    }

    ll ans = INF;
    rep (i, 1 << m) {
        ll a = 1, b = 1;
        rep (j, m) {
            if (i & (1 << j)) a *= yaku2[j];
            else b *= yaku2[j];
        }
        // DEBUG(pll(a, b));
        ll x, y;
        extgcd(a, -b, x, y);
        assert(abs(a * x - b * y) == 1);
        if (a * x - b * y == -1) {
            x *= -1;
            y *= -1;
        }
        ll need = 0;
        if (x <= 0) {
            ll xx = -x;
            chmax(need, xx / b + 1);
        }
        if (y <= 0) {
            ll yy = -y;
            chmax(need, yy / a + 1);
        }
        x += need * b;
        y += need * a;
        // DEBUG(pll(x, y));
        chmin(ans, b * y);
    }
    // cout << ans << endl;
    return ans;
}

