using boost::multiprecision::cpp_int;
using bint = cpp_int;

int solve() {
    LL(n);
    map<ll, ll> m = factor(n);
    ll ans = LINF;

    ll h = m.size();
    vector<ll> f(h);
    ll in = 0;
    for(auto it = m.begin(); it != m.end(); it++) {
        f[in] = modpow(it->first, it->second, LINF);
        in++;
    }
    bint p = modpow(2, h, LINF);
    rep(i, p) {
        ll x = 1;
        ll ii = i;
        rep(j, h) {
            if(ii % 2 == 1) x *= f[j];
            ii /= 2;
        }
        ll mm = ((bint)modinv(x, n / x) * (bint)(n / x - 1)) % (n / x);
        if(mm == 0) mm += n / x;
        if(((bint)mm * (x * mm + 1) / 2) % (n / x) == 0) chmin(ans, x * mm);
    }
    out(ans);
    return 0;
}

