// ax+by=1の解
int extgcd(int a, int b, int& x, int& y){
    int d = a;
    if (b != 0){
        d = extgcd(b, a%b, y, x);
        y -= (a / b)*x;
    }
    else{
        x = 1; y = 0;
    }
    return d;
}

// mod mでのaの逆数
int mod_inv(int a, int m){
    int x, y;
    a = (a%m+m)%m;
    extgcd(a, m, x, y);
    return (m + x%m) % m;
}

int func(int N)
{
   int ans = INF;

   int c = N;
   while(c%2==0) c/=2;
   if(c==1){ return N*2-1;}

   auto d = divisor(2*N);

    if(d.size()==2){
       return N-1;
   }

   for(auto p : d)
   {

       int q = 2*N / p;
       if(gcd(p,q)>1) continue;

       int i = mod_inv(-p,q);
       i = ((i%q)+q)%q;
       int k = i * p;
       if(k!=0){
           if(k * (k+1)/2 % N==0) chmin(ans, k);
       }
   }
   return ans;
}

