    for (int i = 0; i < 2; ++i) {
      vector<pair<long long, long long>> rem_mod = {{0, x}, {-1, y}};
      auto crt = chinese_remainder(rem_mod);
      if (crt && crt->first != 0) {
        ans = min(ans, (long long)crt->first);
