map<ll, int> factorize(ll N){
        map<ll, int> factors;
        while(!(N&1))N >>= 1, factors[2] ++;
        while(N % 3 == 0)N /= 3, factors[3] ++;
        for (ll i = 5; i * i <= N; i += 6){
            while(N % i == 0)N /=i, factors[i]++;
            while(N % (i+2) == 0)N /= i+2, factors[i+2] ++;
        }
        if(N > 1)factors[N] ++;
        return factors;
    }

    ll power(ll x, ll y) {
                assert(y >= 0);
                ll res = 1;
                while (y) {
                    if (y & 1)res *= x;
                    y = y >> 1;
                    x *= x;
                }
                return res;
            }

