long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    ll n;
    cin >> n;
    n *= 2;
    ll ans = n - 1;
    REP(i,2,50000000) {
        if(n%i)continue;
        if(i>=n)break;
        ll x = i, y = n/i;
        rep(_,2){
            ll a=0,b=0;
            ll g = extGCD(x,y,a,b);
            if(g!=1)continue;
            while(a<0){
                a+=y;b-=x;
            }
            while(a>y){
                a-=y;b+=x;
            }
            assert(a*x + b* y == 1);
            if(1.0 * a * x > 1e18)continue;
            ans = min(ans, a*x);

            a=-a;b=-b;
            a+=y;b-=x;
            assert(a*x + b* y == -1);
            if(1.0 * a * x > 1e18)continue;
            ans = min(ans, a * x);
            swap(x,y);
        }
    }
    cout << ans << endl;
    return 0;
}

