map<ll, int> prime_factor(ll n){
    map<ll, int> ret;
    for (ll i = 2; i * i <= n; ++i){
        while (n % i == 0){
            ++ret[i]; n /= i;
        }
    }
    if (n != 1) ret[n] = 1;
    return ret;
}

/* aとbの最大公約数を求める. */
ll gcd(ll a, ll b){
    if (b > a) return gcd(b, a);
    if (b == 0) return a;
    return gcd(b, a % b);
}

/* ax+by=gcd(a,b)を満たす(x,y)を格納し、gcd(a,b)を返す. */
ll extgcd(ll a, ll b, ll& x, ll& y){
    if (b > a) return extgcd(b, a, y, x);
    if (b == 0){
        x = 1; y = 0;
        return a;
    }
    ll g = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
    return g;
}

/* mod mでのaの逆元を求める.(gcd(a,m) = 1) */
ll modinv(ll a, ll m){
    ll x, y;
    extgcd(a, m, x, y);
    return (m + x % m) % m;
}

/* 連立線形方程式を解く.
        A[i] * x ≡ B[i] (mod M[i])
    なる方程式の解が
        x ≡ b (mod m)
    とかけるとき、(b, m)を返す.(存在しなければ(0, -1)) */
pair<ll, ll> liner_congruence(
    vector<ll> A, vector<ll> B, vector<ll> M
){
    ll x = 0, m = 1;

    for (int i = 0; i < A.size(); ++i){
        ll a = A[i] * m,
         b = B[i] - A[i] * x,
         d = gcd(M[i], a);

        if (b % d != 0) // 解なし
            return make_pair(0, -1);

        ll t = b / d * modinv(a / d, M[i] / d) % (M[i] / d);
        x = x + m * t;
        m *= M[i] / d;
    }

    return make_pair(x % m, m);
}

ll N;

void input(void){
  cin >> N;
}

ll _pow(ll a, ll b){
  if (b == 0) return 1;
  ll tmp = _pow(a, b / 2);
  if (b % 2 == 0) return tmp * tmp;
  return tmp * tmp * a;
}

ll solve(void){
  ll ret = (1LL << 60);
  map<ll, int> p = prime_factor(2 * N);
  vector<pair<ll, int>> pf;
  for (auto pi : p)
    pf.push_back({pi.first, pi.second});
  int k = p.size();
  for (int f = 0; f < (1 << k); ++f){
    ll tmp1 = 1, tmp2 = 1;
    for (int i = 0; i < k; ++i){
      if (f & (1 << i)) tmp1 *= pow(pf[i].first, pf[i].second);
      else tmp2 *= pow(pf[i].first, pf[i].second);
    }
    auto res = liner_congruence({1, 1}, {0, tmp2 - 1}, {tmp1, tmp2});
    if (res == (pair<ll, ll>){0, -1}) continue;
    ll tmp = res.first;
    if (tmp == 0) tmp += res.second;
    ret = min(ret, tmp);
  }
  return ret;
}

int main(void){
  input();
  cout << solve() << endl;
  return 0;
}

