long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}



int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll n;
  cin>>n;

  if(n==1){
    cout << 1 << endl;
    return 0;
  }
  if(n==2){
    cout << 3 << endl;
    return 0;
  }

  ll x=n;
  vector<pair<ll,ll>> so;

  for(ll i=2;i*i<=n;i++){
    if(n%i==0){
      bool che=true;
      for(ll j=2;j*j<=i;j++){
        if(i%j==0) che=false;
      }
      if(che){
        ll cnt=0;
        while(x%i==0){
          cnt++;
          x/=i;
        }
        so.pb({i,cnt});
      }

      if(i*i==n) continue;

      che=true;
      ll k=n/i;
      for(ll j=2;j*j<=k;j++){
        if(k%j==0) che=false;
      }
      if(che){
        ll cnt=0;
        while(x%k==0){
          cnt++;
          x/=k;
        }
        so.pb({k,cnt});
      }
    }
  }

  if(so.empty()){
    cout << n-1 << endl;
    return 0;
  }

  if(so[0].fi==2) so[0].se++;
  else so.pb({2,1});

  int m=so.size();
  vector<ll> ko(m);
  rep(i,m){
    ko[i]=1;
    rep(j,so[i].se){
      ko[i]*=so[i].fi;
    }
  }

  //——————————————bit全探索——————————————
  ll ans=n-1;
  rep(i, (1<<m)){
    ll a=1;
    ll b=1;
    rep(j,m){
      if(i & (1<<j)){
        a*=ko[j];
      }
      else b*=ko[j];
    }
    if(a==1||b==1) continue;
    vector<ll> c={0ll,b-1};
    vector<ll> d={a,b};
    pair<ll,ll> e=crt(c,d);
    ll an=e.fi;
    if(an==0) an+=e.se;
    chmin(ans,an);
  }

  cout << ans << endl;

