const int MAX_PRIME = 32 * 1e6;
int divisors[MAX_PRIME] = { 0 }, primes[MAX_PRIME] = { 0 }, nPrimes = 0;
void generatePrimes() {
	for (int i = 2; i < MAX_PRIME; i++) {
		if (divisors[i] == 0) divisors[i] = primes[nPrimes++] = i;
		for (int j = 0; j < nPrimes && i * primes[j] < MAX_PRIME; j++)
			divisors[i * primes[j]] = min(divisors[i], primes[j]);
	}
}

long long gcdex(long long a, long long b, long long &x, long long &y) {
	if (!b) return x = 1, y = 0, a;
	long long px, py, res = gcdex(b, a % b, px, py);
	return x = py, y = px - a / b * py, res;
}

map<long long, int> factorize(long long x) { 
    // max prime should be greater than or equal to the square root of x
	map<long long, int> res;
	for (int i = 0; 1ll * primes[i] * primes[i] <= x; i++) {
		if (x % primes[i] == 0) {
			int c = 0;
			while (x % primes[i] == 0) c++, x /= primes[i];
			res[primes[i]] = c;
		}
	}
	if (x != 1) res[x] = 1;
	return res;
}

int main () {
    generatePrimes();
    long long n;
    while (scanf("%lld", &n) == 1) {
        auto f = factorize(2 * n);
        vector<long long> p;
        for (auto [div, c] : f) {
            long long x = 1;
            while (c--) x *= div;
            p.push_back(x);
        }

        long long res = n == 1 ? 1 : n & 1 ? n - 1 : 2 * n;
        int psz = p.size();
        for (int m = 0; m < (1 << psz); m++) {
            long long a, b, x = 1, y = 1;
            for (int b = 0; b < psz; b++)
                if (m >> b & 1) x *= p[b];
                else y *= p[b];
            if (x == 1) continue;
            if (y == 1) a = 1, b = x - 1;
            else gcdex(x, y, a, b);
            res = min(res, min(x * abs(a), y * abs(b)));
        }
        printf("%lld\n", res);
    }
}

