long long garner(vector<long long> r, vector<long long> m){
	int n = r.size();
	long long m_prod = 1;
	long long x = r[0] % m[0];
	for (long long i = 1; i < n; i++) {
		m_prod *= m[i - 1];
		long long t = (((r[i] - x + m[i]) % m[i]) * mod_inv(m_prod, m[i])) % m[i];
		if (t < 0) t += m[i];
		x += t * m_prod;
	}
	return x;
}
