ll gcd(ll a, ll b, ll& x, ll& y) {
  if (b == 0) {
      x = 1;
      y = 0;
      return a;
  }
  ll x1, y1;
  ll d = gcd(b, a % b, x1, y1);
  x = y1;
  y = x1 - y1 * (a / b);
  return d;
}

bool dio(ll a, ll b, ll c, ll &x0, ll &y0, ll&g) {
  g = gcd(abs(a), abs(b), x0, y0);
  if (c % g) {
    return false;
  }

  x0 *= c / g;
  y0 *= c / g;
  if (a < 0) x0 = -x0;
  if (b < 0) y0 = -y0;
  return true;
}

ll solve(ll a,ll b,ll c)
{
  ll  x0, y0, g;
   b = -b;
  if(dio(a, b, c, x0, y0, g) == 0){
    assert(false);
    return 0;
  }
  //cerr << x0 << ' ' << y0;
  ll oo = 1e18;
  function<pair<ll, ll>(ll k)>get = [&](ll k)
  {
    return mp(x0 + b / g * k, y0 - a / g * k);
  };
  auto check = [&](ll k)
  {
    auto tmp = get(k);
    return tmp.fi >= 0 && tmp.se >= 0;
  };
  ll b1 = b / g, a1 = a / g; b1 = abs(b1);
  ll l = max((-oo + x0) / b1, (-oo + y0) / a1);
  ll r = min((oo + x0) / b1, (oo + y0) / a1);
  ll mid;
  l = max(l, -oo), r = min(r, oo);
  if(l > r) swap(l, r);
  while(l <= r){
    mid = (l + r) / 2;
    if(!check(mid)) r = mid - 1;
    else l = mid + 1;
  }
  return get(r).first * a;
}

