inline long long crt_mod(long long a, long long m) {
	return (a % m + m) % m;
}

long long crt_gcd(long long a, long long b, long long &p, long long &q) {
	if (b == 0) { p = 1; q = 0; return a; }
	long long d = crt_gcd(b, a%b, q, p);
	q -= a / b * p;
	return d;
}

// ({rx}, {modx})
pair<long long, long long> crt(const vector<long long> &r, const vector<long long> &m) {
	long long r0 = 0, m0 = 1;
	for (int i = 0; i < (int)r.size(); ++i) {
		long long p, q;
		long long d = crt_gcd(m0, m[i], p, q); // p is inv of M/d (mod. m[i]/d)
		if ((r[i] - r0) % d != 0) return make_pair(0, -1);
		long long tmp = (r[i] - r0) / d * p % (m[i] / d);
		r0 += m0 * tmp;
		m0 *= m[i] / d;
	}
	return make_pair(crt_mod(r0, m0), m0);
}

vector<int> get_divisor(int N)
{
	vector<int> res;
	rep(i, 1, sqrt(N) + 1)
	{
		if (N%i == 0)
		{
			res.push_back(i);
			if (N / i != i)res.push_back(N / i);
		}
	}
	return res;
}

signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;

	auto div = get_divisor(2 * N);

	int ans = INF;
	for (auto v : div)
	{
		int r0 = 0, r1 = (2 * N) / v - 1, m0 = v, m1 = (2 * N) / v;
		auto res = crt({ r0,r1 }, { m0,m1 });
		if (res.first == 0)continue;
		chmin(ans, res.first);
	}

	cout << ans << endl;

	return 0;
}

