template <typename T>
std::vector<std::pair<T, int>> prime_factorization(T val) {
  std::vector<std::pair<T, int>> res;
  for (T i = 2; i * i <= val; ++i) {
    if (val % i != 0) continue;
    int exponent = 0;
    while (val % i == 0) {
      ++exponent;
      val /= i;
    }
    res.emplace_back(i, exponent);
  }
  if (val != 1) res.emplace_back(val, 1);
  return res;
}

std::vector<bool> sieve_of_eratosthenes(int val) {
  std::vector<bool> res(val + 1, true);
  res[0] = false;
  if (val >= 1) res[1] = false;
  for (int i = 2; i * i <= val; ++i) {
    if (res[i]) {
      for (int j = i * i; j <= val; j += i) res[j] = false;
    }
  }
  return res;
}

template <typename T>
std::pair<T, T> ext_gcd(T a, T b) {
  if (b == 0) return {1, 0};
  T fst, snd; std::tie(fst, snd) = ext_gcd(b, a % b);
  return {snd, fst - a / b * snd};
}

int main() {
  ll n; cin >> n;
  ll ans = n * 2;
  int two = 0;
  while (n % 2 == 0) {
    ++two;
    n >>= 1;
  }
  auto p = prime_factorization(n);
  int m = p.size();
  vector<ll> ex(m, 1);
  REP(i, m) REP(_, p[i].second) ex[i] *= p[i].first;
  // k = 2l
  REP(i, 1 << m) {
    ll cur = 1;
    REP(j, m) {
      if (i >> j & 1) cur *= ex[j];
    }
    ll rem = n / cur;
    cur *= 1 << two;
    ll x = ext_gcd(rem, -cur * 2).second;
    ll p = x > 0 ? x / rem - (x % rem == 0) : (x - (rem - 1)) / rem - (-x % rem == 0);
    if (log10(rem) + log10(abs(p)) < 18) {
      ll tmp = x - rem * p;
      assert(tmp > 0);
      if (log10(cur) + log10(tmp) + log10(2) < 18) chmin(ans, cur * tmp * 2);
    }
  }
  // k = 2l - 1
  REP(i, 1 << m) {
    ll cur = 1;
    REP(j, m) {
      if (i >> j & 1) cur *= ex[j];
    }
    ll rem = n / cur;
    cur *= 1 << two;
    ll x = -ext_gcd(cur * 2, -rem).first;
    ll p = x > 0 ? x / rem - (x % rem == 0) : (x - (rem - 1)) / rem - (-x % rem == 0);
    if (log10(rem) + log10(abs(p)) < 18) {
      ll tmp = x - rem * p;
      assert(tmp > 0);
      if (log10(cur) + log10(tmp) + log10(2) < 18) chmin(ans, cur * tmp * 2 - 1);
    }
  }
  cout << ans << '\n';
  return 0;
}

