map<ll, int> factorize(ll x)
{
    map<ll, int> ret;
    for(ll i = 2; i*i <= x; i++)
    {
        while(x%i == 0)
        {
            ret[i]++;
            x/=i;
        }
    }
    if(x != 1) ret[x]++;
    return ret;
}

int main()
