        if(p == 2) m *= 2LL;
        M.push_back(m);
    }
    int n = M.size();
    ll ans = LINF;
    for(ll S = 0; S < (1 << n); S++)
    {
        vector<ll> R;
        rep(i,n)
        {
            if((S >> i) & 1) R.push_back(M[i] - 1);
            else R.push_back(0);
        }
        auto tmp = crt(R, M);
        if(tmp.first != 0) chmin(ans, tmp.first);
    }
    cout << ans << endl;
