std::vector<ll> enumerateDivisors(ll n) {
	std::vector<ll> l, r;
	for (ll i = 1; i * i <= n; ++i) {
		auto d = std::div(n, i);
		if (d.rem) continue;
		l.emplace_back(i);
		if (d.quot != i) r.emplace_back(d.quot);
	}
	l.insert(l.end(), r.rbegin(), r.rend());
	return l;
}

i64 slow(i64 n) {
	i64 sum = 0;
	i64 k = 1;
	while (true) {
		sum += k;
		if (sum % n == 0) return k;
		++k;
	}
}

i64 calc(i64 n) {
	auto v = enumerateDivisors(2 * n);
	i64 mi = INFLL;
	for (auto x : v) {
		if (x < 2 * n / x) continue;
		i64 y = 2 * n / x;
		// k | x && (k+1) | (2n/x)
		// k | x && (k-1) | (2n/x)

		for (i64 k = x; k <= std::min(8 * n, mi); k += x) {
			if ((k - 1) % y == 0) CHMIN(mi, k - 1);
			else if ((k + 1) % y == 0) CHMIN(mi, k);
		}
	}
	return mi;
}

