typedef long long ll;

template <typename T>
T pow(T a, ll n, ll MOD) {
    a %= MOD;
	T ans = 1;
	T tmp = a;
	for (int i = 0; i <= 60; i++) {
		ll m = (ll)1 << i;
		if (m & n) {
		ans *= tmp;
		ans %= MOD;
		}
		tmp *= tmp;
		tmp %= MOD;
	}
	return ans;
}


int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    ll N;
    cin >> N;
    N *= 2;
    ll M;
    M = N;
    vector<ll> fac;
    vector<ll> ps;
    for(ll i = 2; i*i <= N; i++){
        if(M%i == 0){
            ll cur = 1;
            while(M%i == 0){
                cur *= i;
                M /= i;
            }
            ps.push_back(i);
            fac.push_back(cur);
        }
    }
    if(M != 1) {
        ps.push_back(M);
        fac.push_back(M);
    }
    int sz = fac.size();
    ll ans = 2*N-1;
    for(int i = 0; i < (1<<sz); i++){
        ll x = 1, y = 1;
        for(int j = 0; j < sz; j++){
            if(i&(1<<j)) x *= fac[j];
            else y *= fac[j];
        }

        // cout << x << ' ' << y << endl;
        if(N == 1){
            cout << 1 << endl;
            return 0;
        }
        if(y < x){
            if(y == 1) continue;
            // x*inv % y = 1にしたい
            ll p = 1;
            ll inv = 1;
            for(int j = 0; j < sz; j++){
                if(!(i&(1<<j))) {
                    p *= (fac[j]/(ps[j]))*(ps[j]-1);
                }
            }
            inv = pow<ll>(x, p-1, y);
            ll K = (x*inv)-1;
            // cout << K << ':' << x*inv << ' ' << inv << endl;
            ans = min(ans, K);
        }else{
            if(x == 1) continue;
            // y*inv % x = -1にしたい
            ll inv = 1;
            ll p = 1;
            for(int j = 0; j < sz; j++){
                if((i&(1<<j))) {
                    p *= (fac[j]/(ps[j]))*(ps[j]-1);
                }
            }
            inv = pow<ll>(y, p-1, x);
            inv *= -1; inv += x; inv %= x;
            ll K = (y*inv);
            // cout << K << "->" << inv << endl;
            ans = min(ans, K);
        }
    }
    cout << ans << endl;
}

