template< typename F >
struct FixPoint : F {
  FixPoint(F &&f) : F(forward< F >(f)) {}

  template< typename... Args >
  decltype(auto) operator()(Args &&... args) const {
    return F::operator()(*this, forward< Args >(args)...);
  }
};

template< typename F >
inline decltype(auto) MFP(F &&f) {
  return FixPoint< F >{forward< F >(f)};
}

map< int64_t, int > prime_factor(int64_t n) {
  map< int64_t, int > ret;
  for(int64_t i = 2; i * i <= n; i++) {
    while(n % i == 0) {
      ret[i]++;
      n /= i;
    }
  }
  if(n != 1) ret[n] = 1;
  return (ret);
}

using ll = int64;

ll extgcd(ll a, ll b, ll &x, ll &y) {
  ll g = a;
  x = 1;
  y = 0;
  if(b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
  return g;
}

std::tuple< ll, ll, ll > extgcd(ll a, ll b) {
  ll x, y;
  ll g = extgcd(a, b, x, y);
  return std::make_tuple(x, y, g);
}


int main() {
  int64 N;
  cin >> N;
  // k(k+1)/2

  if(N == 1) {
    cout << 1 << "\n";
    exit(0);
  }
  if(N == 2) {
    cout << 3 << "\n";
    exit(0);
  }

  auto p = prime_factor(N);
  p[2]++;
  vector< pair< int64, int > > ps(begin(p), end(p));


  int64 ret = N - 1;


  auto dfs = MFP([&](auto dfs, int idx, int64 k) -> void {
    if(idx == (int) ps.size()) {
      int64 l = (N * 2) / k; // 残ったやつ
      // k*x +1 = l*y
      int64 x, y;
      extgcd(-k, l, x, y);
      if(k * x + 1 == l * y && x > 0) {
        chmin(ret, x * k);
      }
      return;
    }
    if(ps[idx].second > 0) {
      ps[idx].second--;
      dfs(idx, k * ps[idx].first);
      ps[idx].second++;
    }
    dfs(idx + 1, k);
  });
  dfs(0, 1);
  cout << ret << "\n";
}

