void solve() {
  inl(N);
  if (N == 1) {
    out(1);
    return;
  }
  N *= 2;
  ll ans = infLL;
  rep1(i, N) {
    if (i == 1) {
      amin(ans, N - 1);
      continue;
    }
    if (i * i > N) break;
    if (N % i == 0) {
      ll j = N / i;
      {
        vl r{0, j - 1}, m{i, j};
        auto [c, d] = atcoder::crt(r, m);
        if (c)
          amin(ans, c);
        else if(d)
          amin(ans, d);
        trc(c,d);
      }
      {
        vl r{i - 1, 0}, m{i, j};
        auto [c, d] = atcoder::crt(r, m);
        if (c)
          amin(ans, c);
        else if(d)
          amin(ans, d);
        trc(c,d);
      }
      trc(i, ans);
    }
  }
  out(ans);
}

