ll gcd_ex(ll a, ll b, ll &x, ll &y) // a * x + b * y = gcd(a, b)
{
    if (a == 0)
    {
        x = 0; y = 1;
        return b;
    }
    ll x1, y1;
    ll d = gcd_ex(b % a, a, x1, y1);
    x = y1 - (b / a) * x1;
    y = x1;
    return d;
}

ll solve(ll n1, ll n2) {
    ll x, y;
    ll g = gcd_ex(n1, n2, x, y);
    if (g != 1) {
        return big;
    }
    y %= n1;
    if (y < 0) {
        y += n1;
    }
    if (y * n2 <= 1) {
        y += n1;
    }
    return y * n2 - 1;
}

