ll inv_mod(ll a, ll m){
	assert(0<a);
	assert(a<m);
	return a==1 ? 1 : m-m*__int128_t(inv_mod(m%a, a))/a;
}


ll gg(ll a, ll b){
	if(b == 1) return a+1; //for(ll x=1;;++x) if(b*x>1 && (b*x-1) %a==0) return x;
	//bx - 1 = ay
	//bx = 1 (mod a)

	if(a == 1) return 1;
	ll x = inv_mod(b%a, a);
	return x;
}

ll solve(ll n){
	n*=2;
	ll ans = n-1;
	for(ll d=1; d*d<=n; ++d) if(n%d==0){
		ll d2 = n/d;
		if(gcd(d,d2) == 1){
			ll x1 = gg(d,d2);
			ll x2 = gg(d2,d);

			ans = min(ans, d2 * x1 - 1);
			ans = min(ans, d * x2 - 1);
		}
	}

	return ans;
}


