vector<ll> makeDivisors(ll n) {
    vector<ll> ret;
    for(ll i = 1; i * i <= n; i++) {
        if(n%i == 0) {
            ret.push_back(i);
            if(i*i != n) ret.push_back(n/i);
        }
    }
    sort(ret.begin(), ret.end());
    return ret;
}

int main() {
    /*
    k * (k+1) が 2 * N で割り切れるか
    CRT (Chinese Remainder Theorem)
    */ 
    ll N;
    cin >> N;
    vector<ll> cand = makeDivisors(2 * N);
    vector<ll> ans;
    ans.push_back(2 * N);
    for (ll x : cand) {
        // x と N/x で割った余りが0, -1
        pair<ll, ll> temp = crt({0, -1}, {x, 2 * N / x});
        if (temp.first != 0) {
            ans.push_back(temp.first);
        }
        temp = crt({-1, 0}, {x, 2 * N / x});
        if (temp.first != 0) {
            ans.push_back(temp.first);
        }
    }
    sort(ans.begin(), ans.end());
    for (ll a : ans) {
        if (a == 0) continue;
        cout << a << '\n';
        return 0;
    }
    return 0;
