vector<pair<ll,ll>> prime(ll n) {
    vector<pair<ll,ll>> res;
    for (ll i = 2; i * i <= n; i++) {
        if (n % i != 0) continue;
        ll count = 0;
        while (n % i == 0) { count++; n /= i; }
        res.push_back(make_pair(i,count));
    }
    if(n != 1) res.push_back(make_pair(n,1));
    return res;
}

ll pow(ll a, ll n) {
    ll res = 1;
    while (n) {
        if (n & 1) res *= a;
        a *= a;
        n >>= 1;
    }
    return res;
}

ll GCD(ll a, ll b){
    ll s = a, t = b;
    while(s % t) { s %= t; swap(s,t); }
    return t;
}

const ll INF = 1ll<<60;

ll extGCD(ll a, ll b, ll &x, ll &y) {
    x = 1, y = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a,b);
        x -= t * y; swap(x,y);
    }
    return a;
}

int main(){
    ll n; cin >> n;
    auto p = prime(n * 2ll);
if (n == 1) { cout << 1 << endl; return 0; }
    vector<ll> ans;
    for (int i = 0; i < (int)p.size(); i++) {
        ll div = p[i].first, num = p[i].second;
        ans.push_back(pow(div, num));
    }
    ll res = n - 1ll; n *= 2;
    for(ll i = 0; i < 1<<(ll)ans.size(); i++) {
        ll c1 = 1ll;
        for (ll j = 0; j < (int)ans.size(); j++) {
            if (i & 1ll<<j) c1 *= ans[j];
        }
      if (c1 == 1ll || c1 == n) continue; ll c2 = n / c1;
      if (c1 + 1 == c2) { cout << c1 << endl;
                         return 0;
                        }
        ll x, y;
        extGCD(c2, -c1, x, y);
        ll count = c2 * x;
        count = (count % n + n) % n;
      if (count == 0) continue;
        chmin(res, count);
    }
    cout << res << endl;
    return 0;
}

