inline int exgcd(int a, int b, int &x, int &y) {
	if(!b) return x = 1, y = 0, a;
	int d = exgcd(b, a % b, y, x); y -= a / b * x; return d;
}
inline int mul(int x, int y, int p) {
	int res = 0;
	for(; y; y >>= 1) {
		if(y & 1) res = (res + x) % p;
		x = (x + x) % p;
	}
	return res;
}
int solve(int a, int c, int p) {
	int x, y, d = exgcd(a, p, x, y);
	if(d > 1) return -1;
	x = (x % p + p) % p;
	return mul(x, c, p);
}

inline int excrt(int x, int y) {
	int t = solve(x, y - 1, y);
	if(t == -1) return (1ll << 62);
	int res = mul(t, x, x * y);
	return res == 0 ? x * y : res;
}

