void LF_Prime_Sequence(const long &n, vector<long> &viPrime){
    if(n < 2){
        return;
    }
    viPrime.clear();
    vector<char> aiType(n + 1,0);
    long iTmp = 2;
    while(true){
        if(iTmp * iTmp > n){
            break;
        }
        for(long j = iTmp; j * iTmp <= n; j++){
            aiType[j * iTmp] = 1;
        }
        for(long j = iTmp+1; j <= n; j++){
            if(aiType[j] == 0){
               iTmp = j;
               break;
            }
        }
    }
    for (long i = 2; i <= n; i++){
        if(aiType[i] == 0){
            viPrime.push_back(i);
        }
    }
    return;
}

//素因数分解(上とセット)
void LF_Factorization(long n, vector<pair<long, long>> &viiFactor){
    if(n < 2){
        return;
    }
    vector<long> viPrime;
    LF_Prime_Sequence(sqrt(n)+1, viPrime);

    for(long i = 0; i < viPrime.size(); i++){
        if(n == 1){
            break;
        }
        long nCount = 0;
        while(n % viPrime[i] == 0){
            n /= viPrime[i];
            nCount++;
        }
        if(nCount > 0){
            viiFactor.push_back(make_pair(viPrime[i], nCount));
        }
    }
    if(n > 1){
        viiFactor.push_back(make_pair(n, 1));
    }
    return;
}

