        }
        //(k+1)|a, k|bなるkを求める
        long aTmp = a, bTmp = b, u = 1, v = 0; 
        while (bTmp > 0) {
            long t = aTmp / bTmp;
            aTmp -= t * bTmp;
            swap(aTmp, bTmp);
            u -= t * v;
            swap(u, v);
        }
        u %= b;
        if (u <= 0){
            u += b;
        }
        if(a == 1){
            u += b;
        }
        nAns = min(a*u-1, nAns);
    }

    printf("%ld", nAns);

    return 0;
}

