ll __tmp1, __tmp2;
ll exgcd(ll a, ll b, ll &x = __tmp1, ll &y = __tmp2) {
	if(!b) {
		x = 1;
		y = 0;
		return a;
	}
	ll x0, y0;
	ll res = exgcd(b, a % b, x0, y0);
	x = y0;
	y = x0 - a / b * y0;
	return res;
}

ll inv(ll x, ll Mod) {
	ll res;
	if (exgcd(x, Mod, res) != 1)
		return -1;
	return ((res % Mod) + Mod) % Mod;
}

ll ans = 1000000000000000000;
void solve (ll x, ll y) {
	ll iv = inv(x, y);
	if (iv == -1) return;
	ll z = iv * x - 1;
	if (z < 1) z += x * y;
	ans = std::min(ans, z);
}

