ll Cal(ll a, ll b)
{
    ll m = a, n = b, xm = 1, xn = 0, xr;
    while (n)
    {
        int q = m / n;
        int r = m - q * n;
        xr = xm - xn * q;
        m = n; xm = xn;
        n = r; xn = xr;
    }
    ll ym = (1 - xm * a) / b;
    if (xm == 0 || ym == 0)
        xm += b;
    return xm;
}

