map<i64, i64> get_primes(i64 n) {
    map<i64, i64> ans;

    for (i64 i = 2; i <= sqrt(n) + 2; i++) {
        while (n % i == 0) {
            ans[i] += 1;
            n /= i;
        }
    }

    ans[n] += 1;
    ans.erase(1);
    return ans;
}

void gen(map<i64, i64>& primes, set<pair<i64, i64>>& res) {
    vector<i64> q;
    for (auto e : primes) {
        q.push_back(1);
        for (i64 i = 0; i < e.second; i++) {
            q.back() *= e.first;
        }
    }

    i64 mx = (1ll << q.size());
    for (i64 m = 0; m < mx; m++) {
        i64 u = 1;
        i64 v = 1;

        for (i64 i = 0; i < q.size(); i++) {
            if (m & (1ll << i)) {
                u *= q[i];
            }
            else {
                v *= q[i];
            }
        }

        res.insert({min(u, v), max(u, v)});
    }
}

