long long fastPower(long long base, long long power) {
	long long result = 1;
	while (power > 0) {
		if (power & 1) {//此处等价于if(power%2==1)
			result = result * base;
		}
		power >>= 1;//此处等价于power=power/2
		base = (base * base);
	}
	return result;
}
