void exgcd(ll a, ll &x, ll b, ll&y, ll&g)
{
    if (b) {
        exgcd(b, y, a % b, x, g);
        y -= a/b*x;
    } else {
        x = 1;
        y = 0;
        g = a;
    }
}
void solve(ll a, ll b)
{
    ll x0, y0, g;
    exgcd(a, x0, b, y0, g);
    ll t = 2 - a * x0;
    if (t < 0)
        t /= a * b;
    else
        t = (t + a * b - 1) / (a * b);
    ll x = x0 + t * b;
    ll k = x * a - 1;
    assert(k > 0);
    //cerr << "a, b, k " << a << ' ' << b << ' ' << k << endl;
    ans = min(ans, k);
}
