        tie(y, y1) = make_tuple(y1, y - q * y1);
        tie(a1, b1) = make_tuple(b1, a1 - q * b1);
    }
    return a1;
}


void brute(int64_t x, int64_t y) {
    int64_t foo, bar;
    if (ex_gcd(x, y, foo, bar) != 1) return ;
    int64_t real_foo = foo * x;
    int64_t real_bar = -y * bar;
    if (real_bar > 0) ans = min(ans, real_bar);
    else {
        int64_t need = 1 - real_bar;
        int64_t add = (need + n - 1) / n;
        real_bar += add * n;
        ans = min(ans, real_bar);
    }
}

