// Finds the minimal pair {x, y} such that x, y >= 0 and ax - by = gcd(a, b).
pair<int64_t, int64_t> extended_euclidean(int64_t a, int64_t b) {
    // https://en.wikipedia.org/wiki/Extended_Euclidean_algorithm#Example
    int64_t g = b, r = a, x = 0, y = 1;

    while (r != 0) {
        int64_t q = g / r;
        g %= r; swap(g, r);
        x -= q * y; swap(x, y);
    }

    // g == gcd(a, b)
    // x * a == g (mod b)
    x = x <= 0 ? x + b : x;
    y = (x * a - g) / b;
    assert(x >= 0 && y >= 0);
    int64_t take = min(x / (b / g), y / (a / g));
    x -= take * (b / g);
    y -= take * (a / g);
    assert(x >= 0 && y >= 0);
    return {x, y};
}


