#define MAXQ 33000000
bool isPrime[(MAXQ + 1)];
ll pList[(MAXQ + 1)];
ll sizeP;  // global
void calcP() {
  sizeP = 0;
  fill(isPrime, isPrime + MAXQ + 1, true);
  isPrime[0] = isPrime[1] = false;
  for (ll i = 2; i <= MAXQ; ++i) {
    if (isPrime[i]) {
      pList[sizeP++] = i;
      for (ll j = i * 1LL * i; j <= MAXQ; j += i) {
        isPrime[j] = false;
      }
    }
  }
}
//素因数分解
map<ll, ll> factorizeVal(ll val) {
  map<ll, ll> ma;
  for (ll i = 0; i < sizeP; i++) {
    ll cnt = 0;
    ll primeV = pList[i];
    while (val % primeV == 0) {
      val /= primeV;
      cnt++;
    }
    if (cnt) {
      ma[primeV] += cnt;
    }
    if (val == 1) break;
  }
  if (val != 1) {
    ma[val]++;
  }
  return ma;
}

