bool is_prime(int x) {
	if (x == 1)
		return false;
	if (x == 2 || x == 3)
		return true;
	if (x % 6 != 1 && x % 6 != 5)
		return false;
	int s = sqrt(x);
	for (int i = 5; i <= s; i += 6)
