ll gcd(ll a, ll b) {// 最大公約数
	a = abs(a);
	b = abs(b);
	if (a == 0) { return b; }
	if (b == 0) { return a; }

	ll c;
	if (a < b) { c = a; a = b; b = c; }
	while (1) {
		a %= b;
		if (a == 0) { return b; }
		c = a; a = b; b = c;
	}
}

inline ll lcm(ll a, ll b) {// 最小公倍数
	if (a < 0) { a = -a; }
	if (b < 0) { b = -b; }
	if (a == 0) { return b; }
	if (b == 0) { return a; }
	ll x = a;
	x /= gcd(a, b);
	x *= b;
	return x;
}

ll mod_multi(ll a, ll b, ll n) {
	return (a * b) % n;
}
ll mod_pow(ll a, ll d, ll n) {
	a = a % n;

	if (d == 0) {
		return 1;
	}
	if (d == 1) {
		return a;
	}
	if (d % 2 == 0) {
		ll k = mod_pow(a, d / 2, n);
		return mod_multi(k, k, n);
	}
	else {
		ll k = mod_pow(a, d / 2, n);
		ll b = mod_multi(k, k, n);

		return mod_multi(b, a, n);
	}
}
bool miller_rabin(ll n, ll a) {
	ll d = n - 1;
	int p = 0;

	while (d % 2 == 0) {
		p++;
		d /= 2;
	}
	ll m = mod_pow(a, d, n);
	if (m == 1) {
		return true;
	}
	for (int i = 0; i < p; i++) {
		if (m == n - 1) {
			return true;
		}
		m = mod_multi(m, m, n);
	}
	return false;
}
