int* euler_phi_table(int n) {
	if (n < 0) { return NULL; }
	int* a = new int[n + 1];
	for (int i = 0; i <= n; i++) {
		a[i] = i;
	}
	for (int i = 2; i <= n; i++) {
		if (a[i] == i) {
			for (int j = i; j <= n; j += i) {
				a[j] = a[j] / i * (i - 1);
			}
		}
	}
