//素因数分解(関数ver)
map<int64_t,int64_t> prime_fact(int64_t n){
  int64_t a = 2;
  map<int64_t,int64_t> mp;
  while(n >= a*a){
    if(n %a == 0){
      if(mp.count(a)){
        mp[a]++;
      }
      else{
        mp[a] = 1;
      }
      n /= a;
    }
    else{
      a++;
    }
  }
  if(mp.count(n)){
    mp[n]++;
  }
  else{
    mp[n] = 1;
  }
  return mp;
}

//bit全探索改
vector<string> bit_all_search(int n){
  vector<string> use(0);
  queue<string> Q;
  Q.push("");
  while(Q.size()){
    string S = Q.front();
    Q.pop();
    string T = S;
    T += '0';
    if(T.size() == n){
      use.push_back(T);
    }
    else{
      Q.push(T);
    }
    T = S;
    T += '1';
    if(T.size() == n){
      use.push_back(T);
    }
    else{
      Q.push(T);
    }
  }
  return use;
}

int64_t extGCD(int64_t a, int64_t b, int64_t &x, int64_t &y) {
  if (b == 0) {
    x = 1;
    y = 0;
    return a;
  }
  int64_t d = extGCD(b, a%b, y, x);
  y -= a/b * x;
  return d;
}

