	{
		template<class T>struct ext_gcd_result_t
		{
			T gcd, x, y;
		};
	}
	template<class T>impl::ext_gcd_result_t<T> ext_gcd(T a, T b)
	{
		impl::ext_gcd_result_t<T> ret{};
		if (b == T())
		{
			ret.gcd = a;
			ret.x = 1;
			ret.y = 0;
		}
		else
		{
			auto prev = ext_gcd(b, a % b);
			prev.y -= a / b * prev.x;
		}
		return ret;
	}
}

