template <typename T>
T extgcd(T a, T b, T& x, T& y) {
    T s = a, t = b,
      xs = 1, ys = 0,
      xt = 0, yt = 1;

    while (t != 0) {
        T div = s / t;

        s -= t * div;
        xs -= xt * div;
        ys -= yt * div;

        std::swap(s, t);
        std::swap(xs, xt);
        std::swap(ys, yt);
    }

    x = xs;
    y = ys;
    return s;
}

struct Prime {
    int max_n;
    std::vector<int> primes;
    std::vector<bool> isp;

    explicit Prime(int max_n)
        : max_n(max_n), isp(max_n + 1, true) {
        isp[0] = isp[1] = false;
        for (int i = 2; i * i <= max_n; ++i) {
            if (isp[i]) {
                for (int j = i; i * j <= max_n; ++j) {
                    isp[i * j] = false;
                }
            }
        }

        for (int p = 2; p <= max_n; ++p) {
            if (isp[p]) primes.push_back(p);
        }
    }

    template <class T>
    bool isprime(T n) const {
        if (n <= max_n) return isp[n];
        for (T p : primes) {
            if (p * p > n) break;
            if (n % p == 0) return false;
        }
        return true;
    }

    template <class T>
    std::vector<std::pair<T, int>> factorize(T n) const {
        std::vector<std::pair<T, int>> facts;
        for (T p : primes) {
            if (p * p > n) break;
            if (n % p != 0) continue;
            int exp = 0;
            while (n % p == 0) {
                n /= p;
                ++exp;
            }
            facts.emplace_back(p, exp);
        }
        if (n > 1) {
            facts.emplace_back(n, 1);
        }
        return facts;
    }

    template <class T>
    static std::vector<T> divisors(T n) {
        std::vector<T> ret;
        for (T p = 1; p * p <= n; ++p) {
            if (n % p != 0) continue;
            ret.push_back(p);
            if (n / p == p) continue;
            ret.push_back(n / p);
        }
        return ret;
    }
};

using lint = long long;
const Prime P(40000000);

void solve() {
    lint n;
    std::cin >> n;

    auto fs = P.factorize(n * 2);
    std::vector<lint> ds;
    for (auto f : fs) {
        ds.push_back(1);
        while (f.second--) ds.back() *= f.first;
    }
    int k = ds.size();

    lint ans = n * 2;
    for (int b = 0; b < (1 << k); ++b) {
        lint d = 1;
        for (int i = 0; i < k; ++i) {
            if ((b >> i) & 1) d *= ds[i];
        }

        lint e = n * 2 / d;
        if (std::gcd(d, e) != 1) continue;

        lint x, y;
        extgcd(d, e, x, y);
        x *= -1;

        while (x <= 0) {
            x += e;
            y += d;
        }

        ans = std::min(ans, d * x);
    }

    std::cout << ans << "\n";

