pair<LL, LL> extended_euclidean(LL a, LL b) {
    if (b == 0)
        return {1, 0};
    LL g, x, y;
    pair < LL, LL > gap = extended_euclidean(b, a%b);
    x = gap.first, y = gap.second;
    return {y, x-(a/b)*y};
}

void dfs(LL pos, LL A, LL B){
    if(pos >= (LL)prime.size()){
        auto rv = extended_euclidean(B, A);
        LL gap = -rv.second;
        if(gap <= 0) gap += (-gap / B) * B + 2 * B;
        gap %= B;
        if(!gap) gap = B;
        gap = max(gap, (B - 1) / A + ((B - 1) % A > 0));
        ans = min(ans, gap * A);
        return;
    }
    dfs(pos + 1, A * prime[pos], B);
    dfs(pos + 1, A, B * prime[pos]);
}

