inline long long mod(long long a, long long m) {
	return (a % m + m) % m;
}

// 拡張 Euclid の互除法
long long extGCD(long long a, long long b, long long &p, long long &q) {
	if (b == 0) { p = 1; q = 0; return a; }
	long long d = extGCD(b, a%b, q, p);
	q -= a / b * p;
	return d;
}

// 答えを x ≡ r (mod. M) として、{r, M} をリターン, 存在しない場合は {0, -1} をリターン
pair<long long, long long> ChineseRem(const vector<long long> &b, const vector<long long> &m) {
	long long r = 0, M = 1;
	for (int i = 0; i < (int)b.size(); ++i) {
		long long p, q;
		long long d = extGCD(M, m[i], p, q); // p is inv of M/d (mod. m[i]/d)
		if ((b[i] - r) % d != 0) return make_pair(0, -1);
		long long tmp = (b[i] - r) / d * p % (m[i] / d);
		r += M * tmp;
		M *= m[i] / d;
	}
	return make_pair(mod(r, M), M);
}

vector<int> get_divisor(int N)
{
	vector<int> ret;
	rep(i, 1, sqrt(N) + 1) {
		if (N % i == 0) {
			ret.push_back(i);
			if (i * i != N) ret.push_back(N / i);
		}
	}
	sort(begin(ret), end(ret));
	return (ret);
}

signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;

	auto div = get_divisor(2 * N);

	int ans = INF;
	for (auto v : div)
	{
		int m0 = v, m1 = (2 * N) / v;
		int r0 = 0, r1 = m1 - 1;
		auto res = ChineseRem({ r0,r1 }, { m0,m1 });
		if (res.second == -1)continue;
		if (res.first == 0)chmin(ans, res.second);
		else chmin(ans, res.first);
	}

	cout << ans << endl;

	return 0;
}

