template <typename T>
constexpr T gcd(T a, T b, T& x, T& y) {
  static_assert(std::is_integral_v<T>);
  T xx = y = 1;
  T yy = x = 0;
  while (a != 0) {
    T q = b / a;
    T t = a;
    a = b - q * a;
    b = t;
    t = xx;
    xx = x - q * xx;
    x = t;
    t = yy;
    yy = y - q * yy;
    y = t;
  }
  if (b < 0) {
    b = -b;
    x = -x;
    y = -y;
  }
  return b;
}

template <typename T>
std::optional<std::pair<T, T>> chinese_remainder(
    const std::vector<std::pair<T, T>>& rem_mod) {
  static_assert(std::is_integral_v<T>);
  T x = 0, n = 1;
  for (const auto& [r, m] : rem_mod) {
    T inv_m, inv_n, g = gcd(m, n, inv_m, inv_n);
    x = x * inv_m * (m / g) + r * inv_n * (n /= g);
    if ((x %= (n *= m)) < 0) {
      x += n;
    }
  }
  for (const auto& [r, m] : rem_mod) {
    if (x % m != r) {
      return std::nullopt;
    }
  }
  return std::pair(x, n);
}

// k (k + 1) = 2 a N
// x = gcd(k, 2 N)
// k / x * (k + 1) = 2 N / x * a
// y = 2 N / x
// k mod x = 0
// k mod y = -1
int main() {
  auto start_time = std::chrono::steady_clock::now();
  std::mt19937 thanos(
      (std::uint_fast32_t)start_time.time_since_epoch().count());
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  std::cout.precision(24);
  long long n;
  cin >> n;
  long long ans = 2 * n;
  for (long long x = 1; x * x <= 2 * n; ++x) {
    if (2 * n % x != 0) {
      continue;
    }
    long long y = 2 * n / x;
    for (int i = 0; i < 2; ++i) {
      vector<pair<long long, long long>> rem_mod = {{0, x}, {y - 1, y}};
      auto crt = chinese_remainder(rem_mod);
      if (crt && crt->first != 0) {
        ans = min(ans, crt->first);
      }
      swap(x, y);
    }
  }
  cout << ans << '\n';
  return 0;
}

