std::vector<ll> enumerateDivisors(ll n) {
	std::vector<ll> l, r;
	for (ll i = 1; i * i <= n; ++i) {
		auto d = std::div(n, i);
		if (d.rem) continue;
		l.emplace_back(i);
		if (d.quot != i) r.emplace_back(d.quot);
	}
	l.insert(l.end(), r.rbegin(), r.rend());
	return l;
}

signed main() {
	INIT;

	VAR(i64, n);
	auto v = enumerateDivisors(2 * n);
	i64 mi = INFLL;
	for (auto x : v) {
		if (x * x < 2 * n) continue;
		// k | x && (k+1) | (2n/x)
		// (k+1) | x && k | (2n/x)
		// k | (2n/x) && (k+1) | x
		// (k+1) | (2n/x) && k | x

		for (i64 k = x; k <= 2 * n; k += x) {
			if ((k + 1) % (2 * n / x) == 0) CHMIN(mi, k);
			if ((k - 1) % (2 * n / x) == 0) CHMIN(mi, k - 1);
		}
	}
	OUT(mi)BR;

	return 0;
}

