// 例えば -17 を 5 で割った余りは本当は 3 (-17 ≡ 3 (mod. 5))
// しかし単に -17 % 5 では -2 になってしまう
inline __int128_t mod(__int128_t a, __int128_t m) {
    return (a % m + m) % m;
}

// 拡張 Euclid の互除法
// ap + bq = gcd(a, b) となる (p, q) を求め、d = gcd(a, b) をリターンします
__int128_t extGcd(__int128_t a, __int128_t b, __int128_t &p, __int128_t &q) {
    if (b == 0) {p = 1; q = 0; return a; }
    __int128_t d = extGcd(b, a%b, q, p);
    q -= a/b * p;
    return d;
}

// 中国剰余定理
// リターン値を (r, m) とすると解は x ≡ r (mod. m)
// 解なしの場合は (0, -1) をリターン
pair<__int128_t, __int128_t> ChineseRem(__int128_t b1, __int128_t m1, __int128_t b2, __int128_t m2) {
  __int128_t p, q;
  __int128_t d = extGcd(m1, m2, p, q); // p is inv of m1/d (mod. m2/d)
  if ((b2 - b1) % d != 0) return make_pair(0, -1);
  __int128_t m = m1 * (m2/d); // lcm of (m1, m2)
  __int128_t tmp = (b2 - b1) / d * p % (m2/d);
  __int128_t r = mod(b1 + m1 * tmp, m);
  return make_pair(r, m);
}

template<typename T> map<T,int> prime_factor(T n){
    map<T,int> res;
    for (T i=2;i*i<=n;++i){
        while (n%i==0){
            ++res[i]; n/=i;
        }
    }
    if (n!=1) res[n]=1;
    return res;
}

int main(){
