    ll N; cin >> N; N*=2;

    map<ll,int> pri=prime_factor(N);
    int n=pri.size();
    vector<ll> POW;
    for (auto p:pri){
        ll cnt=1;
        for (int i=0;i<p.second;++i){
            cnt*=p.first;
        }
        POW.emplace_back(cnt);
    }

    ll ans=IINF;
    for (int mask=0;mask<(1<<n);++mask){
        ll a=1,b=1;
        for (int i=0;i<n;++i){
            if (mask&1<<i) a*=POW[i];
            else b*=POW[i];
        }
        __int128_t r=ChineseRem(0,a,b-1,b).first;
        if (r>IINF) continue;
        if (r==0) continue;
        ans=min(ans,(ll)r);
    }

    cout << ans << '\n';
}

