template <typename T>
constexpr T gcd(T a, T b, T& x, T& y) {
  static_assert(std::is_integral_v<T>);
  T xx = y = 1;
  T yy = x = 0;
  while (a != 0) {
    T q = b / a;
    T t = a;
    a = b - q * a;
    b = t;
    t = xx;
    xx = x - q * xx;
    x = t;
    t = yy;
    yy = y - q * yy;
    y = t;
  }
  if (b < 0) {
    b = -b;
    x = -x;
    y = -y;
  }
  return b;
}

template <typename T>
std::optional<std::pair<T, T>> chinese_remainder(
    const std::vector<std::pair<T, T>>& rem_mod) {
  static_assert(std::is_integral_v<T>);
  T x = 0, n = 1;
  for (const auto& [r, m] : rem_mod) {
    T inv_m, inv_n, g = gcd(m, n, inv_m, inv_n);
    x = x * inv_m * (m / g) + r * inv_n * (n /= g);
    if ((x %= (n *= m)) < 0) {
      x += n;
    }
  }
  for (const auto& [r, m] : rem_mod) {
    if (x % m != r) {
      return std::nullopt;
    }
  }
  return std::pair(x, n);
}

