		for (lint a = 2; a * a <= n; ++a) {
			if (n % a == 0 && gcd(a, n / a) == 1) {
				const lint b = n / a;

				chmin(ans, a * modinv(a, b) - 1);
				chmin(ans, b * modinv(b, a) - 1);
			}
		}

		cout << ans << endl;
	}
}

