ll bn(ll vl) {
	ll l = 0, r = INF2;

	while (r - l > 1) {
		ll mid = (l + r) / 2;
		if ((mid * (mid + 1)) / 2 >= vl) {
			r = mid;
		}
		else {
			l = mid;
		}
	}

	return r;
}

