		x *= a; if(x && x - 1 < ans) ans = x - 1;
		std::swap(a, b);
		exgcd(a, b);
		x = (x % b + b) % b, y = (x % a + a) % a;
		if(x * a == 1) x += b;
	//	std::printf("%lld %lld %lld %lld\n", a, b, (ll)x, (ll)y);
		x *= a; if(x && x - 1 < ans) ans = x - 1;
	}
