/**
 * @brief Divisor(約数列挙)
 * @docs docs/divisor.md
 */
vector< int64 > divisor(int64 n) {
  vector< int64 > ret;
  for(int64 i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      ret.push_back(i);
      if(i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return ret;
}

template< typename T >
T extgcd(T a, T b, T &x, T &y) {
  T d = a;
  if(b != 0) {
    d = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  } else {
    x = 1;
    y = 0;
  }
  return d;
}


int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  int64 n;
  cin >> n;
  int64 ans = llinf;
  auto divs = divisor(2*n);
  for(auto d : divs){
    int64 e = 2*n/d;
    if(gcd(d,e) > 1)continue;
    int64 x,y;
    extgcd(d,e,x,y);
    while(x < 0){
      x += e;
      y -= d;
    }
    while(x >= 0){
      x -= e;
      y += d;
    }
    chmin(ans,-d*x);
  }
  ANS(ans);
  return 0;
}

