ll gcd( ll m, ll n ){ // m/n
    if( n==0 ) return m;
    return gcd( n, m%n);
}

ll min_ll(ll a,ll b){
    if(a>b) return b;
    return a;
}

ll bst( ll n1, ll n2, ll N ){
    if( (n1*(n1+1) )%N != 0 ){
        ll  m = (n1*(n1+1) )/N;
        if( n2*(n2+1)<(m+1)*N ) return N;
    }
    if( n2 - n1 == 1 ){
        ll ans0 = N;
        ll q = N/gcd(N,n1);
        if( (n1+1)%q == 0 ) ans0 = min_ll(ans0,n1);
        if( n1>1 and (n1-1)%q == 0 )  ans0 = min_ll(ans0,n1-1);
        return ans0;
    }
    ll piv = (n1+n2)/2;
    ll ans1 = bst(n1,piv,N);
    ll ans2 = bst(piv,n2,N);
    if( ans1 < ans2 ) return ans1;
    return ans2;
}

