//atcoder crt but i removed the comments to make shorter and then added a comment for you to read right now. :)
pair<long long, long long> inv_gcd(long long a, long long b) {
    if (a == 0) return { b, 0 };
    long long s = b, t = a;
    long long m0 = 0, m1 = 1;
    while (t) {
        long long u = s / t;
        s -= t * u;
        m0 -= m1 * u;
        swap(s, t);
        swap(m1, m0);
    }
    if (m0 < 0) m0 += b / s;
    return { s, m0 };
}


pair<ll, ll> crt(vector<ll>& r, vector<ll>& m) {
    int n = r.size();
    ll r0 = 0, m0 = 1;
    for (int i = 0; i < n; i++) {
        ll r1 = ((r[i] % m[i]) + m[i]) % m[i];
        ll m1 = m[i];
        if (m0 < m1) {
            swap(r0, r1);
            swap(m0, m1);
        }
        if (m0 % m1 == 0) {
            if (r0 % m1 != r1) return { 0, 0 };
            continue;
        }
        ll g, im;
        std::tie(g, im) = inv_gcd(m0, m1);

        long long u1 = (m1 / g);
        if ((r1 - r0) % g) return { 0, 0 };
        long long x = (r1 - r0) / g % u1 * im % u1;
        r0 += x * m0;
        m0 *= u1;
        if (r0 < 0) r0 += m0;
    }
    return { r0, m0 };
}

