    for (int i = 0; i < (1 << (v.size())); i++) {
        ll x = 1;
        ll y = 1;
        for (int j = 0; j < v.size(); j++) {
            if (i & (1 << j)) x *= v[j];
            else y *= v[j];
        }
        //find candidate for k+1, 1 mod x, 0 mod y
        vector<ll> a({ 1, 0 });
        vector<ll> b({ x, y });
        auto ans = crt(a, b);
        if (ans.first == 0) ans.first += ans.second;
        if (ans.first == 1) ans.first += ans.second;
