//Prime Factorization(素因数分解)
//ペア{素因数、個数}の配列で返す
std::vector<std::pair<ll, int>> PF(ll n){
    std::vector<std::pair<ll, int>> divisor;
    ll upplim = sqrt(n);
    for(int i = 2; i <= upplim; i++){
        if(n % i) continue;
        int cnt = 0;
        while(!(n % i)){
            cnt++;
            n /= i;
        }
        divisor.push_back({i, cnt});
    }
    if(n != 1) divisor.push_back({n, 1});
    return divisor;
}

long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

