        (a *= a); x /= 2;
    }
    return ret;
}

int main(){
    ll i,j,n; cin >> n;
    if(n==1){
        cout << 1 << endl;
        return 0;
    }
    n *= 2;
    ll ans = n - 1;
    for(i=2;i*i<=n;i++){
        while(n%i==0){
            n /= i; mp[i]++;
        }
    }
    if(n!=1) mp[n]++;
    for(auto x:mp) v.push_back(x);
    int k = v.size();
    for(i=0;i<(1<<k);i++){
        ll x = 1,y = 1;
        for(j=0;j<k;j++){
            ll s = v[j].first,t = v[j].second;
            if(i & (1<<j)) x *= pw(s,t);
            else y *= pw(s,t);
