bool check(long long k, long long N) {
    if (k <= 0) return false;
    return (__int128) k * (k + 1) / 2 % N == 0;
}

long long f(long long N) {
    int k = 1;
    while (true) {
        if (k * (k + 1) / 2 % N == 0) {
            return k;
        }
        k++;
    }
    return -1;
}


vector<long long> g(long long N) {
    vector<long long> X;
    for (long long i = 2; i * i <= N; i++) {
        if (N % i == 0) {
            int c = 0;
            long long W = 1;
            while (N % i == 0) {
                c++;
                N /= i;
                W *= i;
            }
            X.push_back(W);
        }
    }
    if (N > 1) {
        X.push_back(N);
    }
    sort(X.begin(), X.end());

    return X;
}

typedef long long Int;

Int gcd(Int a, Int b) {
    return b != 0 ? gcd(b, a % b) : a;
}

Int lcm(Int a, Int b) {
    return a * b / gcd(a, b);
}

// a x + b y = gcd(a, b)
Int extgcd(Int a, Int b, Int &x, Int &y) {
    Int g = a;
    x = 1;
    y = 0;
    if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
    return g;
}

void solve(long long N) {
    auto X = g(2 * N);
    ll ans = 1e18;
    for (int i = 0; i < (1 << X.size()); i++) {
        long long x = 1;
        long long y = 1;
        for (int j = 0; j < X.size(); j++) {
            if (i >> j & 1) {
                x *= X[j];
            } else {
                y *= X[j];
            }
        }
        long long aa, bb;
        extgcd(x, y, aa, bb);
        long long W = max(x * aa, y * bb);
        if (check(W, N)) ans = min(W, ans);
        if (check(W - 1, N)) ans = min(W - 1, ans);
        if (check(W + 1, N)) ans = min(W + 1, ans);

    }
    cout << ans << endl;

}

