ll safe_mod(ll x,ll m){
    x %= m;
    if (x < 0) x += m;
    return x;
}
pair<long long, long long> inv_gcd(long long a, long long b) {
    a = safe_mod(a,b);
    if (a == 0) return {b, 0};
    long long s = b, t = a;
    long long m0 = 0, m1 = 1;

    while (t) {
        long long u = s / t;
        s -= t * u;
        m0 -= m1 * u; 
        auto tmp = s;
        s = t;
        t = tmp;
        tmp = m0;
        m0 = m1;
        m1 = tmp;
    }
    if (m0 < 0) m0 += b / s;
    return {s, m0};
}
pair<long long, long long> crt(const vector<long long>& r,
                                    const vector<long long>& m) {
    int n = int(r.size());
    long long r0 = 0, m0 = 1;
    for (int i = 0; i < n; i++) {
        long long r1=safe_mod(r[i], m[i]), m1 = m[i];
        if (m0 < m1) {
            swap(r0, r1);
            swap(m0, m1);
        }
        if (m0 % m1 == 0) {
            if (r0 % m1 != r1) return {0, 0};
            continue;
        }
        long long g, im;
        P p= inv_gcd(m0, m1);
        g=p.fi;im=p.se;
        long long u1 = (m1 / g);
        if ((r1 - r0) % g) return {0, 0};
        long long x = (r1 - r0) / g % u1 * im % u1;
        r0 += x * m0;
        m0 *= u1; 
        if (r0 < 0) r0 += m0;
    }
    return {r0, m0};
}
