long long myPow(int x,int n){
    lint res=1;
    lint cur=x;
    while(n>0){
        if(n&1){
            res*=cur;
        }
        n/=2;cur*=cur;
    }
    return res;
}
signed main(){
  lint n;cin>>n;
  map<lint,int> prime;
  lint bbuf=n*2;
