        x+=b;y-=a;
      }
      buf=min(buf,min(abs(a*x),abs(b*(-y))));
      x+=b;y-=a;
      buf=min(buf,min(abs(a*x),abs(b*y)));
    }
    if(buf==0)continue;
    res=min(res,buf);
  }
  cout<<res<<"\n";
  return 0;
}

