// (Generalised) Chinese remainder theorem (for arbitrary moduli):
// Solves x from system of equations x == a_i (mod m_i),
// giving answer modulo m = lcm(m_1,...,m_n)
// Runs in O(log(m)+n) time
// Overflows only if m overflows
// Returns {1, {x, m}} if solution exists, and {-1, {0,0}} otherwise
ll ee(ll ca, ll cb, ll xa, ll xb, ll&x) {
	if (cb) return ee(cb, ca%cb, xb, xa-(ca/cb)*xb, x);
	x = xa;
	return ca;
}
pair<int, pair<ll, ll>> crt(vector<ll> as, vector<ll> ms) {
	ll aa = 0, mm = 1, d, a, x;
	for (int i = 0; i < (int) as.size(); i++) {
		d = ee(ms[i], mm, 1, 0, x);
		if ((aa-as[i])%d) return {-1,{0,0}};
		a = ms[i]/d;
		mm *= a;
		aa = (as[i] + (aa-as[i])*(((lll)a*x)%mm))%mm;
	}
	if (aa < 0) aa += mm;
	return {1, {aa, mm}};
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	ll n;
	cin >> n;
	if (n == 1) {
		cout << 1 << '\n';
		return 0;
	}
	ll res = n;

	// \sum_{i = 1}^{k} i = k(k+1)/2

	// For prime powers p^t:
	//	either k or k-1 is a multiple of p^t
	// We can loop for 

	// Can we efficiently find the smallest integer K such that K = 0 (mod A) and K = -1 (mod B)
	// Obviously, this is just the chinese remainder theorem!

	vector<ll> parts;
	for (ll k = 2; k*k <= n; ++k) {
		if (n % k == 0) {
			ll val = k;
			while (n % (val*k) == 0) {
				val *= k;
			}
			n /= val;
			if (val % 2 == 0) val *= 2; // to account for /2
			parts.push_back(val);
		}
	}
	if (n > 1) parts.push_back(n);

	int h = parts.size();
	for (int mask = 0; mask < (1 << h); ++mask) {
		ll a = 1, b = 1;
		for (int i = 0; i < h; ++i) {
			if (mask & (1 << i)) a *= parts[i];
			else b *= parts[i];
		}
		// Min integer that is 0 (mod a) and -1 (mod b)
		if (a == 1) res = min(res, b-1);
		else if (b == 1) res = min(res, a);
		else {
			auto tmp = crt({0, b-1}, {a, b});
			res = min(res, tmp.second.first);
		}
	}
	cout << res << '\n';
}

