vector<pair<ll, int>>factorize(ll x) {
	vector<pair<ll, int>>ret;
	for (ll i = 2; i*i <= x; i++) {
		if (x % i == 0) {
			pair<ll, int> res = { i,0 };
			while (x%i == 0) {
				res.second++;
				x /= i;
			}
			ret.push_back(res);
		}
	}
	if (x != 1) {
		ret.push_back({ x,1 });
	}
	return ret;
}


ll extGCD(ll a, ll b, ll &x, ll &y) {
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}
	ll d = extGCD(b, a%b, y, x);
	y -= a / b * x;
	return d;
}
void solve() {
	long long N; cin >> N;
	int M = 2 * N;
	if (N <= 1e6) {
		FOR(i, 1, N + 1) {
			ll a = i * (i + 1)/2;
			if (a%N == 0) {
				cout << (long long)i << endl;
				return;
			}
		}
	}
	vector<pii>factors = factorize(M);
	int sz = factors.size();
	vector<int>f(sz);
	REP(i, sz) {
		ll x = 1;
		REP(_, factors[i].second)x *= factors[i].first;
		f[i] = x;
	}
	ll ans = LINF;
	REP(bit, 1LL << sz) {
		ll a = 1, b = 1;
		REP(i, sz) {
			if (bit&(1LL << i)) {
				a *= f[i];
			}
			else b *= f[i];
		}
		a *= -1;
		ll x, y;
		extGCD(a, b, x, y);
		if (x >= 1 && y >= 1) {
			ll k = -a * x;

			chmin(ans, k);
		}
	}
	cout << (long long)ans << endl;
}




