void exgcd(ll a, ll b, ll &x, ll &y) {
	if (!b) return x = 1, y = 0, void();
	exgcd(b, a % b, x, y); 
	ll t = x; x = y, y = t - y * (a / b);
}

const int N = 2256;
ll st[N], X, x, y, tp, n;
int main() {
	read(n), X = n * 2;
	if (X % 2 == 0) {
		st[++tp] = 1;
		while (X % 2 == 0) X /= 2, st[tp] *= 2;
	}
	for (ll i = 3;i * i <= X; i += 2) {
		if (X % i == 0) {
			st[++tp] = 1;
			while (X % i == 0) X /= i, st[tp] *= i;
		}
	}
	if (X != 1) st[++tp] = X;
	int lim = (1 << tp) - 1;
	ll ans = 1e15;
	for (int i = 0;i <= lim; i++) {
		ll A = 1, B = 1;
		for (int j = 1;j <= tp; j++)
			if (i >> (j - 1) & 1) A = A * st[j];
			else B = B * st[j];
		exgcd(A, B, x, y);
		if (A > B) {
			x = (x % B + B) % B;
			if (!x) x += B;
			Mn(ans, x * A - 1);
		}
		else {
			y = (y % A + A) % A - A; 
			Mn(ans, - y * B);
		}
	}
	write(ans);
	return 0;
}

