vector<pair<long long,int>> prime_divs(long long x){
	vector<pair<long long,int>> res;
	for(long long i=2;i*i<=x;i++){
		if(x%i!=0) continue;

		int cnt=0;
		while(x%i==0){
			x/=i;
			cnt++;
		}
		res.push_back(make_pair(i,cnt));
	}
	if(x>1) res.push_back(make_pair(x,1));
	return res;
}
__int128 inv(__int128 a,__int128 mod){
	__int128 b=mod,p=1,q=0;
	while(b){
		__int128 c=a/b,d=a;
		a=b;
		b=d%b;
		d=p;
		p=q;
		q=d-c*q;
	}
	return (p+mod)%mod;
}

