	int n=(int)pds.size();

	long long res=x-1;
	for(int i=0;i<(1<<n);i++){
		long long le=1,ri=1;
		for(int j=0;j<n;j++){
			if((i>>j)&1){
				for(int k=0;k<pds[j].second;k++) le*=pds[j].first;
			}else{
				for(int k=0;k<pds[j].second;k++) ri*=pds[j].first;
			}
		}

		if(le==1 || ri==1) continue;
		__int128 invle=inv(le,ri);
		if((res+1)/le>=invle){
			res=min(res,(long long)(le*invle-1));
		}
	}
	cout << res << "\n";
	return 0;
}

