ll iterative_pow(ll x,ll power) {
	ll res = 1;
	ll k = power;
	ll y = x;
	while (k) {
		if (k & 1)res = (res*y);
		y = y*y;
		k /= 2;
	}
	return res;
}

ll ext_gcd(ll a,ll b,ll &x,ll &y){
    if(b==0){
        x=1;
        y=0;
        return a;
    }
    ll x2,y2;
    ll d = ext_gcd(b,a%b,x2,y2);
    x = y2;
    y = x2 - (a/b)*y2;
    return d;
}


ll mod_inv(ll a,ll m){
    ll x,y;
    ll d = ext_gcd(a,m,x,y);
    if(d!=1){
        return -1;
    }
    x %= m;
    if(x<0)x += m;
    return x;
}


ll garner(vector<ll> r,vector<ll>m){
    int n = r.size();
    ll m_prod = 1;
    ll x = (r[0]+m[0])%m[0];
    x = (x+m[0])%m[0];
    for(int i=1;i<n;i++){
        m_prod *= m[i-1];
        ll Inv = mod_inv(m_prod,m[i]);
        ll t = ((r[i]-x)*Inv)%m[i];
        if(t<0)t+=m[i];
        x += t*m_prod;
    }
    return x;
}


