template<class INT>
std::vector<INT> factorize(INT n){
    std::vector<INT> res;
    for (INT i = 1; i * i <= n; i++){
        if (n % i == 0){
            res.push_back(i);
            if (i * i != n)
                res.push_back(n / i);
        }
    }
    return res;
}

u_int seed = 1;
u_int xor_shift(){
    seed ^= seed << 1;
    seed ^= seed >> 3;
    seed ^= seed << 10;
    return seed;
}


int main(){
    int64_t n;
    cin >> n;
    if (n == 1){
        puts("1");
        return 0;
    }
    auto res = factorize(n);
    sort(res.begin(), res.end());
    int64_t upper = n % 2 == 0 ? 2 * n - 1 : n - 1;
    int m = res.size();
    for (int i = 0; i < int(3e7); i++){
        while (upper < res[m - 1]) m--;
        auto k = res[xor_shift() % m];
        int64_t d = xor_shift() % (upper / k);
        if (d == 0) d++;
        auto r = k * d;
        if (r == 1)
            continue;
        if (r * (r - 1) / 2 % n == 0){
            upper = r - 1;
            continue;
        }
        if (r * (r + 1) / 2 % n == 0){
            upper = r;
        }
    }

    cout << upper << endl;
}

