using namespace std;

int64_t solve(int64_t n)
{
	int64_t bottom = 0;
	int64_t up = ceil(sqrt(n));

	while (bottom + 1 < up) {
		int64_t m = (bottom + up) / 2;
		int64_t v = m * m + m;
		if (v == n) {
			return m;
		}
		if (v < n) {
			bottom = m;
		}
		else {
			up = m;
		}
	}
	return 0;

}

