  if(N>1) {
    p.push_back(N);
    r.push_back(1);
  }

  if(r.front()==1 and p.back()>n) {
    cout << ans << newl;
    return 0;
  }

  ll ps = p.size();
  vl P(ps);
  rep(i, ps) P[i] = pow(p[i], r[i]);

  rep(i, 1 << (ps-1)) {
    vb choose(ps, 0);
    rep(j, ps-1) if(i ^ (2 << j)) choose[j]=1;
    ll a=1, b=1;
    rep(j, ps) {
      if(choose[j]) a *= P[j];
      else b *= P[j];
    }

    chmin(ans, extended_euclidian(a, b));
  }
  cout << ans << newl;
  return 0;
}

