//拡張ユークリッド
//ax+by=gcd(a,b)の解
ll extgcd(ll a,ll b,ll &x,ll &y){
	ll d=a;
	if(b){
		d=extgcd(b,a%b,y,x);
		y-=(a/b)*x;
	}else{
		x=1,y=0;
	}
	return d;
}

//中国剰余定理
//https://qiita.com/drken/items/ae02240cd1f8edfc86fd
//リターン値 (r,m) x¥equiv r (mod m)
P CRT (vector<ll> &b,const vector<ll> &m){
	ll r=0,M=1;
	rep(i,b.size()){
        b[i]=(b[i]%m[i]+m[i])%m[i];
		ll p,q;
		ll d=extgcd(M,m[i],p,q);
		if((b[i]-r)%d!=0) return P(0,-1);
		ll tmp=(b[i]-r)/d*p%(m[i]/d);
		r+=M*tmp;
		M*=m[i]/d;
	}
	return P((r%M+M)%M,M);
}

//約数列挙
template <class T>
vector<T> divisor(T x){
    vector<T> res;
    for(T i=1;i*i<=x;i++){
        if(x%i==0){
            res.push_back(i);
            if(i!=x/i){
                res.push_back(x/i);
            }
        }
    }
    return res;
}

int main(){
    cin.tie(0);ios::sync_with_stdio(false);
    ll n;
    cin>>n;
    ll ans=inf;
    for(auto x:divisor(2*n)){
        vector<ll> b={0,-1},m={x,2*n/x};
        P ret=CRT(b,m);
        if(ret.se==-1) continue;
        if(ret.fi==0) ret.fi+=ret.se;
        chmin(ans,ret.fi);
    }
    cout<<ans<<endl;
}

