std::vector<T> unsortedDivisors(const T& n) {
    std::vector<T> result;
    for (T i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            result.push_back(i);
            if (i * i != n) {
                result.push_back(n / i);
            }
        }
    }
    return result;
}

template <typename T>
std::vector<T> sortedDivisors(const T& n) {
    auto divisors = unsortedDivisors(n);
    sort(all(divisors));
    return divisors;
}

template<typename T>
std::vector<T> primeDivisors(T n) {
    std::vector<T> result;
    for (T i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            result.push_back(i);
            while (n % i == 0) {
                n /= i;
            }
        }
    }
    if (n > 1) {
        result.push_back(n);
    }
    return result;
}

template<typename T>
vector<pair<T, int>> factorize(T n) {
    vector<pair<T, int>> result;
    for (T i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            int power = 0;
            while (n % i == 0) {
                power++;
                n /= i;
            }
            result.push_back({i, power});
        }
    }
    if (n > 1) {
        result.push_back({n, 1});
    }
    return result;
}

