vector<pair<LL, LL>> prime_factorization(LL x) {
	assert(x > 0);
	vector<pair<LL, LL>> f;
	for(LL i = 2; i <= x; i++) {
		if(i * i > x) { i = x; }
		if(x % i == 0) {
			f.EB(i, 0);
			while(x % i == 0) { f.back().SE++; x /= i; }
		}
	}
	return f;
}

vector<LL> divisors(LL x) {
	auto pf = prime_factorization(x);
	vector<LL> d = { 1 };
	for(auto e: pf) {
		int ds = d.size();
		inc(i, ds) {
			LL v = d[i];
			inc(j, e.SE) { v *= e.FI; d.PB(v); }
		}
	}
	sort(ALL(d));
	return d;
}

