__int128 bin_pow(__int128 base,__int128 deg,__int128 mod)
{
    if (deg==0)
        return 1;
    __int128 t=bin_pow(base,deg/2,mod);
    if (deg&1)
        return t*t%mod*base%mod;
    else
        return t*t%mod;
}
void solve()
{
    ll n;
    cin>>n;
    n*=2;
    ll was=n;
    vector <pll> p;
    vector <ll> x;
    for (ll i=2;i*i<=n;i++)
    {
        if (n%i==0)
        {
            int cnt=0;
            ll y=1;
            while (n%i==0)
                cnt++,n/=i,y*=i;
            x.pb(y);
            p.pb({i,cnt});
        }
    }
    if (n>1)
        p.pb({n,1}),x.pb(n);
    int sz=p.size();
    ll ans=INFLL;
    for (int mask=0;mask<(1<<sz);mask++)
    {
        __int128 a=1;
        for (int i=0;i<sz;i++)
        {
            if ((mask>>i)&1)
                a*=x[i];
        }
        __int128 b=was/a;
        __int128 phi=1;
        for (int i=0;i<sz;i++)
        {
            if ((mask>>i)&1)
                continue;
            phi*=x[i];
            phi/=p[i].fi;
            phi*=p[i].fi-1;
        }
        __int128 now=b-1;
        now=(now*bin_pow(a,phi-1,b))%b;
        if (now==0)
            ans=min(ans,(ll)(a*b));
        else {
            ans = min(ans, (ll)(now * a));
        }
    }
    cout<<ans<<'\n';
}

