void Eratosthenes() {
    is_prime[0] = is_prime[1] = false;
    for (long long i = 2;i*i < MAX_N;++i) if (is_prime[i]) for (long long j = 2*i;j < MAX_N;j += i) is_prime[j] = false;
    for (long long i = 0;i < MAX_N;++i) if (is_prime[i]) prime.push_back(i);
}

vector<pair<long long,int>> prime_factorization(long long a) {
    vector<pair<long long,int>> prime_factor;
    if (is_prime[0]) Eratosthenes();
    for (long long& i : prime) {
        if (i*i > a) break;
        if (a%i == 0) {
            pair<long long,long long> p = make_pair(i,0);
            while (a%i == 0) {
                a /= i;
                p.second++;
            }
            prime_factor.push_back(p);
        }
    }
    if (a != 1) prime_factor.push_back(make_pair(a,1));
    return prime_factor;
}

void rec(vector<long long>& div,vector<pair<long long,int>>& fact,int i,long long d) {
    if (i == fact.size()) {
        div.push_back(d);
        return;
    }
    for (int j = 0;j <= fact[i].second;++j) {
        rec(div,fact,i+1,d);
        d *= fact[i].first;
    }
}

// unsorted
vector<long long> divisor(long long a) {
    vector<long long> div;
    vector<pair<long long,int>> prime_factor = prime_factorization(a);
    rec(div,prime_factor,0,1);
    return div;
}

ll extGcd(ll a,ll b,ll &p,ll &q) {
    if (b == 0) {
        p = 1;
        q = 0;
        return a;
    }  
    ll d = extGcd(b,a%b,q,p);  
    q -= a/b*p;  
    return d;  
}

