map<ll, ll> factorize(ll N) {
  map<ll, ll> count;
  for (int i = 0; primes[i] * primes[i] <= N; i++) {
    while (N % primes[i] == 0) {
      count[primes[i]]++;
      N /= primes[i];
    }
  }
  if (N != 1) count[N]++;
  return count;
}


