ll inv(ll a, ll m){ 
    ll m0 = m, t, q; 
    ll x0 = 0, x1 = 1; 

    if (m == 1) return 0; 
    while (a > 1){
        q = a / m; 

        t = m;
        m = a % m, a = t; 

        t = x0; 

        x0 = x1 - q * x0; 

        x1 = t; 
    } 
    if (x1 < 0) 
       x1 += m0; 

    return x1; 
} 

ll findMinX(vll num, vll rem){
    ld prod = 1;
    for(int i = 0; i < 2; i++) 
        prod = prod * num[i];
    ll result = 0;
    for(int i = 0; i < 2; i++){
        ll pp = prod / num[i]; 
        result = fmod(result + fmod(fmod(rem[i] * fmod(inv(pp, num[i]), prod), prod) * pp,prod),prod);
    }
    return result;
}

