vector<pll> pf(ll x) {
	vector<pll> res;
	ll p = 2;
	while (p * p <= x) {
		if (x % p == 0) {
			ll d = 0;
			while (x % p == 0) {
				x /= p;
				d++;
			}
			res.push_back(pll(p, d));
		}
		p++;
	}
	if (x > 1) res.push_back(pll(x, 1));
	return res;
}

ll solve(int i, vl &m) {
	vl r; // 余り(0 or -1)
	rep(j, m.size()) {
		if (i & (1 << j)) {
			r.push_back(m[j] - 1);
		} else {
			r.push_back(0);
		}
	}
	// dbl(i); dbl(r);
	auto [res, M] = crt(r, m);
	// dbs(res, M);
	return res;
}

int main() {
	ll N; cin >> N;
	vector<pll> v = pf(N * 2); // 2Nの素因数分解
	int d = v.size(); // 2Nの異なる素因数の個数
	// rep(i, d) {
	// 	dbs(v[i].first, v[i].second);
	// }
	vl m; // 法
	rep(i, d) {
		ll t = 1;
		rep0(v[i].second) t *= v[i].first; // p^d
		m.push_back(t);
	}
	// dbl(m); // 法
	ll ans = INF;
	rep2(i, 1, 1 << d) { // 0以外の2^d-1通り試す
		chmin(ans, solve(i, m)); // i(に対応するベクトル),法
	}
	cout << ans << endl;
}

