signed main(){
  lint n;cin>>n;
  map<lint,int> prime;
  lint bbuf=n*2;
  for(int i=2;i*i<=n*2;++i){
    if(bbuf%i==0){
      bbuf/=i;
      prime[i]+=1;
    }
  }
  if(bbuf>1)prime[bbuf]+=1;
  vector<pair<lint,int>> primes;
  for(auto& val:prime){
    primes.push_back({val.first,val.second});
  }
  lint num=primes.size();
  lint res=inf;
  for(lint bit=0;bit<(1<<num);++bit){
    lint a=1;lint b=1;
    lint buf=inf;
    lint x,y;
    for(int i=0;i<num;++i){
      if(bit&(1<<i)){
        a*=myPow(primes[i].first,primes[i].second);
      }
      else{
        b*=myPow(primes[i].first,primes[i].second);
      }
    }
    if(a==inf){
      res=min(res,b-1);
      continue;
    }
    if(b==inf){
      res=min(res,a-1);
      continue;
    }
    extGCD(a,b,x,y);
    if(x>0){
      while(x>b){
        x-=b;y+=a;
      }
      buf=min(buf,min(abs(a*x),abs(b*(-y))));
      x-=b;y+=a;
      buf=min(buf,min(abs(a*x),abs(b*y)));
    }
    else{
      while(x<-b){
        x+=b;y-=a;
      }
      buf=min(buf,min(abs(a*x),abs(b*(-y))));
      x+=b;y-=a;
      buf=min(buf,min(abs(a*x),abs(b*y)));
    }
    if(buf==0)continue;
    res=min(res,buf);
  }
  cout<<res<<"\n";
  return 0;
}

