using namespace std;
typedef int64_t ll;
typedef long double ld;

vector<bool> furui_bool(ll n) {
  vector<bool> fu(n + 1, 1);
  fu.at(0) = 0; fu.at(1) = 0;
  for (ll i=2; i <= n/2 + 1; i++) {
    if (fu.at(i) == 1) {
      ll j = 2 * i;
      while (j <= n) {
        fu.at(j) = 0;
        j += i;
      }
    }
  }
  return fu;
}

vector<ll> prime_fac(ll n, ll &mx) {
  ll sq = sqrt(n);
  vector<ll> pr(sq + 1, 0);
  vector<bool> fu = furui_bool(sq + 2);
  for (ll i=2; i <= sq; i++) {
    if (fu.at(i)) {
      while (n % i == 0) {
        n /= i;
        mx = i;
        pr.at(i)++;
      }
    }
  }
  if (n > 1) {
    mx = n;
  }
  return pr;
}

int main() {
  ll n;
  cin >> n;
  if(n==1){cout<<1<<endl;return 0;}
  if(n%2==0)n*=2;
  ll mx=1,facpowmax=1;
  vector<ll> out = prime_fac(n,mx);
  for(ll i=2; i <= sqrt(n); i++){
    if(out.at(i) >= 1)facpowmax=max(facpowmax,(ll)pow(i,out.at(i)));
  }
  if(mx > sqrt(n))facpowmax=max(facpowmax,mx);
  if(n%2==0)n/=2;
  for(ll i=facpowmax;i<=(n%2==0 ? 2*n : n);i+=facpowmax){
    if(i*(i-1)/2%n==0){cout<<i-1<<endl;return 0;}
    else if(i*(i+1)/2%n==0){cout<<i<<endl;return 0;}
  }
}

