const LL INF = 1e18;

LL extGCD(LL a, LL b, LL &x, LL &y){
	if(b==0){
		x=1;
		y=0;
		return a;
	}
	LL d=extGCD(b,a%b,y,x);
	y-=a/b*x;
	return d;
}

int main(){
	LL N;
	cin >> N;
	N*=2;
	LL Nc=N;
	vector<LL> div;
	for(LL d=2; d*d<=Nc; d++){
		LL res=1;
		while(N%d==0){
			N/=d;
			res*=d;
		}
		if(res>1) div.emplace_back(res);
	}
	if(N>1) div.emplace_back(N); 
	int S=div.size();
	LL ans=INF;
	rep(bit,1<<S){
		LL a=1, b=1;
		rep(i,S){
			if(bit&(1<<i)) a*=div[i];
			else b*=div[i];
		}
		LL x, y, res;
		if(a==1 or b==1) res=a*b-1;
		else{
			extGCD(a,-b,x,y);
			res=min(a*x,b*y);
			extGCD(-a,b,x,y);
			res=min(a*x,b*y);
		}
		ans=min(ans,res);
	}
	cout << ans << endl;

	return 0;
}

