long long gcd(long long x, long long y, long long &a, long long &b) {
	// debug(x, y);
	if(y == 0) {
		a = 1;
		b = 0;
		return x;
	}

	long long g = gcd(y, x % y, a, b);
	long long tmp = a;
	a = b;
	b = tmp - (x / y) * b;
	return g;
}

long long inv(long long x, long long y) {
	// inverse of x wrt y

	// debug(x, y);

	long long a, b;
	long long g = gcd(x, y, a, b);
	assert(g == 1);
	a %= y;
	if(a < 0)
		a += y;
	return a;
}

void solve() {
	long long n;
	cin >> n;
	long long res;
	if(n % 2 == 1)
		res = n;
	else
		res = n - 1;
	n *= 2;
	vector<pair<long long, long long>> fac;
	for(long long i = 2; i * i <= n; i++) {
		int cnt = 0;
		long long num = 1;
		while(n % i == 0) {
			cnt++;
			num *= i;
			n /= i;
		}
		if(cnt > 0)
			fac.push_back({i, num});
	}

	if(n > 1)
		fac.push_back({n, n});

	// for(auto pp : fac) {
	// 	cout << pp.fs << ' ' << pp.sd << '\n';
	// }
	// cout << '\n';

	int m = fac.size();

	for(int i = 0; i < (1 << m); i++) {
		long long x = 1, y = 1;
		for(int j = 0; j < m; j++) {
			if((i & (1LL << j)))
				x *= fac[j].second;
			else
				y *= fac[j].second;
		}

		if(x == 1 || y == 1) {
			// res = min(res, n);
			continue;
		}

		long long inv1 = inv(x, y);
		assert((inv1 * x - 1) % y == 0);
		res = min(res, inv1 * x - 1);

		debug(x, y, inv1, inv1 * x - 1);

		long long inv2 = (-inv1) % y;
		if(inv2 < 0)
			inv2 += y;
		assert((inv2 * x + 1) % y == 0);
		res = min(res, inv2 * x);
		debug(x, y, inv2, inv2 * x);

	}

	cout << res << '\n';

}

