ll nCk(ll N, ll K){
  if(N>1){
    ll kid = 1;
  for(ll i = N; i > N - K; i--){
      kid = kid * i;
    }
    for(ll i = 1; i < K + 1; i++){
        kid = kid / i;
    }
  return kid;
  }
  else{
    return 0;
  }
}

