ll LCS(ST s, ST t){
    ll s1 = s.size();
    ll s2 = t.size();
    Graph p(s1 + 1, vec(s2 + 2));
    rep(i,s1 + 1) {
        rep(j,s2 + 1){
            if (i > 0 && j > 0){
                if (s[i-1] == t[j-1]){
                    p[i][j] = max(p[i - 1][j - 1] + 1, max(p[i][j - 1], p[i - 1][j]));
                }
                else {
                    p[i][j] = max(p[i - 1][j], p[i][j - 1]);
                }
            }
            else {
                p[i][j] = 0;
            }
        }
    }
    ll ans = p[s1][s2];
    return ans;
}

