struct modint{
  ll x;
  modint(ll x = 0) : x((x % mod + mod) % mod){}
  modint operator-() const {
    return modint(-x);
  }
  modint& operator += (const modint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  modint& operator -= (const modint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  modint& operator *= (const modint a) { 
    (x *= a.x) %= mod; 
    return *this;
  }
  modint operator + (const modint a) const { 
    return modint(*this) += a;
  }
  modint operator - (const modint a) const { 
    return modint(*this) -= a;
  }
  modint operator * (const modint a) const { 
    return modint(*this) *= a;
  }
  modint pow(ll t) const {
    if (!t) return 1;
    modint a = pow(t >> 1);
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }
  modint inv() const { 
    return pow(mod - 2);
  }
  modint& operator /= (const modint a) {
    return *this *= a.inv();
  }
  modint operator / (const modint a) const { 
    return modint(*this) /= a;
  }
};
istream& operator >> (istream& is, modint& a) {
  return is >> a.x;
}
ostream& operator << (ostream& os, const modint& a) { 
  return os << a.x;
}

vector<P> prime_factorize(ll N) {
    vector<P> res;
    for (ll a = 2; a * a <= N; ++a) {
        if (N % a != 0) continue;
        ll ex = 0;
        while (N % a == 0) {
            ++ex;
            N /= a;
        }
        res.push_back({a, ex});
    }
    if (N != 1) res.push_back({N, 1});
    return res;
}

