std::vector<int> prime(const int upper) {
	std::vector<bool> is_prime(upper + 1, true);
	for (auto i = 2; i * i <= upper; ++i) {
		if (is_prime[i]) {
			for (auto j = i * i; j <= upper; j += i) {
				is_prime[j] = false;
			}
		}
	}
	std::vector<int> result;
	for (auto i = 2; i <= upper; ++i) {
		if (is_prime[i]) result.push_back(i);
	}
	return result;
}
std::vector<long long int> coprime_factors(long long int n) {
	const auto primes = prime(std::sqrt(n));
	std::vector<long long int> result;
	for (const auto prime : primes) {
		if ((long long int)prime * (long long int)prime > n) continue;
		if (n % prime == 0) {
			long long int p = 1;
			while (n % prime == 0) {
				p *= prime;
				n /= prime;
			}
			result.push_back(p);
		}
	}
	if (n > 1) result.push_back(n);
	return result;
}
int brute(const long long int n) {
	long long int sum{ 1 };
	auto i = 2;
	for (; sum % n != 0; ++i) {
		sum += i;
	}
	return i - 1;
}
long long int gcd(const long long int a, const long long int b) {
	return b == 0 ? a : gcd(b, a % b);
}
long long int solve(long long int n) {
	if (n == 1) {
		return 1;
	}
	const auto factor = coprime_factors(n);
	long long int min_k = n & 1 ? n - 1 : 2 * n - 1;
	for (auto i = 0; i < (1 << factor.size()); ++i) {
		long long int a{ 1 }, b{ 1 };
		for (auto j = 0; j < factor.size(); ++j) {
			if ((i >> j) & 1) {
				a *= factor[j];
			}
			else {
				b *= factor[j];
			}
		}
		const auto x = atcoder::inv_mod(a, b);
		const auto k = a * x - 1;
		if (k <= 0) continue;
		const auto rest = 2 * n / gcd(2 * n, k);
		const auto r = rest / gcd(rest, k + 1);
		if (r == 1) min_k = std::min(min_k, k);
	}
	return min_k;
}
int main() {
	long long int n; std::cin >> n;
	std::cout << solve(n) << '\n';
}

