vector<pair<long long, int>>factorize(long long x) {
	vector<pair<long long, int>>ret;
	for (long long i = 2; i*i <= x; i++) {
		if (x % i == 0) {
			pair<long long, int> res = { i,0 };
			while (x%i == 0) {
				res.second++;
				x /= i;
			}
			ret.push_back(res);
		}
	}
	if (x != 1) {
		ret.push_back({ x,1 });
	}
	return ret;
}

long long extGCD(long long a, long long b, long long &x, long long &y) {
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}
	long long d = extGCD(b, a%b, y, x);
	y -= a / b * x;
	return d;
}
void solve() {
	int N; cin >> N;
	int M = 2 * N;
	vector<pii>factors = factorize(M);
	int sz = factors.size();
	vector<int>f(sz);
	REP(i, sz) {
		int x = 1;
		REP(_, factors[i].second)x *= factors[i].first;
		f[i] = x;
	}
	ll ans = LINF;
	REP(bit, 1LL << sz) {
		int a = 1, b = 1;
		REP(i, sz) {
			if (bit&(1LL << i)) {
				a *= f[i];
			}
			else b *= f[i];
		}
		a *= -1;
		int x,  y;
		extGCD(a, b, x, y);
		if (x >= 1 && y >= 1) {
			ll k = -a * x;

			chmin(ans, k);
		}
	}
	print(ans);
}




