  //  if(df)print(sq);
  sq=min(sq,s_max);
  //  if(df)print(sq);
  if(a<sq) linear_sieve(sq,prime,seive);
  a=seive.size()-1;
  //  if(df)print("seive_size",a);
  while(n>a){
    for(int p:prime){
      while(n%p==0){
        factors[p]++;
        n/=p;
      }
      if(n<=a) break;
    }
    if(n>a){
      if(factors.size()==0){
        if(s_max<sqrt(n)+1)
          print(n,"has too large prime as factor!!!!!");
        else factors[n]++;
        return;
      }
      map<li,int> f;
      factorization(n,f);
      for(auto p:f){
        factors[p.first]+=p.second;
      }
      return;
    }
  }
  while(n!=1){
    int p=seive[n];
    factors[p]++;
    n/=p;
  }
}

