	map <ll, int> cnt;
	for (ll i = 2; i * i <= n; ++i) {
		if (n % i == 0)
			v.push_back(i);
		while (n % i == 0) {
			++cnt[i];
			n /= i;
		}
	}	
	if (n > 1) {
		++cnt[n];
		v.push_back(n);
	}
	int sz = v.size();
	ll res = INF;
	for (int mask = 0; mask < (1 << sz); ++mask) {
		ll x = 1, y = 1;
