struct Timer {
    int64_t start; const int64_t CYCLES_PER_SEC = 2800000000;
    Timer() { reset(); }
    void reset() { start = getCycle(); }
    inline double get() { return (double)(getCycle() - start) / CYCLES_PER_SEC; }
    inline int64_t getCycle() {
        uint32_t low, high; __asm__ volatile ("rdtsc" : "=a" (low), "=d" (high));
        return ((int64_t)low) | ((int64_t)high << 32);
    }
};

bool multicase = false;

void solve() {
    ll n;
    cin >> n;
    if (n == 2) {
        p(3);
        return;
    }
    vec v;
    for(ll i=2;i*i<=n;i++){
        ll res = 1ll;
        if (n % i == 0) {
            while(n % i == 0) {
                res *= i;
                n /= i;
            }
        }
        if (i == 2ll) res *= 2ll;
        if (res != 1ll) v.pb(res);
    }
    if (n != 1) v.pb(n);
    ll m = v.size();
    ll mbit = (1ll << (m - 1));
    ll ans = INF;
    for(ll i=0;i<mbit;i++){
        ll ka = 1ll, kb = 1ll;
        for(ll j=0;j<m;j++){
            if (i & (1ll << j)) {
                ka *= v[j];
            } else {
                kb *= v[j];
            }
        }
        if (ka > ans) continue;
        ll x = inv_mod(ka, kb);
        x = kb - x;
        ll res = x * ka;
        ans = min(ans, res);
    }
    p(ans);
    return;
}

