    }
    // by [3]: |m0| <= b/g
    // by g != b: |m0| < b/g
    if (m0 < 0) m0 += b / s;
    return {s, m0};
}

// (rem, mod)
std::pair<long long, long long> crt(const std::vector<long long>& r,
                                    const std::vector<long long>& m) {
    assert(r.size() == m.size());
    int n = int(r.size());
    // Contracts: 0 <= r0 < m0
    long long r0 = 0, m0 = 1;
    for (int i = 0; i < n; i++) {
        assert(1 <= m[i]);
        long long r1 = safe_mod(r[i], m[i]), m1 = m[i];
        if (m0 < m1) {
            std::swap(r0, r1);
            std::swap(m0, m1);
        }
        if (m0 % m1 == 0) {
            if (r0 % m1 != r1) return {0, 0};
            continue;
        }
        // assume: m0 > m1, lcm(m0, m1) >= 2 * max(m0, m1)

        // (r0, m0), (r1, m1) -> (r2, m2 = lcm(m0, m1));
        // r2 % m0 = r0
        // r2 % m1 = r1
        // -> (r0 + x*m0) % m1 = r1
        // -> x*u0*g % (u1*g) = (r1 - r0) (u0*g = m0, u1*g = m1)
        // -> x = (r1 - r0) / g * inv(u0) (mod u1)

        // im = inv(u0) (mod u1) (0 <= im < u1)
        long long g, im;
        std::tie(g, im) = inv_gcd(m0, m1);

        long long u1 = (m1 / g);
        // |r1 - r0| < (m0 + m1) <= lcm(m0, m1)
        if ((r1 - r0) % g) return {0, 0};

        // u1 * u1 <= m1 * m1 / g / g <= m0 * m1 / g = lcm(m0, m1)
        long long x = (r1 - r0) / g % u1 * im % u1;

        // |r0| + |m0 * x|
        // < m0 + m0 * (u1 - 1)
        // = m0 + m0 * m1 / g - m0
        // = lcm(m0, m1)
        r0 += x * m0;
        m0 *= u1;  // -> lcm(m0, m1)
        if (r0 < 0) r0 += m0;
    }
    return {r0, m0};
}

vector<ll> pr(ll a) {
    vector<ll> res;
    for (ll i = 2; i * i <= a; ++i) {
        ll val = 1;
        while(a % i == 0) {
            a /= i;
            val *= i;
        }
        if (val != 1) res.emplace_back(val);
    }
    for (int i = 0; i < res.size(); ++i) {
        if (res[i] % a == 0) {
            res[i] *= a;
            a = 1;
        }
    }
    if (a != 1) {
        res.PB(a);
    }
    return res;
}
vector<ll> d;
ll solve(int mask) {
    vector<ll> r, m;
    for (int i = 0; i < d.size(); ++i) {
        if (mask & (1 << i)) {
            m.PB(d[i]);
            r.PB(0);
        } else {
            m.PB(d[i]);
            r.PB(d[i] - 1);
        }
    }
    pair<ll, ll> res = crt(r, m);
    if (res == make_pair(0LL, 0LL)) {
        //cout << mask << endl;
        return 1e18;
        exit(1);
    }
    //cout << mask << ' ' << res.F << endl;
    //return crt(r, m).F;
    return res.F == 0 ? res.S : res.F;
}

