{
    //freopen("input.txt", "r", stdin);
    ll n;
    cin >> n;
    if (n == 1) {
        cout << 1 << endl;
        return 0;
    }
    ll ans = n - 1;
    n *= 2;
    d = pr(n);
    for (int mask = 0; mask < (1 << d.size()); ++mask) {
        ans = min(ans, solve(mask));
    }
    cout << ans << endl;

    return 0;
}

