// 約数の列挙O(√n)
vector<ll> divisor(ll n) {
  vector<ll> res;
  for (ll i = 1; i * i <= n; i++) {
    if (n % i == 0) {
      res.push_back(i);
      if (i != n / i) {
        res.push_back(n / i);
      }
    }
  }
  return res;
}

// 素因数分解O(√n)
map<ll, ll> prime_factor(ll n) {
  map<ll, ll> res;
  for (ll i = 2; i * i <= n; i++) {
    while (n % i == 0) {
      ++res[i];
      n /= i;
    }
  }
  if (n != 1)
    res[n] = 1;
  return res;
}

bool is_pow2(ll x) {
  if (x == 0) {
    return false;
  }
  return (x & (x - 1)) == 0;
}

ll f(ll x) {
  return x * (x + 1) / 2;
}

void solve(long long N) {
  if (N == 1) {
    cout << 1 << endl;
    return;
  }
  if (is_pow2(N)) {
    cout << (N * 2 - 1) << endl;
    return;
  }
  auto v = divisor(N);
  sort(ALL(v));
  for (auto x : v) {
    if (x == 1) {
      continue;
    }
    if (f(x - 1) % N == 0) {
      cout << x - 1 << endl;
      return;
    }
    if (f(x) % N == 0) {
      cout << x << endl;
      return;
    }
  }
  auto m = prime_factor(N);
  ll y = m.rbegin()->first;
  ll j = 1;
  while (true) {
    ll x = y * j;
    if (f(x - 1) % N == 0) {
      cout << x - 1 << endl;
      return;
    }
    if (f(x) % N == 0) {
      cout << x << endl;
      return;
    }
    j++;
  }
}

int main() {
  long long N;
  scanf("%lld", &N);
  solve(N);
  return 0;
}

