template< typename T >
vector<T> accumulate(vector<T>& v){
	vector<T> acc(v.size());
	acc[0]=v[0];
	for(int i=1;i<v.size();i++) acc[i]=acc[i-1]+v[i];
	return acc;
}
template< typename T >
vector<vector<T>> daccumulate(vector<vector<T>>& v){
	vector<vector<T>> acc(v.size(),vector<T>(v[0].size()));
	for(int i=0;i<v.size();i++){
		for(int j=0;j<v[0].size();j++){
			acc[i][j]+=v[i][j];
			if(i) acc[i][j]+=acc[i-1][j];
			if(j) acc[i][j]+=acc[i][j-1];
			if(i&j) acc[i][j]-=acc[i-1][j-1];
	}} return acc;
}

