ll N;

vector <ll> pri;

namespace CRT {
  int tot;
  ll A[20], P[20];

  ll mul(ll a, ll b, ll P) {
    ll res = 0;
    for (; b; b >>= 1, a = (a + a) % P) {
      if (b & 1) res = (res + a) % P;
    }
    return res;
  }

  ll qp(ll a, ll k, ll P) {
    a %= P;
    ll res = 1;
    for (; k; k >>= 1, a = mul(a, a, P)) {
      if (k & 1) res = mul(res, a, P);
    }
    return res;
  }

  void exgcd(ll a, ll b, ll &x, ll &y) {
    if (!b) return x = 1, y = 0, void();
    exgcd(b, a % b, y, x), y -= a / b * x;
  }

  ll inv(ll A, ll P) {
    ll x, y = 0;
    exgcd(A, P, x, y);
    return (x + P) % P;
  }

  ll solve() {
    ll res = 0;
    rep(i, 1, tot) {
      ll m = N / P[i];
      ll im = inv(m, P[i]);
      res = (res + mul(A[i], mul(m, im, N), N)) % N;
    }
    return !res ? N : res;
  }
}

void getget() {
  ll x = N;
  rep(i, 2, sqrt(N) + 0.5) if (x % i == 0) {
    ll tmp = 1;
    while (x % i == 0) x /= i, tmp *= i;
    pri.push_back(tmp);
  }
  if (x > 1) pri.push_back(x);
}

void solve() {
  cin >> N;
  N *= 2;
  getget();
  int sz = pri.size(), all = (1 << sz) - 1;
  ll res = 1e18;
  rep(S, 0, all) {
    CRT::tot = sz;
    rep(i, 0, sz - 1) {
      if (S >> i & 1) {
        CRT::A[i + 1] = 0, CRT::P[i + 1] = pri[i];
      } else {
        CRT::A[i + 1] = pri[i] - 1, CRT::P[i + 1] = pri[i];
      }
    }
    chkmin(res, CRT::solve());
  }
  cout << res << endl;
}

