vector<ll> PrimeFactor(ll n){
    vector<ll> ret;
    for(ll i=2;i*i<=n;i++){
        while(n%i==0){
            ret.push_back(i);
            n/=i;
        }
    }
    if(n!=1) ret.push_back(n);
    return ret;
}

bool isPrime(ll num){
    if(num<2)           return false;
    else if(num==2)     return true;
    else if(num%2==0)   return false;
    for(ll i=3;i*i<=num;i+=2) if(num%i==0) return false;
    return true;
}


