ll extgcd(ll a, ll b, ll& x, ll& y, ll c = 1, ll d = 0, ll e = 0, ll f = 1) {
    if (b == 0) {
        x = c;
        y = e;
        return a;
    }
    ll q = a / b, r = a % b;
    return extgcd(b, r, x, y, d, c - q * d, f, e - q * f);
}

ll solve(ll N) {
    ll kmin = LLONG_MAX;
    for (ll u = 1; u <= 31622776; ++u) {
        if (N % u) continue;
        ll v = N / u;
        if (v < u) break;
        ll g = gcd(u, v);
        if (g != 1) continue;

        ll x_, y_, k;
        extgcd(u, v, x_, y_);
        ;
        for (int j = -3; j <= 3; ++j) {
            ll x = x_ - v * j, y = y_ + u * j;
            if (x == 0 || y == 0) continue;
            if (x > 0 && y < 0) {
                k = x * u - 1;
                if (x * (-y) % 2) continue;
            } else if (x < 0 && y > 0) {
                k = (-x * u);
                if ((-x) * y % 2) continue;
            }
            amin(kmin, k);
        }
    }
    return kmin;
}

