map<i64, i64> get_primes(i64 n) {
    map<i64, i64> ans;

    for (i64 i = 2; i <= sqrt(n) + 2; i++) {
        while (n % i == 0) {
            ans[i] += 1;
            n /= i;
        }
    }

    ans[n] += 1;
    ans.erase(1);
    return ans;
}

void gen(map<i64, i64>& primes, set<pair<i64, i64>>& res) {
    vector<i64> q;
    for (auto e : primes) {
        q.push_back(1);
        for (i64 i = 0; i < e.second; i++) {
            q.back() *= e.first;
        }
    }

    i64 mx = (1ll << q.size());
    for (i64 m = 0; m < mx; m++) {
        i64 u = 1;
        i64 v = 1;

        for (i64 i = 0; i < q.size(); i++) {
            if (m & (1ll << i)) {
                u *= q[i];
            }
            else {
                v *= q[i];
            }
        }

        res.insert({min(u, v), max(u, v)});
    }
}


void check_prime(i64 u, i64 v) {
    for (auto p : all) {
        if (v * p > R) {
            break;
        }

        if ((v * p + 1) % u == 0) {
            R = min(R, v * p);
        }
        if ((v * p - 1) % u == 0) {
            R = min(R, v * p - 1);
        }
    }
}

void check(i64 u, i64 v) {
    for (i64 p = 1; p <= n; p++) {
        if (v * p > R) {
            break;
        }

        //if (gcd(p, u) != 1) {
        //    continue;
        //}

        if ((v * p + 1) % u == 0) {
            R = min(R, v * p);
        }
        if ((v * p - 1) % u == 0) {
            R = min(R, v * p - 1);
        }
    }
}


i64 solve(i64 t) {
    n = t;

    m = sqrt(n) + 2;
    R = 2 * n - 1;

    cmp.resize(m + 1);
    all.push_back(1);
    for (i64 i = 2; i <= m; i++) {
        if (cmp[i]) {
            continue;
        }
        all.push_back(i);
        for (i64 j = 2; i * j <= m; j++) {
            cmp[i * j] = 1;
        }
    }


    auto primes = get_primes(2 * n);

    set<pair<i64, i64>> can;
    gen(primes, can);

    for (auto e : can) {
        check_prime(e.first, e.second);
    }

    for (auto e : can) {
        check(e.first, e.second);
    }

    return R;
}

