template<class T>
T ExGcd(T a, T b, T &x, T &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    T d = ExGcd(b, a % b, y, x);
    y -= a / b * x;
    return d;  // gcd
}

