typedef unsigned long long ul;
ul modMul(ul a, ul b, const ul mod) {
	ll ret = a*b-mod*(ul)((ld)a*b/mod);
	return ret+((ret<0)-(ret>=(ll)mod))*mod;
}
ul modPow(ul a, ul b, const ul mod) {
	if (b == 0) return 1;
	ul res = modPow(a,b/2,mod);
	res = modMul(res,res,mod);
	if (b&1) return modMul(res,a,mod);
	return res;
}
template<int SZ> struct Sieve {
	bitset<SZ> pri;
	vi pr;
	Sieve() {
		pri.set(); pri[0] = pri[1] = 0;
		for (int i = 4; i < SZ; i += 2) pri[i] = 0;
		for (int i = 3; i*i < SZ; i += 2) if (pri[i])
			for (int j = i*i; j < SZ; j += i*2) pri[j] = 0;
		F0R(i,SZ) if (pri[i]) pr.pb(i);
	}
	int sp[SZ]; // smallest prime that divides
	void linear() { // above is faster
		memset(sp,0,sizeof sp);
		FOR(i,2,SZ) {
			if (sp[i] == 0) sp[i] = i, pr.pb(i);
			trav(p,pr) {
				if (p > sp[i] || i*p >= SZ) break;
				sp[i*p] = p;
			}
		}
	}
};
Sieve<1<<20> S; // primes up to N^{1/3}

bool millerRabin(ll p) { // test primality
	if (p == 2) return true;
	if (p == 1 || p % 2 == 0) return false;
	ll s = p-1; while (s % 2 == 0) s /= 2;
	F0R(i,30) { // strong liar with probability <= 1/4
		ll a = rand()%(p-1)+1, tmp = s;
		ll mod = modPow(a,tmp,p);
		while (tmp != p-1 && mod != 1 && mod != p-1) {
			mod = modMul(mod,mod,p);
			tmp *= 2;
		}
		if (mod != p-1 && tmp%2 == 0) return false;
	}
	return true;
}

ll f(ll a, ll n, ll &has) { return (modMul(a,a,n)+has)%n; }
vpl pollardsRho(ll d) {
	vpl res;
	auto& pr = S.pr;
	for (int i = 0; i < sz(pr) && pr[i]*pr[i] <= d; i++)
		if (d % pr[i] == 0) {
			int co = 0; while (d % pr[i] == 0) d /= pr[i], co ++;
			res.pb({pr[i],co});
		}
	if (d > 1) { // d is now a product of at most 2 primes.
		if (millerRabin(d)) res.pb({d,1});
		else while (1) {
			ll has = rand()%2321+47;
			ll x = 2, y = 2, c = 1;
			for (; c == 1; c = __gcd(abs(x-y), d)) {
				x = f(x, d, has);
				y = f(f(y, d, has), d, has);
			} // should cycle in ~sqrt(smallest nontrivial divisor)
			if (c != d) {
				d /= c; if (d > c) swap(d,c);
				if (c == d) res.pb({c,2});
				else res.pb({c,1}), res.pb({d,1});
				break;
			}
		}
	}
	return res;
}
pl euclid(ll a, ll b) {
	if (!b) return {1,0};
	pl p = euclid(b,a%b);
	return {p.s,p.f-a/b*p.s};
}
ll invGen(ll a, ll b) {
	pl p = euclid(a,b); assert(p.f*a+p.s*b == 1); // gcd is 1
	return p.f+(p.f<0)*b;
}
pl CRT(pl a, pl b) {
	if (a.s < b.s) swap(a,b);
	ll x,y; tie(x,y) = euclid(a.s,b.s);
	ll g = a.s*x+b.s*y, l = a.s/g*b.s;
	if ((b.f-a.f)%g) return {-1,-1}; // no solution
	// ?*a.s+a.f \equiv b.f \pmod{b.s}
	// ?=(b.f-a.f)/g*(a.s/g)^{-1} \pmod{b.s/g}
	x = (b.f-a.f)%b.s*x%b.s/g*a.s+a.f;
	return {x+(x<0)*l,l};
}
