  rep2(i, 2, n) {
    if(!is_prime[i]) continue;
    for(ll j=i; i*j<=n; j++) is_prime[i*j] = 0;

    if(N%i == 0) {
      p.push_back(i);
      r.push_back(0);
      while(N%i == 0) {
        N /= i;
        r.back()++;
      }
    }
  }

  if(N>1) {
    p.push_back(N);
    r.push_back(1);
  }

  if(r.front()==1 and p.back()>n) {
    cout << ans << newl;
