inline __int128 mod(__int128 a, __int128 m) {
	return (a % m + m) % m;
}

// 拡張 Euclid の互除法
// ap + bq = gcd(a, b) となる (p, q) を求め、d = gcd(a, b) をリターンします
__int128 extGcd(__int128 a, __int128 b, __int128 &p, __int128 &q) {
	if (b == 0) { p = 1; q = 0; return a; }
	__int128 d = extGcd(b, a%b, q, p);
	q -= a / b * p;
	return d;
}

// 中国剰余定理
// リターン値を (r, m) とすると解は x ≡ r (mod. m)
// 解なしの場合は (0, -1) をリターン
pair<__int128 ,__int128> ChineseRem(__int128 b1, __int128 m1, __int128 b2, __int128 m2) {
	__int128 p, q;
	__int128 d = extGcd(m1, m2, p, q); // p is inv of m1/d (mod. m2/d)
	if ((b2 - b1) % d != 0) return make_pair(0, -1);
	__int128 m = m1 * (m2 / d); // lcm of (m1, m2)
	__int128 tmp = (b2 - b1) / d * p % (m2 / d);
	__int128 r = mod(b1 + m1 * tmp, m);
	return make_pair(r, m);
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	__int128 ans = N * 2;
	for (__int128 i = 1; i*(i * 1) / 2 <= N; i++) {
		if (i*(i + 1) / 2 % N == 0)ans = min(ans, i);
		if (2 * N%i == 0) {
			__int128 box = 2 * N / i;
			auto bag = ChineseRem(0, i, box-1, box);
			if(bag.first)ans = min(ans, bag.first);
			bag = ChineseRem(0, box, i - 1, i);
			if (bag.first)ans = min(ans, bag.first);
		}
	}
	long long int ret = ans;
	cout << ret << endl;
}

