long long binPow (long long x, long long y) {
    long long ans = 1;
    while (y > 0) {
        if (y & 1LL) ans = 1LL * ans * x;
        x = 1LL * x * x;
        y >>= 1;
    }

    return ans;
}

void bt (int pos, long long mul1, long long mul2) {
    if (pos == (int)pf.size()) {
        //if (mul1 == 16 * 2371) cout << "HERE " << mul1 << " " << mul2 << "\n";
        for (long long q2 = 1; mul2 * q2 <= n; q2++) {
            if (mul2 * q2 != 1 && (mul2 * q2 - 1) % mul1 == 0) {
                //cout << "Here " << mul1 << " " << mul2 << " " << (mul2 * q2 - 1) / mul1 << " " << q2 << "\n";
                ans = min(ans, mul2 * q2 - 1);
                break;
            }
        }

        return;
    }

    long long curpf = pf[pos].first;
    int totalCnt = pf[pos].second;

    for (int i = 0; i <= totalCnt; i++) {
        bt(pos + 1, mul1 * binPow(curpf, i), mul2 * binPow(curpf, totalCnt - i));
    }
}

