vector<pair<ULL, ULL>> factorize(ULL N) {
    vector<pair<ULL, ULL>> res;
    for (ULL i = 2; i * i <= N; i = (i + 1) | 1) {
        if (N % i) continue;
        res.push_back({ i,0 });
        while (N % i == 0) { N /= i; res.back().second++; }
    }
    if (N != 1) res.push_back({ N,1 });
    return move(res);
}
vector<ULL> divs(vector<pair<ULL, ULL>> F) {
    vector<ULL> res = { 1 };
    for (auto f : F) {
        int t = res.size() * f.second;
        rep(i, t) res.push_back(res[i] * f.first);
    }
    return move(res);
}
ULL GCD(ULL a, ULL b) { return b ? GCD(b, a % b) : a; }


