        if (GCD(d, N / d) != 1) continue;
        ULL K = crt({ 0ll,LL(N / d - 1) }, { LL(d), LL(N / d) }).first;
        ans = min(ans, K);
    }

    cout << ans << endl;

    return 0;
}

