inline LL Pollard_solve(LL n){
    LL x = 0,y = x,t = 1,q = 1,a = (rand()%(n-1))+1;
    for (int k = 2;; k <<= 1, y = x, q = 1){
        for (int i = 1; i <= k; ++i){
            x = (mul(x,x,n)+a)%n,q = mul(q,abs(x-y),n);
            if (!(i & 127)){ t = gcd(q,n); if (t > 1) break; }
        }
        if (t > 1 || (t = gcd(q,n)) > 1) break;
    }
    if (t == n){ t = 1; while (t == 1) t = gcd(abs((x=(mul(x,x,n)+a)%n)-y),n); }
    return t;
}
inline void Pollard(LL n){
	if (n == 1) return;
	if (Miller_Rabin(n)){ t[++cnt] = n; return; }
	LL p = n; while (p == 1 || p == n) p = Pollard_solve(n);
	Pollard(n/p),Pollard(p);
}
