    vector<ll> check;
    for (ll i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            check.emplace_back(i);
            if (n / i != i) check.emplace_back(n / i);
        }
    }

    ll ans = n - 1;
    for (int i = 0; i < (int)check.size(); i++) {
        ll x = check[i], y = n / x;
        auto change = crt({0ll, y - 1}, {x, y});
        if (change.second != 0 && change.first < ans) ans = change.first;
    }

    cout << ans << endl;
    return 0;
}

