        if (n % i)continue;
        ll x = i, y = n / i;
        if (__gcd(x, y) > 1)continue;
        ll x1,y1;
        extgcd(x,-y,x1,y1);
        tar = min({tar,x*x1,y*y1});
    }
    cout << tar << endl;
}
