ll exgcd(ll a, ll b,ll &x,ll &y)//扩展欧几里得算法
{
    if(b==0)
    {
        x=1;y=0;
        return a;  //到达递归边界开始向上一层返回
    }
    ll r=exgcd(b,a%b,x,y);
    ll temp=y;    //把x y变成上一层的
    y=x-(a/b)*y;
    x=temp;
    return r;     //得到a b的最大公因数
}

void solve() {
    ll n;
    cin >> n;
    n *= 2;
    ll ans = n / 2;
    ll p = 2;
    vector<pair<ll, int>> vp;
    vl rs;
    while(p * p <= n) {
        if(n % p == 0) {
            int cnt = 0;
            ll t = 1;
            while(n % p == 0) {
                n /= p;
                t *= p;
                cnt++;
            }
            vp.push_back({p,cnt});
            rs.push_back(t);
        }
        if(n == 1) break;
        p++;
    }
    if(n > 1) {
        vp.push_back({n,1});
        rs.push_back(n);
    }
    int m = vp.size();

    fori(i,0,(1 << m)) {
        ll a = 1, b = 1;
        fori(j,0,m) {
            if(i & (1 << j)) {
                a *= rs[j];
            }
            else b *= rs[j];
        }
        if(a == 1 || b == 1) continue;
        ll x, y;
        exgcd(a, b, x, y);
        ll r = min(abs(a * x), abs(b * y));
        ans = min(r, ans);
    }
    cout << ans << endl;
}

