int Pow(int a, int m) 
{ 
    int m0 = m; 
    int y = 0, x = 1; 

    if (m == 1) 
      return 0; 

    while (a > 1) 
    { 
        // q is quotient 
        int q = a / m; 
        int t = m; 

        // m is remainder now, process same as 
        // Euclid's algo 
        m = a % m, a = t; 
        t = y; 

        // Update y and x 
        y = x - q * y; 
        x = t; 
    } 

    // Make x positive 
    if (x < 0) 
       x += m0; 

    return x; 
} 

void solve() {
	int n; cin >> n;
	if(n == 1) {
		cout << 1 << endl;
		return;
	}
	vi p;
	n *= 2;
	int m = n;
	for(int i = 2; i*i <= m; i++) {
		if(m%i == 0) {
			while(m%i == 0)m /= i;
			p.pb(i);
		}
	}
	if(m > 1)p.pb(m);

	if(si(p) == 1) {
		if(n%2) {
			cout << n-1 << endl;
		}
		else {
			cout << n*2-1 << endl;
		}
		return;
	}
	vpi v;
	int mn = n%2 ? n : n*2-1;
	for(int i = 1; i < (1<<si(p))-1; i++) {
		int m = n;
		int cur1 = 1, cur2 = 1;
		for(int j = 0; j < si(p); j++) {
			if((i>>j)&1) {
				while(m%p[j] == 0)cur1 *= p[j], m /= p[j];
			}

			else {
				while(m%p[j] == 0)cur2 *= p[j], m /= p[j];
			}
		}
		// if(cur2 > 1e9)continue;
		int inv = Pow(cur1, cur2);
		if(n*2/inv >= cur1)
		mn = min(mn, inv*cur1-1);
	}
	cout << mn << endl;
}

