    if (n == 1) {
        cout << 1 << endl;
        exit(0);
    } else if (n == 2) {
        cout << 3 << endl;
        exit(0);
    }

    n *= 2;

    ll r = n - 1;
    for (ll i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            ll j = n / i;
            if (gcd(i, j) == 1) {
                ll a, b;
                extgcd(i, j, a, b);
                if (a == 0 || b == 0) continue;
                if (a < 0) {
                    a *= -1;
                    r = min(r, a * i);
                } else {
                    b *= -1;
                    r = min(r, b * j);
                }
            }
        }
    }

    cout << r << endl;

    return 0;
}

