namespace DLOG {
    int gcd(int a, int b, int &x, int &y) {
        if (b == 0) {
            x = 1, y = 0;
            return a;
        }
        if (a == 0) {
            x = 0, y = 1;
            return b;
        }
        int cx, cy;
        int g = gcd(b, a % b, cx, cy);
        x = cy;
        y = cx - a / b * cy;
        return g;
    }

    int find_any_solution(int a, int b, int c, int &x, int &y) {
        int g = gcd(abs(a), abs(b), x, y);
        if (c % g) return -1;
        x *= c / g;
        y *= c / g;
        if (a < 0) x = -x;
        if (b < 0) y = -y;
        return g;
    }

    int find_xmin(int a, int b, int c, int &x, int &y) {
        int g = find_any_solution(a, b, c, x, y);
        if (g == -1) return g;
        auto shift = [&](int k) -> void {
            x += b / g * k;
            y -= a / g * k;
        };
        if (x < 0)
            shift(-(-x + (-b / g) - 1) / (-b / g));
        if (x == 0)
            shift(-1);
        shift((x / (-b / g)));
        if (y < 0)
            shift(-(-y + (a / g) - 1) / (a / g));
        if (y == 0)
            shift(-1);
        return g;
    }
}

void smain() {
    ll n;
    cin >> n;
    n *= 2;
    ll ans = n - 1;
    for (ll i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            int j = n / i;
            ll x, y;
            ll g = DLOG::find_xmin(i, -j, 1, x, y);
            if (g != -1) {
                assert(x > 0 && y > 0);
                assert(i * x == j * y + 1);
                inmin(ans, i * x - 1);
            }
            swap(i, j);
            x, y;
            g = DLOG::find_xmin(i, -j, 1, x, y);
            if (g != -1) {
                assert(x > 0 && y > 0);
                assert(i * x == j * y + 1);
                assert(i * j == n);
                inmin(ans, i * x - 1);
            }
            swap(i, j);
        }
    }
    cout << ans;
}

