const int N = 2e5 + 10;
int p[N], pp[N];

void gcd(int a, int b, int &x, int &y) {
	if (a == 0) {
		x = 0; y = 1;
	} else {
		int x2, y2;
		gcd(b % a, a, x2, y2);
		x = y2 - (b / a) * x2;
		y = x2;
	}
}

