pair<int64_t, int64_t> extended_euclidean(int64_t a, int64_t b) {
    // https://en.wikipedia.org/wiki/Extended_Euclidean_algorithm#Example
    int64_t g = b, r = a, x = 0, y = 1;

    while (r != 0) {
        int64_t q = g / r;
        g %= r; swap(g, r);
        x -= q * y; swap(x, y);
    }

    x = x < 0 ? x + b : x;
    // x * a == g mod b
    y = (x * a - g) / b;

    while (x <= 0 || y <= 0) {
        x += b;
        y += a;
    }

    dbg(a, b, x, y);
    return {x, y};
}


int main() {
