    int64_t best = 2 * N;

    auto consider_candidate = [&](int64_t candidate) {
        if (candidate > 0)
            best = min(best, candidate);
    };

    for (int64_t a = 1; a * a <= N; a++)
        if (N % a == 0) {
            int64_t b = N / a;

            if (__gcd(a, b) == 1) {
                consider_candidate(b * extended_euclidean(a, b).second);
                consider_candidate(a * extended_euclidean(b, a).second);
            }
        }

    cout << best << '\n';
}

