  lint bbuf=n*2;
  for(int i=2;i*i<=n*2;++i){
    if(bbuf%i==0){
      bbuf/=i;
      prime[i]+=1;
    }
  }
  if(bbuf>1)prime[bbuf]+=1;

  vector<pair<lint,int>> primes;
  for(auto& val:prime){
    primes.push_back({val.first,val.second});
  }
  lint num=primes.size();
  lint res=inf;
  if(n%2==1)res=n-1;
  else res=2*n-1;
  for(lint bit=0;bit<(1<<num);++bit){
    lint a=1;lint b=1;
    for(int i=0;i<num;++i){
      if(bit&(1<<i)){
