const int SIZE = 51234567;
vector<ll> primes;
bool isPrime[SIZE];

void make_primes() {
  if (primes.size() > 0) return;
  memset(isPrime, true, sizeof(isPrime));
  isPrime[0] = isPrime[1] = false;
  for (int i = 2; i * i < SIZE; i++)
    if (isPrime[i])
      for (int j = i * i; j < SIZE; j += i)
        isPrime[j] = false;
  REP(i, SIZE) if (isPrime[i]) primes.push_back(i);
}

map<ll, ll> factorize(ll N) {
  map<ll, ll> count;
  for (int i = 0; primes[i] * primes[i] <= N; i++) {
    while (N % primes[i] == 0) {
      count[primes[i]]++;
      N /= primes[i];
    }
  }
  if (N != 1) count[N]++;
  return count;
}


vector<int> divisors(int n) {
  vector<int> ds;
  for(int d = 1; d * d <= n; d++) {
    if (n % d == 0) {
      ds.push_back(d);
      if (d * d != n) ds.push_back(n/d);
    }
  }
  sort(ds.begin(), ds.end());
  return ds;
}

ll ext_gcd(ll p,ll q,ll& x, ll& y) { // get px+qy=gcd(p,q)
	if(q==0) return x=1,y=0,p;
	ll g=ext_gcd(q,p%q,y,x);
	y-=p/q*x;
	return g;
}

bool check(ll k, ll N) {
  auto count = factorize(N);
  count[2]++;

  auto count_k = factorize(k);
  auto count_k1 = factorize(k+1);

  for (auto it : count) {
    ll p = it.first;
    if (count[p] > count_k[p] + count_k1[p]) return false;
  }
  return true;
}


