typedef long long ll;
const ll MOD = 1e9 + 7;
const long double EPS = 1e-8;

class Sieve {
    long long n_;
    vector<long long> sieve_, primes_;

public:
    explicit Sieve(long long n=1): n_(n), sieve_(n + 1) {
        sieve_[0] = sieve_[1] = -1;
        for (long long i = 2; i <= n; ++i) {
            if (sieve_[i]) continue;
            primes_.push_back(i);
            sieve_[i] = i;
            for (long long j = i*i; j <= n; j += i) {
                if (!sieve_[j]) sieve_[j] = i;
            }
        }
    }
    bool isPrime(long long x) {
        assert (n_ * n_ >= x);
        if (n_ >= x) {
            return sieve_[x] == x;
        } else {
            for (const auto prime : primes_) {
                if (x % prime == 0) return false;
            }
            return true;
        }
    }
    vector<long long> getPrimes() {
        return primes_;
    }
    vector<pair<long long, int>> getPrimeFactorList(long long x) {
        assert (n_ * n_ >= x);
        vector<long long> factorList;
        for (int i=(int)primes_.size()-1; i>=0; i--) {
            if (n_ >= x) break;
            while (x % primes_[i] == 0) {
                x /= primes_[i];
                factorList.emplace_back(primes_[i]);
            }
        }
        if (isPrime(x)) {
            factorList.emplace_back(x);
            x /= x;
        }
        assert (n_ >= x);
        while (x != 1) {
            factorList.push_back(sieve_[x]);
            x /= sieve_[x];
        }
        if (factorList.empty()) return {};
        vector<pair<long long, int>> res(1, pair<long long, int>(factorList[0], 0));
        for (long long p : factorList) {
            if (res.back().first == p) {
                res.back().second++;
            } else {
                res.emplace_back(p, 1);
            }
        }
        return res;
    }
};


void solve(long long N){
    Sieve sieve(pow(N, 0.5)+2);
    auto list = sieve.getPrimeFactorList(N);
    vector<ll> factors(list.size());
    rep(i,0,list.size()) {
        ll factor = 1;
        rep(j,0,list[i].second) factor *= list[i].first;
        factors[i] = factor;
    }
    ll answer = LLONG_MAX;
    rep(i,0,1 << factors.size()) {
        ll a = 1;
        rep(j,0,factors.size()) {
            if (i & (1<<j)) {
                a *= factors[j];
            }
        }
        ll b = N / a;
        if (a < b) swap(a, b);
        ll l = 1;
        while (true) {
            ll k = l * a;
            if (k > 2 * N) break;
            if ((k+1) % b == 0 && (l % 2 == 0 || (k+1) / b % 2 == 0)) {
                answer = min(k, answer);
            }
            if (k > 1 && (k-1) % b == 0 && (l % 2 == 0 || (k-1) / b % 2 == 0)) {
                answer = min(k-1, answer);
            }
            l++;
        }
    }
    cout << answer << endl;
    return;
}

signed main(){
    // ios_base::sync_with_stdio(false);
    // cin.tie(NULL);
    long long N;
    scanf("%lld",&N);
    solve(N);
    return 0;
}

