	std::ios_base::sync_with_stdio(false); std::cin.tie(NULL);
	long long x;
	std::cin >> x;
	long long ans = 2*x;
	std::vector<long long> primes;
	{
		long long m = x;
		for(long long l = 2; l * l <= m; l++) {
			long long e = 1;
			while(m % l == 0) {
				e *= l;
				m /= l;
			}
			if(e > 1) primes.push_back(e);
		}
		if(m > 1) {
			primes.push_back(m);
		}
	}
	auto test = [&](long long val) {
		//std::cout << "testing " << val << '\n';
		if(val <= 1) return false;
		if((val % 2 == 0 ? mul(val/2, val-1, x) : mul((val-1)/2, val, x)) == 0) {
			ans = std::min(ans, val-1);
			return true;
		}
		return false;
	};
	test(x+1);
	test(x);
	test(2*x);
	test(2*x-1);
	int n = (int) primes.size();
	for(int i = 0; i < (1 << n); i++) {
		long long a = 1, b = 1;
		for(int j = 0; j < n; j++) {
			if(i & (1 << j)) {
				a *= primes[j];
			} else {
				b *= primes[j];
			}
		}
		assert(a * b == x);
		{
			// val % (2*a) == 0
			// val % b == b-1
			auto eq = Equation(Equation(0, 2*a), Equation(b-1, b));
			test(eq.ans);
			test(eq.ans+1);
		}
		{
			// val % a == 0
			// val % b == b-1
			auto eq = Equation(Equation(0, 2*a), Equation(b-1, b));
			test(eq.ans);
			test(eq.ans*2);
			test(eq.ans+1);
			test(eq.ans*2+1);
		}
		{
			// val % a == 0
			// val % (2*b) == 2*b-1
			auto eq = Equation(Equation(0, a), Equation(2*b-1, 2*b));
			test(eq.ans);
			test(eq.ans*2);
			test(eq.ans+1);
			test(eq.ans*2+1);
		}
	}
	std::cout << ans << '\n';
	return 0;
	for(int i = 1; 1; i++) {
		if(test(i+1)) {
			std::cout << "real answer is " << i << '\n';
			break;
		}
	}
}

