template<typename T>
vector<T> divisors(T n) {
  vector<T> res;
  for (T i = 1; i*i <= n; ++i) {
    T d = n/i;
    if (d*i != n) continue;
    res.push_back(i);
    if (i*i != n) res.push_back(d);
  }
  return res;
}


