long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

LL pow(LL a,LL b){
    LL ret = 1,b_=a;
    while(b){
        if(b%2)ret*=b_;
        b_ = b_*b_;
        b/=2;
    }
    return ret;
}

