            break;
        }
        if(!(dumn%p)){
            FOR(i,1,52){
                if(!(dumn % pow((LL)p,(LL)i)) && dumn % pow((LL)p,(LL)i+1)){
                    primes.push_back(Pcnt{(LL)p,i});
                    dumn /= pow(p,i);
