pair<LL, LL> ext_gcd( LL a, LL b) {
	if (b == 0) return make_pair(1, 0);
    if (a % b == 0) return make_pair(0, 1);
    pair<LL, LL> t = ext_gcd(b, a % b);
    return make_pair( t.second, t.first - a / b * t.second);
}

void solve() {
	LL n;
	cin >> n;

	LL tmp = 2 * n;
	vector<LL> fac;
	for (LL i = 2; i * i <= tmp; i++) {
		if (tmp % i == 0) {
			LL tot = 1;
			while (tmp % i == 0) {
				tmp /= i;
				tot *= i;
			}
			fac.push_back(tot);
		}
	}
	if (tmp != 1) {
		fac.push_back(tmp);
	}
//	cout << "Tot " << fac.size() << '\n';

	LL ans = 2 * n;
	for (int i = 0; i < (1 << fac.size()); i++) {
		LL l = 1, r = 1;
		for (int j = 0; j < fac.size(); j++) {
			if (i >> j & 1) l *= fac[j];
			else r *= fac[j];
		}
		PLL res = ext_gcd(l, r);
		LL k = l * -res.fi;

		if (k <= 0) {
			k += l * r;
		}
