T extgcd(T a, T b, T& x, T& y) {
    if (b) {
        T d = extgcd(b, a % b, y, x);
        y -= a / b * x;
        return d;
    } else {
        x = 1;
        y = 0;
        return a;
    }
}
int intpow(int a, int b) {
    int ans = 1;
    while (b) {
        if (b & 1)
            ans *= a;
        a *= a;
        b /= 2;
    }
    return ans;
}

int N;
void solve() {
    int ans = N * 2 - 1;
    auto pf = FastPrimeFactorization::prime_factor(N * 2);
    map<int, int> M;
    M[1] = 1;
    for (auto& x : pf)
        M[x]++;
    vp V;
    for (auto p : M) {
        V.emplace_back(p);
    }
    int len = V.size();
    for (int BIT = 0; BIT < (1ll << len); BIT++) {
        int a = 1, b = 1;
        for (int i = 0; i < len; i++) {
            if (bit(BIT, i))
                a *= intpow(V[i].first, V[i].second);
            else
                b *= intpow(V[i].first, V[i].second);
        }
        if (gcd(a, b) != 1)
            continue;
        int x, y;
        int ret = extgcd<int>(a, b, x, y);
        if (x < 0) {
            int tmp = ((abs(x)) + b - 1) / b;
            x += tmp * b;
            y -= tmp * a;
        }
        if (x == 0 || y == 0)
            continue;
        chmin(ans, abs(b * y));
    }
    cout << ans << endl;
}

