pair<LL,LL> ChineseRem(LL b1,LL m1,LL b2,LL m2){
    LL p,q;
    LL d=extgcd(m1,m2,p,q);
    if((b2-b1)%d!=0){
        return make_pair(0,-1);
    }
    LL m=m1*(m2/d);
    LL tmp=(b2-b1)/d*p%(m2/d);
    LL r=((b1+m1*tmp)%m+m)%m;
    return make_pair(r,m);
}
