P extgcd(ll a, ll b, bool gcd = false){
    // return p  :  a * p.fi + b * p.se = gcd(a, b);
    struct eq_elem{
        // ax + by = u
        ll u, x, y;
        eq_elem(ll _a, ll _b, ll _c){
            u = _a; x = _b; y = _c;
        }
        eq_elem& operator *=(const ll &t){
            u *= t; x *= t; y *= t;
            return *this;
        }
        eq_elem operator * (const ll &t){
            return eq_elem(*this) *= t;
        }
        eq_elem& operator -=(const eq_elem &t){
            u -= t.u; x -= t.x; y -= t.y;
            return *this;
        }
        eq_elem operator - (const eq_elem &t){
            return eq_elem(*this) -= t;
        }
    };
    bool flag = a < b;
    if(flag) swap(a, b);
    eq_elem s(a, 1, 0), t(b, 0, 1);
    while(t.u != 0){
        s -= t * (s.u / t.u);
        swap(s, t);
    }
    if(gcd){
        return make_pair(s.u, 0LL);
    }else {
        if(flag) swap(s.x, s.y);
        return make_pair(s.x, s.y);
    }
}

