vector<int> divisors(int n) {
    assert(n > 0);
    vector<int> a;
    int x = 1;
    for ( ; x*x < n; x++) if (n % x == 0) a.push_back(x);
    int s = a.size();
    if (x*x == n) a.push_back(x);
    a.reserve(a.size()+s);
    rep (i,s) a.push_back(n/a[s-1-i]);
    return a;
}
int mul(int x, int y) {
    if (x == 0 || y == 0) return 0;
    int sgn = 1;
    if (x < 0) sgn = -sgn, x = -x;
    if (y < 0) sgn = -sgn, y = -y;
    int p = (x > INF/y ? INF : x*y);
    if (sgn < 0) p = -p;
    return p;
}

