pii diof(int a,int b, int c) {
    int d = gcd(a, b);
    if (c % d != 0) {
        return {0, 0};
    }
    pii res = ext_gcd(a, b);
    res.first = res.first * (c/d)% (b/d);
    if (res.first < 0)res.first += b/d;
    res.second = (c - a * res.first) / b;
    return res;
}
