template <typename IntType>
constexpr IntType ExtendedGCD(IntType a, IntType b, IntType& x, IntType& y) {
  if (b == 0) {
    x = 1;
    y = 0;
    return a;
  }
  const auto c = ExtendedGCD(b, a % b, y, x);
  y -= a / b * x;
  return c;
}

int main() {
  std::int64_t N;
