  std::vector<std::int64_t> factors;
  N *= 2;
  auto n = N;
  for (std::int64_t p = 2; p * p <= n; ++p) {
    if (n % p == 0) {
      factors.push_back(p);
      n /= p;
      while (n % p == 0) {
        n /= p;
        factors.back() *= p;
      }
    }
  }
  if (n > 1) {
    factors.push_back(n);
  }
  std::int64_t best_k = std::max<std::int64_t>(1, N / 2 - 1);
  const auto search = [&](auto f, std::size_t index, std::int64_t a) -> void {
    if (index == factors.size()) {
      const auto b = N / a;
      std::int64_t x, y;
      ExtendedGCD(a, b, x, y);
      y = -y;
      if ((a == 1 || x > 0) && (b == 1 || y > 0)) {
        best_k = std::min(best_k, b * y);
      }
    } else {
      f(f, index + 1, a);
      f(f, index + 1, a * factors[index]);
    }
  };
  search(search, 0, 1);
  std::cout << best_k << std::endl;
  return 0;
}

