vector<p> factor(int n){
    vector<p> ans;
    int sqrt1 = sqrt(n);
    for (int q = 2; q <= sqrt1; q++){
        if (n % q == 0){
            ans.push_back({q, 1});
        }
        while (n % q == 0){
            n /= q;
            ans.back().second *= q;
        }
    }
    if (n != 1){
        ans.push_back({n, n});
    }
    return ans;
}

pair<int, p> ax_by(int x, int y){
    if (x > y){
        pair<int, p> k = ax_by(y, x);
        return {k.first, {k.second.second, k.second.first}};
    }
    if (x == 0){
        return {y, {0, 1}};
    }
    pair<int, p> k = ax_by(y % x, x);
    return {k.first, {k.second.second-k.second.first*(y-y % x)/x, k.second.first}};
}

