  while(m>=i*i){
    if(m%i==0){
      p.at(j)=i;
      m=m/i;
      j++;
    }else{
      i++;
    }
  }
  p.at(j)=m;

  vector<ll> q(20,1);
  ll s=0;
  for(i=0;i<=j;i++){
    if(i==0||p.at(i)==p.at(i-1)){
      q.at(s) *= p.at(i);
    }else{
      s++;
      q.at(s) *= p.at(i);
    }
  }

  s++;
  ll mink=2*n-1,h,a,b,k;
  for(i=0;i<(1<<s);i++){
    bitset<50> bi(i);
    a=1;
    b=1;
    for(h=0;h<s;h++){
      if(bi.test(h)){
        a *= q.at(h);
      }else{
        b *= q.at(h);
      }
    }
    if(a>b){
      k=a;
      while(k<mink&&(k+1)%b!=0){
        k += a;
      }
      if(k<mink){
