map< int64_t, int > prime_factor(int64_t n) {
  map< int64_t, int > ret;
  for(int64_t i = 2; i * i <= n; i++) {
    while(n % i == 0) {
      ret[i]++;
      n /= i;
    }
  }
  if(n != 1) ret[n] = 1;
  return ret;
}

ll extgcd(ll a, ll b, ll &x, ll &y){
    ll d = a;
    if(b!=0){
        d = extgcd(b, a%b, y, x);
        y -= (a/b)*x;
    }
    else{
        x = 1, y = 0;
    }
    return d;
}

void chmin(ll &a, ll b){if(a>b)a=b;}

ll solve(ll n){
    if(n==1) return 1;
    auto pf = prime_factor(2*n);
    ll k = 2*n;
    vector<ll> Pfs;
    for(auto [p,e]:pf) Pfs.push_back((ll)pow(p,e));
    int m = Pfs.size();
    for (int bit = 1; bit < (1<<m); bit++)
    {
        ll a = 1LL;
        for (int i = 0; i < m; i++)
        {
            if((bit>>i)&1LL) a *= Pfs[i];
        }
        ll b = 2*n/a;
        if(a==1LL || b==1LL) continue;
        ll x, y;
        extgcd(a,b,x,y);
        // debug(a,b,x,y);
        // if(x==0 || y==0) continue;
        if(x<0) chmin(k,-a*x);
        else chmin(k,-b*y);
    }
    return k;
}   

