vector< int64_t > divisor(int64_t n) {
  vector< int64_t > ret;
  for(int64_t i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      ret.push_back(i);
      if(i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return (ret);
}

ll wsolve(ll n){
    auto div = divisor(2*n);
    ll k = 2*n;
    for(ll x:div){
        ll y = 2*n/x;
        vector<ll> mod = {x, y};
        vector<ll> residue = {0, -1};
        auto p = atcoder::crt(residue, mod);
        if(p.first==0) continue;
        chmin(k, p.first);
    }
    return k;
}

