ll extended_euclidian(ll a, ll b) {
  if(b == 1) return a-1;
  if(a == 1) return b-1;
  ll s=a, t=b, x=1, y=0, u=0, v=1, k;
  while(t) {
    k = s / t;
    s -= k * t;
    swap(s, t);
    x -= k * u;
    swap(x, u);
    y -= k * v;
    swap(y, v);
  }
  if(x>0) return a*x-1;
  else return b*y-1;
}

