int power(int A, int B)
{
    int res = 1;
    while (B)
    {
        if (B & 1)
        {
            res *= A;
        }
        A *= A;
        B >>= 1;
    }
    return res;
}
void exgcd(int A, int B, int &x, int &y)
{
    if (B == 0)
    {
        x = 1;
        y = 0;
        return;
    }
    exgcd(B, A % B, x, y);
    int X = x, Y = y;
    x = -Y;
    y = -(X + A / B * Y);
}
void dfs(int now, int A, int B)
{
    if (now > cnt)
    {
        int x, y;
        exgcd(A, B, x, y);
        if (x <= 0)
        {
            int len = (-x) / B + 1;
            x += len * B;
            y += len * A;
        }
        if (y <= 0)
        {
            int len = (-y) / A + 1;
            x += len * B;
            y += len * A;
        }
        while (x > B && y > A)
        {
            x -= B;
            y -= A;
        }
        ans = min(ans, B * y);
        return;
    }
    dfs(now + 1, A * power(p[now], tim[now]), B);
    dfs(now + 1, A, B * power(p[now], tim[now]));
}
