ll gcd(ll a, ll b, ll& x, ll& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll x1, y1;
    ll d = gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - y1 * (a / b);
    return d;
}

bool find_any_solution(ll a, ll b, ll c, ll &x0, ll &y0, ll &g) {
    g = gcd(abs(a), abs(b), x0, y0);
    if (c % g) {
        return false;
    }

    x0 *= c / g;
    y0 *= c / g;
    if (a < 0) x0 = -x0;
    if (b < 0) y0 = -y0;
    return true;
}

ll get(ll a, ll b, ll c)
{
    a++;
    ll sig = 1;
    if(a<0)
        sig*=(-1);
    a = abs(a); 
    ll c1 = a/c, c2 = b/c;
    ll r1 = a%c, r2 = b%c;

    ll mo = (r1*r2)%c;
    ll temp (c1*c2*c + c1*r2 + c2*r1 + (r1*r2)/c);

    if(sig == -1)
        return (-temp);
    if(mo == 0)
        return temp;
    return temp+1;    
}

