	{
		long long m = x;
		for(long long l = 2; l * l <= m; l++) {
			long long e = 1;
			while(m % l == 0) {
				e *= l;
				m /= l;
			}
			if(e > 1) primes.push_back(e);
		}
		if(m > 1) {
			primes.push_back(m);
		}
	}
