			auto eq = Equation(Equation(0, 2*a), Equation(b-1, b));
			test(eq.ans);
			test(eq.ans+1);
		}
		{
			// val % a == 0
			// val % b == b-1
			auto eq = Equation(Equation(0, 2*a), Equation(b-1, b));
			test(eq.ans);
			test(eq.ans*2);
			test(eq.ans+1);
