	cout << fixed << setprecision(15);
	srand((unsigned)time(NULL));

	LL(n);
	vll v = pollard(n * 2);
	auto c = cntv(v);
	vpll a;
	foa(t, c) { a.push_back(t); }

	vll w;
	foa(t, c) { w.push_back(POW(t.first, t.second)); }

	int k = w.size();

	ll ans = numeric_limits<ll>::max();

	rep(i, 1 << k) {
		ll y = 1;
		rep(j, k) {
			if(i & 1 << j) {
				y *= w[j];
			}
		}
		ll z = n * 2 / y;
		ll a, b;
		ext_gcd(y, z, a, b);
		//cout << y << " " << z << " " << a << " " << b << endl;
		ll k = -z * b;
		if(k > 0) chmin(ans, -z * b);
	}
	drop(ans);

	return 0;
}

#include <bits/stdc++.h>
