#define F first
#define S second
using namespace std;
using namespace atcoder;
using uint = unsigned int;
using ll = long long;
using ull = unsigned long long;
typedef pair<ll, ll> P;
ll Mod = 1000000007;

ll N;
ll calc(ll a,ll b) {
  if (__gcd(a,b) != 1) {
    return -1;
  }
  // a < b
  vector<P> E;
  ll c = a;
  ll d = b;
  E.emplace_back(a,b);
  while (d % c != 0) {
    ll f = d % c;
    d = c;
    c = f;
    E.emplace_back(c,d);
  }
  int sz = (int)E.size();
  ll x = 1;
  ll y = -(E[sz-2].S / E[sz-2].F);
  for (int i = sz - 3; i >= 0; i--) {
    ll z = -(E[i].S / E[i].F);
    ll nx = y;
    ll ny = (x + (y * z));
    x = nx;
    y = ny;
  }
  x *= -1;
  y *= -1;
  ll way1 = x % a;
  ll way2 = y % b;
  if (way1 < 0) way1 += a;
  if (way2 < 0) way2 += b;
  ll res = min(way1 * b,way2 * a);
  return res;
}

int main() {
  cin >> N;
  vector<P> vec;
  if (N == 1) {
    cout << 1 << endl;
    return 0;
  }
  ll ans = N - 1;
  for (ll i = 2; i <= sqrt(N*2); i++) {
    if ((N*2) % i == 0) {
      vec.emplace_back(i,(N*2)/i);
    }
  }
  for (int i = 0; i < (int)vec.size(); i++) {
    ll res = calc(vec[i].F,vec[i].S);
    if (res == -1) {
      continue;
    }
    if (ans == -1) {
      ans = res;
    } else {
      ans = min(ans,res);
    }
  }
  cout << ans << endl;
  return 0;
}

