vector<pair<long long, int>> prime_factorization(long long n) {
	vector<pair<long long, int>> v;
	for (long long i = 2; i * i <= n; ++i) {
		int e = 0;
		while (n % i == 0) {
			++e;
			n /= i;
		}
		if (e != 0) v.emplace_back(i, e);
	}
	if (n != 1) v.emplace_back(n, 1);
	return v;
}

long long pow(long long a, long long n) {
	long long res = 1;
	while (n > 0) {
		if (n & 1) res = (res * a);
		n >>= 1;
		a = (a * a);
	}
	return res;
}

int main() {
	long long n;
	cin >> n;
	auto v = prime_factorization(2*n);
	vector<long long> r(v.size()), m(v.size());
	for (int i = 0; i < m.size(); i++) {
		m[i] = pow(v[i].first, v[i].second);
	}
	long long ans = INF;
	for (int bits = 0; bits < (1<<r.size()); bits++) {
		bitset<32> t(bits);
		for (int i = 0; i < r.size(); i++) {
			r[i] = t[i] ? 0 : m[i]-1;
		}
		long long now = crt(r, m).first;
		if (now == 0) now = 2*n;
		ans = min(ans, now);
	}
	cout << ans << endl;
	return 0;
}

