vector<pll> prime_factorization(ll N) {
    map<ll, ll> mp;
    ll num = 2;
    while (num <= sqrt(N)) {
        while (N%num == 0) {
            mp[num]++;
            N /= num;
        }
        num++;
    }
    if (N != 1)mp[N]++;
    vector<pll> primes;
    for (auto[key, val] : mp)primes.push_back({ key,val });
    return primes;
}

vector<pll> enumarate_all_pair(vector<pll> primeP) {
    const int N = primeP.size();
