    for (auto[prime, mul] : primeP) {
        ll num = 1;
        rep(i, mul)num *= prime;
        primeL.push_back(num);
    }

    vector<pll> res;
    rep(way, allway) {
        pll p = { 1,1 };
        int buf = way;
        rep(i, N) {
            bool left = buf % 2 == 0;
            (left ? p.first : p.second) *= primeL[i];
            buf /= 2;
        }
        res.push_back(p);
    }
    return res;
}

ll extGCD(ll a, ll b, ll& x, ll& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll d = extGCD(b, a%b, y, x);
    y -= a / b * x;
    return d;
}

