namespace math {

// return (x, y) s.t. ax + by = 1
tll ext_euclidean(ll a, ll b) {
    if (b == 0) return tll(1, 0, a);
    auto [ xr, yr, g ] = ext_euclidean(b, a % b);
    ll x = yr;
    ll y = xr - a / b * x;
    return tll(x, y, g);
}

// return (x, y) s.t. ax + by = d
tll ext_euclidean(ll a, ll b, ll d) {
    auto [ x, y, g ] = ext_euclidean(a, b);
    if (d % g) return tll(-1, -1, -1);
    ll mul = d / g;
    return tll(x * mul, y * mul, g);
}

pll chinese_remainder(ll b1, ll m1, ll b2, ll m2) {
    if (b1 > b2) {
        std::swap(b1, b2);
        std::swap(m1, m2);
    }
    auto [ p, q, g ] = ext_euclidean(m1, m2);
    if ((b2 - b1) % g) return pll(-1, -1);
    ll m = m1 / g * m2;
    ll tmp = (b2 - b1) / g * p % (m2 / g);
    ll x = (b1 + tmp * m1 + m) % m;
    return pll(x, m);
}

pll chinese_remainder(const vec<ll> &bv, const vec<ll> &mv) {
    assert(bv.size() == mv.size());
    ll b = 0, m = 1;
    size_type sz = bv.size();
    for (size_type i = 0; i < sz; i++) {
        std::tie(b, m) = chinese_remainder(b, m, bv[i], mv[i]);
        if (b == -1) return pll(-1, -1);
    }
    return pll(b, m);
}

}

ll solve(ll n) {
    if (n == 1) return 1;

    n *= 2;

    ll ans = n;

    auto update = [&](ll k) {
        ll rest = n / k;
        auto [ a, b, c ] = math::ext_euclidean(k, rest, 1);
        if (c == -1) return;
        ll n1 = std::abs(k * a);
        ll n2 = std::abs(rest * b);
        ll tmp = std::min(n1, n2);
        if (tmp == 0) return;
        chmin(ans, tmp);
    };

    for (ll i = 1; i * i <= n; i++) {
        if (n % i) continue;
        update(i);
        update(n / i);
    }
    return ans;
}

