ll extgcd(ll a, ll b, ll &x, ll &y){
    ll gc = a;
    if(b!=0){
        gc = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    }else{
        x = 1, y = 0;
    }
    return gc;
}
