ll nod(ll A, ll B)
{
 	if (A == 0) {X = 0, Y = 1; return 1;}
 	ll d = nod(B % A, A);
 	ll newX = -Y - (B / A) * X;
 	ll newY = -X;
 	X = newX, Y = newY;
 	return d;
}

