ll bin_search(ll a[], ll lb, ll ub, ll item) {
    while (lb <= ub) {
        ll mid = lb + (ub - lb) / 2;
        if (a[mid] == item) return mid;
        if (a[mid] > item) lb = mid + 1;
        else ub = mid - 1;
    }
    return -1;
}

ll power(ll x, ll y) {
    ll res = 1;
    while (y > 0) {
        if (y & 1)
            res = res * x;

        y = y >> 1;
        x = x * x;
    }
    return res;
}

ll powerp(ll x, ll y, ll p) {
    ll res = 1;
    x = x % p;
    if (x == 0) return 0;
    while (y > 0) {
        if (y & 1)
            res = (res * x) % p;

        y = y >> 1; // y = y/2
        x = (x * x) % p;
    }
    return res;
}
