    for (auto p : v) {
        auto q = crt({0,p.second-1},{p.first,p.second});
        // cout << p << q << endl;
        if (q.second != 2 * n) continue;
        ans = min(ans,q.first);
    }
    cout << ans << endl;
    return 0;
}

