using namespace std;
typedef long long li;

vector<li> factor(li n) {
    vector<li> factors;
    for (int p = 2; p * p <= n; ++p) {
        while (n % p == 0) {
            factors.push_back(p);
            n /= p;
        }
    }
    if (n > 1) {
        factors.push_back(n);
    }
    return factors;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li n;
    cin >> n;

    if (n == 1) {
        cout << 1 << endl;
        return 0;
    }

    map<li, li> factors;
    for (auto p: factor(n)) {
        factors[p]++;
    }

    vector<li> pows;
    for (auto p: factors) {
        li pow = 1;
        for (int i = 0; i < p.second; ++i) {
            pow *= p.first;
        }
        if (p.first == 2) {
            pow *= 2;
        }
        pows.push_back(pow);

    }

    const li p = pows.size();
    li ans = 2 * n;
    for (li i = 1; i < 1LL << p; ++i) {
        vector<li> rems;
        for (int j = 0; j < p; ++j) {
            if ((i >> j) & 1) {
                rems.push_back(pows[j] - 1);
            } else {
                rems.push_back(0);
            }
        }
        auto a = atcoder::crt(rems, pows);
        li tans = a.first == 0 ? a.second : a.first;
        ans = min(ans, tans);
    }
    cout << ans << endl;
    return 0;
}

