bool is_prime(int x) {
	if (x == 1)
		return false;
	if (x == 2 || x == 3)
		return true;
	if (x % 6 != 1 && x % 6 != 5)
		return false;
	int s = sqrt(x);
	for (int i = 5; i <= s; i += 6)
		if (x % i == 0 || x % (i + 2) == 0)
			return false;
	return true;
}
map<int, int> c;
void prime_diecom(int n, set<int>& st)
{
	for (int i = 2; i <= n; i++) {
		while (n != i) {
			if (n % i == 0) {
				st.insert(i);
				c[i]++;
				n = n / i;
			}
			else
				break;
		}
		if (is_prime(n)) {
			st.insert(n);
			c[n]++;
			break;
		}
	}
}

