int func(int N)
{
   int ans = INF;

   int c = N;
   while(c%2==0) c/=2;
   if(c==1){ return N*2-1;}

   auto d = divisor(2*N);

    if(d.size()==2){
       return N-1;
   }

   for(auto p : d)
   {

       int q = N / p;
       if(gcd(p,q)>1) continue;

       int i = mod_inv(-p,q);
       i = ((i%q)+q)%q;
       int k = i * p;
       if(k!=0){
           if(k * (k+1)/2 % N==0) chmin(ans, k);
       }
   }
   return ans;
}

