vector<pair<ll, int>> prime_factor(ll a) {
	vector<pair<ll, int>> ret;
	for (ll i = 2; i * i <= a; i++) {
		int cnt = 0;
		while (a % i == 0 && a != 0) {
			cnt++;
			a /= i;
		}
		if (cnt > 0) ret.emplace_back(i, cnt);
	}
	if (a != 1) {
		ret.emplace_back(a, 1);
	}
	return ret;
}

