i64 solve(i64 n) {
	n *= 2LL;

	std::vector<i64> ps;
	std::vector<std::pair<i64, int>> vec;
	{
		i64 m = n;
		for(i64 i = 2; i * i <= m; i++) {
			if(m % i) continue;

			vec.push_back({i, 0});
			while(!(m % i)) {
				vec.back().second++;
				m /= i;
			}
		}
		if(m != 1) vec.push_back({m, 1});

		for(auto v: vec) {
			ps.push_back(1);

			for(int i = 0; i < v.second; i++) ps.back() *= v.first;
		}
	}

	i64 ans = n - 1;
	int k = vec.size();
	for(int i = 0; i < (1 << k); i++) {
		i64 A = 1;
		for(int j = 0; j < k; j++) {
			if(i >> j & 1) continue;
			A *= ps[j];
		}
		i64 B = n / A;

		long long x, y;
		extGCD(A, B, x, y);
		if(!x or !y) continue;
		if(x < 0) {
			x *= -1;
			y *= -1;
		}

		__int128_t X = __int128_t(A) * __int128_t(x);
		__int128_t Y = __int128_t(B) * __int128_t(-y);
		if(X < ans) ans = X;
		if(Y < ans) ans = Y;
	}
	return ans;
}

i64 naive(i64 n) {
	i64 sum = 0;
	for(i64 i = 1; ; i++) {
		sum += i;
		if(sum % n) continue;
		return i;
	}
	return -1;
}

