	i64 n; scanf("%lld", &n);
	i64 ans = solve(n);
	printf("%lld\n", ans);

	#ifndef NDEBUG
	for(i64 i = 1000; i < 100000 ; i++)
		assert(solve(i) == naive(i));
	#endif
	return 0;
}

