struct Sieve {
  int n;
  vector<int> f, primes;
  Sieve(int n=1):n(n), f(n+1) {
    f[0] = f[1] = -1;
    for(int i=2; i<=n; ++i) {
      if(!f[i]) {
        primes.emplace_back(i);
        f[i] = i;
      }
      for(int p:primes) {
        int u = p*i;
        if(u > n or p > f[i]) break;
        f[u] = p;
      }
    }
  }
  //素数判定
  bool isPrime(int x) {return f[x] == x;}
  //素数判定(1つ用)(宣言はsqrt(x)のサイズで)
  bool isPrime1(int64_t x) {
    bool m = true;
    for(int z:primes) {
      if(!(x%z)) {
        m = false;
        break;
      }
    }
    return m;
  }
  //素数列挙
  vector<int > factorList(int x) {
    assert(x <= n);
    vector<int> res;
    while(x != 1) {
      res.emplace_back(f[x]);
      x /= f[x];
    }
    return res;
  }
  //素因数分解　pair(素数, 素因数の数)
  vector<pair<int, int> > factor(int x) {
    vector<int> fl = factorList(x);
    if(fl.size() == 0) return {};
    vector<pair<int, int> > res(1, pair<int, int>(fl[0], 0));
    for(int p : fl) {
      if(res.back().first == p) {
        ++res.back().second;
      } else {
        res.emplace_back(p, 1);
      }
    }
    return res;
  }
  //素数列挙(1つ用)(宣言はsqrt(x)のサイズで)
  vector<int64_t> factorList1(int64_t x) {
    vector<int64_t> vec;
    for(int z:primes) {
      while(!(x%z)) {
        vec.emplace_back(z);
        x /= z;
      }
    }
    if(x != 1) vec.emplace_back(x);
    return vec;
  }
