ll gcd(ll a, ll b){
    if(b>a)swap(a,b);
    while(a%b){
        a %= b;
        swap(a,b);
    }
    return b;
}

ll extGCD(ll a, ll b, ll &x, ll &y){
    if(b==0){
        x = 1;
        y = 0;
        return a;
    }
    ll d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

