inline void solve(LL xxx,LL yyy){
	if (gcd(xxx,yyy) > 1) return;	//x * t1 - y * t2 == 1
	LL a,b,c,t,d,x0,y0;
	a = xxx,b = yyy,c = 1;
	exgcd(a,b,d,x0,y0);
	a /= d,b /= d,c /= d,x0 *= c,y0 *= c;
	if (x0 > 0 && y0 <= 0){
		d = (-y0) / a + 1;
		y0 += d * a;
		x0 -= d * b;
	}
	else if (x0 <= 0 && y0 > 0){
		d = (-x0) / b + 1;
		x0 += d * b;
		y0 -= d * a;
	}
	LL mnx,mxy;
	if (x0 > 0) t = (x0-1) / b,x0 -= t * b,y0 += t * a;
	while (x0 < 0) x0 += b,y0 -= a;
	while (x0 > b) x0 -= b,y0 += a;
	if (y0 == 0) y0 -= a,x0 += b;
	mnx = x0,mxy = y0;

	if (mnx * xxx > 0) ans = min(ans,mnx * xxx);//,cerr << mnx << ' ' << xxx<<'\n';
	//cerr << mnx << ' ' <<xxx << '\n';
