long long extgcd(long long a, long long b, long long &x, long long &y) {
    long long g = a;
    x = 1; y = 0;
    if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
    return g;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    long long N; cin >> N;
    if (N == 1) {
        cout << 1 << "\n";
        return 0;
    }
    N *= 2;
    vector<pair<long long, long long>> V;
    vector<long long> R;
    long long M = N;
    for (long long i = 2; i * i <= M; i++) {
        if (M % i == 0) {
            long long cnt = 0, r = 1;
            while (M % i == 0) {
                cnt++; M /= i; r *= i;
            }
            V.emplace_back(i, cnt);
            R.emplace_back(r);
        }
    }
    if (M != 1) V.emplace_back(M, 1), R.emplace_back(M);
    int Sz = R.size();
    long long Ans = N;
    for (int bit = 0; bit < (1 << Sz); bit++) {
        long long C = 1;
        for (int i = 0; i < Sz; i++) {
            if (bit & (1 << i)) C *= R[i];
        }
        long long a, b;
        long long D = N / C;
        extgcd(C, D, a, b); // aC + bD = 1;
        // DC - CD = 0;
        long long X = D + a, Y = C - b;
        // XC - YD = 1
        if (Y <= 0) {
            long long r = (-Y / C);
            X += D * r, Y += C * r;
            if (Y <= 0) X += D, Y += C;
        }
        assert(Y > 0);
        if (X <= 0) continue;
        long long r = min(X / D, Y / C);
        X -= r * D, Y -= r * C;
        if (X <= 0 || Y <= 0) X += D, Y += C;
        assert(X > 0 && Y > 0);
        Ans = min(Ans, Y * D);
    }
    cout << Ans << "\n";
    return 0;
}

