ll power(ll a, ll b, ll m){
	a %= m;
	if (b == 0) return 1;
	if (b == 1) return a;
	ll half = power(a, b/2, m);
	half *= half;
	half %= m;
	if (b % 2 == 1) half *= a;
	return half%m;
}

ll inv(ll a, ll m){
	//cout << "inv " << a << " " << m << endl; 
    ll m0 = m, t, q; 
    ll x0 = 0, x1 = 1; 

    if (m == 1){
    	//cout << "done" << endl;
    	return 0;
	} 

    while (a > 1){ 
    	//cout << "m : " << m << endl;
        q = a / m; 
        t = m; 
        m = a % m, a = t; 
        t = x0; 
        x0 = x1 - q * x0; 
        x1 = t; 
    } 
    if (x1 < 0) x1 += m0; 
  	//cout << "done" << endl;
    return x1; 
}

ll qmult(ll a, ll b, ll m){
	//cout << a << " " << b << " " << m << endl;
	a %= m;
	b %= m;
	if (a < b) swap(a, b);
	if (b == 0) return 0;
	if (b == 1) return a;
	ll half = qmult(a, b/2, m);
	half += half;
	half %= m;
	if (b % 2 == 1) half += a;
	return half%m;
}


