vvl factorize(ll n) {
  vvl ret;
  for(ll i = 2; i * i <= n; i++) {
    ll c = 0;
    while(n % i == 0) n /= i, c++;
    if(c!=0) ret.push_back(vll{i, c});
  }
  if(n != 1) ret.push_back(vll{n, 1});
  return ret;
}

ll mpow(ll a, ll b, ll p = -1){
  ll ret = 1, num = a;
  if(p==-1){
    while(b>0){
      if(b%2) ret *= num;
      num = num * num;
      b /= 2;
    }
  }else{
    while(b>0){
      if(b%2) ret = (ret*num)%p;
      num = (num*num)%p;
      b /= 2;
    }
  }
  return ret;
}
ll gcd(ll a, ll b){
  if(b<a) swap(a, b);
  ll r = a % b;
  if(r==0) return b;
  while(r!=0) r = a % b, a = b, b = r;
  return a;
}
ll lcm(ll a, ll b){return (a*b)/gcd(a, b);}
vll extgcd(ll a, ll b) {
  ll x, y;
  for (ll u = y = 1, v = x = 0; a;) {
    ll q = b / a;
    swap(x -= q * u, u);
    swap(y -= q * v, v);
    swap(b -= q * a, a);
  }
  return vll{x, y, b};
}

int main(){
  ll n;std::cin >> n;
  auto p = factorize(2LL * n);
  ll m = p.size();
  ll ans = 2*n;
  if(((n*(n+1))/2)%n==0) ans = n;

  for(int i=0;i<m;i++) p[i][0] = mpow(p[i][0], p[i][1]);
  for(ll i=1;i<(1<<m);i++){
    ll x = 1;
    for(ll j=0;j<m;j++){
      if((i>>j)&1){//use
        x *= p[j][0];
      }
    }
    ll y = (2*n)/x;
    //mod xでy=1
    if(x==1||y==1) continue;
    auto a = extgcd(y, x);// y, x
    swap(a[0], a[1]);

    if(a[0]>0){
      ll adnum = a[0]/y + 1;
      a[0] -= adnum * y, a[1] += adnum * x;
    }
    if(a[1]<0){
      ll ab = abs(a[1]);
      ll adnum = ab / x + 1;
      a[0] -= adnum * y, a[1] += adnum * x;
    }
    x *= a[0], y*=a[1];
    if(abs(y)-abs(x)==1) ans = min(ans, abs(x));
    //std::cout << x << " " << y << '\n';
  }
  std::cout << ans << '\n';
}

