__int128 modularInverse(__int128 a, __int128 m){
	__int128 r0 = a, r1 = m, ri, s0 = 1, s1 = 0, si;
	while(r1){
		si = s0 - s1 * (r0 / r1), s0 = s1, s1 = si;
		ri = r0 % r1, r0 = r1, r1 = ri;
	}
	if(r0 < 0) s0 *= -1;
	if(s0 < 0) s0 += m;
	return s0;
}

ll n, res = 1e9;

ll f (__int128 a, __int128 b) {
	__int128 inv = modularInverse(a, b);

	__int128 res = -a * inv;
	res %= n;
	if (res < 0) res += n;
	if (res == 0) res += n;

	return res;
}

