		auto res = ChineseRem({ r0,r1 }, { m0,m1 });
		if (res.second == -1)continue;
		if (res.first > 0)chmin(ans, res.first);
		else chmin(ans, res.first + res.second);
	}

	cout << ans << endl;

	return 0;
}

