long long f[105], cnt[105];

int factor(long long u){
    int size = 0;
    for(long long i = 2; i*i <= u; i++){
        if(u==1) break;
        else if(u%i==0){
            long long fac = 1ll;
            while(u%i==0){
                fac *= i;
                u /= i;
            }
            f[++size] = fac;
        }
    }
    if(u!=1ll) f[++size] = u;
    return size;
}

long long spJudge(long long u){
    long long find = -1;
    for(long long i = 1ll; i*i <= u; i++){
        if(u%i==0){
            long long j = u/i;
            if(i==j+1ll) find = i;
            else if(j==i+1ll) find = j;
        }
    }
    return find;
}

void exgcd(long long a,long long b,long long&x,long long&y){
    if(!b) {
        x = 1;
        y = 0;
    }
    else{
        exgcd(b, a % b, x, y);
        long long t = x; x = y; y= t-a/b*y;
    }
}

long long getRes(long long a,long long b,long long upper){
    long long x,y;
    exgcd(a,b,x,y);
    //printf("a = %lld, b = %lld, x = %lld, y = %lld\n",a,b,x,y);
    if(x<0){
        long long need = -x;
        long long time = need/b;
        if(need%b) time++;
        x += time*b, y -= time*a;
    }
    //printf("diff = %lld\n",a*x+b*y);
    if(y==0) y -= a;
    //printf("after: a = %lld, b = %lld, x = %lld, y = %lld\n",a,b,x,y);
    long long res = (-y)*b;
    return res;
}

