	ans = 2 * N;
	for(ll i = 1; i * i <= N; ++i)
		if(N % i == 0)
		{
			calc(2 * i, N / i);
			calc(i, 2 * N / i);
			calc(2 * N / i, i);
			calc(N / i, 2 * i);
		}
	printf("%lld\n", ans);
	return 0;
}

