typedef unsigned long long ULL;

ULL gcd(ULL x, ULL y) {
    while (1) {
	if (x) y %= x; else return y;
	if (y) x %= y; else return x;
    }
}

ULL lcm(ULL x, ULL y) { return x/gcd(x, y)*y; }

// xs + yt = gcd(x, y), xu + yv = 0
// abs(s) < abs(y / gcd(x, y));
// abs(t) < abs(x / gcd(x, y));
LL extgcd(LL x, LL y, LL&s, LL&t) {
    assert(x >= 0 && y >= 0);
    for (LL u=t=1, v=s=0; x; ) {
	LL q = y / x;
	swap(s -= q * u, u);
	swap(t -= q * v, v);
	swap(y -= q * x, x);
    }
    return y;
}

LL inv_mod(LL a, LL mod) {
    LL x, y;
    if (extgcd(a, mod, x, y) == 1) return (x + mod) % mod;
    return 0; // unsolvable
}

LL ans;
LL N;

void update(LL K) {

    LL a = K, b = K+1, n = N;
    if (a % 2 == 0) a /= 2;
    else b /= 2;
    n /= gcd(a, n);
    n /= gcd(b, n);

    if (n == 1) {
	amin(ans, K);
    } else {
	eprintf("%lld !\n", K);
    }
}

LL safe_mul(LL x, LL y, const LL mod) {
    if (y == 0) return 0;
    if (y == 1) return x % mod;
    x %= mod;
    y %= mod;
    LL r = 0;
    for (;y; y>>=1) {
	if (y&1) {
	    r += x;
	    if (r >= mod) r -= mod;
	}
	x += x;
	if (x >= mod) x -= mod;
    }

    return r;
}

void solve(LL p) {
    LL q = N / p;

    if (gcd(2*p, q) == 1) {
	LL x;
	if (q == 1) {
	    x = 1;
	} else {
	    LL inv_p = inv_mod(2*p % q, q);
	    x = safe_mul(q-1, inv_p, q);
	}
	update(2*x*p);
    }
    if (gcd(2*q, p) == 1) {
	LL y;
	if (p == 1) {
	    y = 1;
	} else {
	    y = inv_mod(2*q % p, p);
	}
	update(2*y*q-1);
    }
}

