// @param m `1 <= m`
// @return x mod m
constexpr long long safe_mod(long long x, long long m) {
    x %= m;
    if (x < 0) x += m;
    return x;
}

// @param b `1 <= b`
// @return pair(g, x) s.t. g = gcd(a, b), xa = g (mod b), 0 <= x < b/g
constexpr std::pair<long long, long long> inv_gcd(long long a, long long b) {
    a = safe_mod(a, b);
    if (a == 0) return {b, 0};

    // Contracts:
    // [1] s - m0 * a = 0 (mod b)
    // [2] t - m1 * a = 0 (mod b)
    // [3] s * |m1| + t * |m0| <= b
    long long s = b, t = a;
    long long m0 = 0, m1 = 1;

    while (t) {
        long long u = s / t;
        s -= t * u;
        m0 -= m1 * u;  // |m1 * u| <= |m1| * s <= b

        // [3]:
        // (s - t * u) * |m1| + t * |m0 - m1 * u|
        // <= s * |m1| - t * u * |m1| + t * (|m0| + |m1| * u)
        // = s * |m1| + t * |m0| <= b

        auto tmp = s;
        s = t;
        t = tmp;
        tmp = m0;
        m0 = m1;
        m1 = tmp;
    }
    // by [3]: |m0| <= b/g
    // by g != b: |m0| < b/g
    if (m0 < 0) m0 += b / s;
    return {s, m0};
}


// (rem, mod)
std::pair<long long, long long> crt(const std::vector<long long>& r,
                                    const std::vector<long long>& m) {
    assert(r.size() == m.size());
    int n = int(r.size());
    // Contracts: 0 <= r0 < m0
    long long r0 = 0, m0 = 1;
    for (int i = 0; i < n; i++) {
        assert(1 <= m[i]);
        long long r1 = safe_mod(r[i], m[i]), m1 = m[i];
        if (m0 < m1) {
            std::swap(r0, r1);
            std::swap(m0, m1);
        }
        if (m0 % m1 == 0) {
            if (r0 % m1 != r1) return {0, 0};
            continue;
        }
        // assume: m0 > m1, lcm(m0, m1) >= 2 * max(m0, m1)

        // (r0, m0), (r1, m1) -> (r2, m2 = lcm(m0, m1));
        // r2 % m0 = r0
        // r2 % m1 = r1
        // -> (r0 + x*m0) % m1 = r1
        // -> x*u0*g % (u1*g) = (r1 - r0) (u0*g = m0, u1*g = m1)
        // -> x = (r1 - r0) / g * inv(u0) (mod u1)

        // im = inv(u0) (mod u1) (0 <= im < u1)
        long long g, im;
        std::tie(g, im) = inv_gcd(m0, m1);

        long long u1 = (m1 / g);
        // |r1 - r0| < (m0 + m1) <= lcm(m0, m1)
        if ((r1 - r0) % g) return {0, 0};

        // u1 * u1 <= m1 * m1 / g / g <= m0 * m1 / g = lcm(m0, m1)
        long long x = (r1 - r0) / g % u1 * im % u1;

        // |r0| + |m0 * x|
        // < m0 + m0 * (u1 - 1)
        // = m0 + m0 * m1 / g - m0
        // = lcm(m0, m1)
        r0 += x * m0;
        m0 *= u1;  // -> lcm(m0, m1)
        if (r0 < 0) r0 += m0;
    }
    return {r0, m0};
}


int main(int argc, char *argv[]) {
  i64 N;
  cin >> N;
  N *= 2;
  vi P;

  auto factorize = [&](i64 p) {
    if(N % p == 0) {
      i64 a = 1;
      while(N % p == 0) {
	N /= p;
	a *= p;
      }
      P.pb(a);
    }
  };

  factorize(2);
  i64 p=3;
  while(p*p < N) {
    factorize(p);
    p += 2;
  }

  if(N != 1) {
    P.pb(N);
  }

  i64 M = sz(P);
  i64 B = 1LL << M;
  i64 ans = -1, b, j;
  auto update = [&](i64 p) {
    if(p == -1) {
      return;
    }

    if(ans == -1) {
      ans = p;
    }
    else {
      ans = min(ans, p);
    }
  };
  REP(0, B, b) {
    i64 p = 1, q = 1;
    REP(0, M, j) {
      if((b & (1LL << j)) != 0) {
	p *= P[j];
      }
      else {
	q *= P[j];
      }
    }

    //cout << p << " " << q << " " << endl;
    if(p == 1) {
      update(q-1);
    }
    else if(q == 1) {
      update(p);
    }
    else {
      vi r = {0, q-1};
      vi m = {p, q};
      pi c = crt(r, m);
      if(c.first != 0 || c.second != 0) {
	//cout << p << " " << q << " " << c.first << " " << c.second << endl;
	update(c.first);
      }
    }
  }

  assert(ans != -1);
  cout << ans << endl;

  return 0;
}

