template <class T> vector<T> Divisor(T n) {
	assert(0 < n);
	vector<T> res;
	T i = 1;
	for (; i * i < n; ++i)
		if (n % i == 0) res.push_back(i);
	bool flag = i * i == n;
	if (flag) res.push_back(i);
	for (i = (int)res.size() - 1 - flag; i >= 0; --i)
		res.push_back(n / res[i]);
	return res;
}

template <class T> T extGcd(T a, T b, T& x, T& y) {
	T d = a;
	if (b != 0) {
		d = extGcd(b, a % b, y, x);
		y -= (a / b) * x;
	} else {
		x = 1;
		y = 0;
	}
	return d;
}

