template<class T>
vector<T> calc_divisor(T n) {
    vector<T> res;
    for (T i = 1; i*i <= n; ++i) {
        if (n % i == 0) {
            res.push_back(i);
            T j = n / i;
            if (j != i) res.push_back(j);
        }
    }
    sort(res.begin(), res.end()); 
    return res;
}
template<typename T>
T extgcd(T a,T b,T& x,T& y){
  T d=a;
  if(b!=0){
    d=extgcd(b,a%b,y,x);
    y-=(a/b)*x;
  }else{
    x=1;y=0;
  }
  return d;
}

