    ll ans = LINF;
    rep(i, divs.size()) {
        ll x,y;
        ll gy = (2*n)/divs[i];
        ll gcd = extgcd(divs[i], gy, x, y);
        if(gcd!=1) continue;
        while(y>=0) {
            y -= divs[i];
            x += gy;
        } 
        chmin(ans, gy*-y);
    }
    cout << ans << endl;
}

