template <typename T>
T extgcd(T a, T b, T &x, T &y) {
    // assert(a>=0 && b>=0);
    T d = a;
    if (b) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1;
        y = 0;
    }
    return d;
}
