        // k2 *= ret.second.second;
        // __int128 cand = k1 < k2 ? k1 : k2;
        ll cand = k1;
        if(cand == 0){
            continue;
        }
        ans = min(ans, cand);
        printde(num1, num2, ret);
        printde(k1, k2, cand);
    }
    return ans;
}

