int main() {
	ll n;
	scanf("%lld", &n);
	ll n2 = n;
	if (n == 1) {
		return 0 * puts("1");
	}
	vector<pair<int, int>> factors;
	for (ll i = 2; i * i <= n; i++) {
		if (n % i == 0) {
			int cnt = 1;
			n /= i;
			while (n % i == 0) {
				cnt += 1;
				n /= i;
			}
			//cout << "INS " << i << " " << cnt << endl;
			factors.push_back({i, cnt});
		}
	}
	if (n > 1) factors.push_back({n, 1});
	if (factors[0].first == 2) factors[0].second += 1;
	else factors.push_back({2, 1});
	//assert(factors.size() <= 16);
	ll ans = 2 * n2 - 1;
	if (n2 % 2 == 1) ans = n2 - 1;
	int m = (int)factors.size();
	for (int mask = 1; mask < (1 << m) - 1; mask++) {
		ll mul1 = 1, mul2 = 1;
		for (int i = 0; i < m; i++) {
			if (mask & (1 << i)) {
				for (int j = 0; j < factors[i].second; j++) mul1 *= factors[i].first;
			} else {
				for (int j = 0; j < factors[i].second; j++) mul2 *= factors[i].first;
			}
		}
		ans = min(ans, solve(mul1, mul2));
	}
	printf("%lld\n", ans);
	return 0;
}

