  for (ll i = 2; i * i <= n; i++) if (2*n % i == 0) {
    if (extgcd(i, 2*n/i, x, y) == 1) {
      if (x < 0) {
        if (i * -x + 1 == 2*n/i * y) ans = min(ans, -i*x);
      } else {
        if (2*n/i * -y + 1 == i * x) ans = min(ans, 2*n/i * -y);
      }
    }
  }
  printf("%lld\n", ans);
}

