ll __lcm(ll a, ll b) {
    return a / __gcd(a, b) * b;
}

ll gcd(ll a, ll b, ll & x, ll & y) {
    if (a == 0) {
        x = 0; y = 1;
        return b;
    }
    ll x1, y1;
    ll d = gcd(b % a, a, x1, y1);
    x = y1 - (b / a) * x1;
    y = x1;
    return d;
}

bool find_any_solution(ll a, ll b, ll c, ll& x0, ll& y0) {
    ll A = a, B = b;
    if (A < 0) A *= -1;
    if (B < 0) B *= -1;
    ll g = gcd(A, B, x0, y0);
    if (c % g != 0) return 0;
    x0 *= c / g;
    y0 *= c / g;
    if (a < 0) x0 *= -1;
    if (b < 0) y0 *= -1;
    return 1;
}

ll CRT_2(Equ p, Equ q) {
    ll x, y;
    if (!find_any_solution(p.mod, -q.mod, q.r - p.r, x, y)) {
        return -1;
    }
    ll X = p.mod * x + p.r;
    ll tot_mod = __lcm(p.mod, q.mod);
    X = (X % tot_mod + tot_mod) % tot_mod;
    return X;
}

Equ merge(Equ p, Equ q) {
    return {CRT_2(p, q), __lcm(p.mod, q.mod)};
}

ll CRT(vector<Equ> vec) {
    Equ cur = vec[0];
    for (int i = 1; i < vec.size(); i++) {
        cur = merge(cur, vec[i]);
        if (cur.r == -1) {
            return -1;
        }
    }
    return cur.r;
}

ll calc(ll a, ll b) {
    ll res = -1;
    if ((a * b) & 1) {
        res = CRT_2({0, a}, {b - 1, b});
    }
    else {
        if (!(a & 1)) {
            res = CRT_2({0, 2 * a}, {b - 1, b});
        }
        else {
            res = CRT_2({0, a}, {2 * b - 1, 2 * b});
        }
    }
    if (!res) {
        res = a * b;
    }
    return res;
}

