bool isp(ll n){
   if(n<2 or n%2==0)return (n==2);
   ll d=n-1; while(d%2==0)d>>=1;
   for(ll x:{2,325,9375,28178,450775,9780504,1795265022}){
      if(n<=x)break;
      ll t=d,y=mpow(x,t,n);
      while(t!=n-1 and y!=1 and y!=n-1){
         y=(__int128_t(y)*y)%n; t<<=1;
      }
      if(y!=n-1 and t%2==0)return 0;
   } return 1;
}

vector<ll> pollard(ll n){
   if(n<=1)return {};
   if(isp(n))return {n};
   if(n%2==0){
      vector<ll> v=pollard(n/2); v.push_back(2);
      return v;
   }
   for(ll c=1,x=2,y=2,d;;c++){
      do{
         x=(__int128_t(x)*x+c)%n;
         y=(__int128_t(y)*y+c)%n;
         y=(__int128_t(y)*y+c)%n;
         d=__gcd(x-y+n,n);
      }while(d==1);
      if(d<n){
         vector<ll> lb=pollard(d),rb=pollard(n/d);
         lb.insert(lb.end(),ALL(rb)); return lb;
      }
   }
}

