		int x=1,y=1;
		int j=0;
		for(auto k:mp){
			if(i>>j&1){
				x*=mod_pow(k.first,k.second,inf);
			}else {
				y*=mod_pow(k.first,k.second,inf);
			}
			j++;
		}
		if(x!=1){
			chmin(ans,CRT(x-1,x,0,y).first);
		}
	}
	cout<<ans<<"\n";
}

