map<ll, int> prime_factors(ll n) {
    map<ll, int> res;
    if(n == 1) {
        return res;
    }
    for(ll i = 2, _n = n; i*i <= _n; ++i) {
        while(n % i == 0) {
            ++res[i]; // 素数i^{res[i]}
        n /= i;
        }
    }
    if(n != 1) res[n] = 1;
    return res;
}

ll lpow(ll a, ll b) {
    if (b==0)return 1;
    if (b==1)return a;
    ll r = lpow(a, b/2);
    r *= r;
    if (b%2) r *= a;
    return r;
}

// https://qiita.com/drken/items/ae02240cd1f8edfc86fd#n-元の場合
inline long long mod(long long a, long long m) {
    return (a % m + m) % m;
}

long long extGcd(long long a, long long b, long long &p, long long &q) {
    if (b == 0) { p = 1; q = 0; return a; }
    long long d = extGcd(b, a%b, q, p);
    q -= a/b * p;
    return d;
}

// 中国剰余定理
ll ChineseRem(const map<ll, ll>&n) {
  long long r = 0, M = 1;
  for (auto Q: n) {
    long long p, q;
    long long d = extGcd(M, Q.F, p, q); // p is inv of M/d (mod. m[i]/d)
    if ((Q.S - r) % d != 0) return -1;
    long long tmp = (Q.S - r) / d * p % (Q.F/d);
    r += M * tmp;
    M *= Q.F/d;
  }
  return mod(r, M);
}

