void ys(map<ll, int>& p, const mp&m, const mp::iterator it, map<ll, ll>&r) {
    if (it == m.end()) {
        func(r);
        return;
    }

    const auto nx = next(it);
    for (int a: it->S) {
        r[it->F] = a; // it->F を法としたときaと合同
        ys(p, m, nx, r);
    }
}

