#include <bits/stdc++.h>
using namespace std;
long long ext_gcd(long long a, long long b, long long &x, long long &y) {
		if (b == 0) {
				x = 1, y = 0;
				return a;
		}
		long long x2, y2;
		long long d = ext_gcd(b, a%b, x2, y2);
  		x = y2;
  		y = x2 - (a / b)*y2;
		return d;
}
long long mod_inv(long long a, long long m) {
	long long x, y;
	long long d = ext_gcd(a, m, x, y);
	if (d != 1) {
		return -1;
	}
	x %= m;
	if (x < 0)x += m;  // 負の数の剰余を考慮
	return x;
}
long long garner(vector<long long> r, vector<long long> m){
	int n = r.size();
	long long m_prod = 1;
	long long x = r[0] % m[0];
	for (int i = 1; i < n; i++) {
		m_prod *= m[i - 1];
		long long t = ((r[i] - x) * mod_inv(m_prod, m[i])) % m[i];
		if (t < 0)t += m[i];
		x += t * m_prod;
	}
	return x;
}
int main(){
	long long N; cin >> N; 
	if(N == 1){
		cout << 1 << "\n"; return 0; 
	}
	long long now = N * 2; 
	vector<long long> M; 
	for(long long i = 2; i * i <= N * 2; i++){
		if(now % i != 0) continue;
		long long mul = 1LL;  
		while(now % i == 0){
			mul *= i; now /= i; 
		}
		M.emplace_back(mul); 
	}
	if(now > 1){
		M.push_back(now); 
	}
	int D = M.size(); 
	long long ans = N * 2; 
	for(int i = 0; i < (1 << D); i++){
		vector<long long> R; 
		for(int j = 0; j < D; j++){
			if((i >> j) & 1) R.emplace_back(M.at(j) - 1); 
			else R.emplace_back(0); 
		}
		long long tmp = garner(R, M); 
		if(tmp == 0) tmp += N * 2; 
		ans = min(ans, tmp); //cout << tmp << endl; 
	}
	cout << ans << endl; 
}

