L exgcd(L a, L b, L &x, L &y){
  if(b == 0){
    x = 1; y = 0;
    return a;
  }
  L result = exgcd(b, a % b, x, y);
  L tp = x;
  x = y;
  y = tp - a / b * y;
  return result;
}

int main() {
  ll n, nn;
  read(n); nn = n * 2;
  for (int i = 2, li = sqrt(nn); i <= li; ++i) {
    if (nn % i == 0) {
      fac[cnt] = 1;
      do fac[cnt] *= i, nn /= i; while (nn % i == 0);
      ++cnt;
    }
  }
  if (nn) fac[cnt++] = nn;
  L res = numeric_limits<ll>::max();
  for (int i = 0; i < (1 << cnt); ++i) {
    ll p = 1;
    for (int j = 0; j < cnt; ++j)
      if ((i >> j) & 1)
        p *= fac[j];
    ll q = n * 2 / p;
    L x, y;
    exgcd(p, q, x, y);
    x = -x;
    if (x >= 0) {
      ll c = x / q;
      x %= q; y -= p * c;
    }
    else {
      ll c = x / q;
      x %= q;
      if (x < 0) x += q, --c;
      y -= p * c;
    }
    if (x > 0 && y > 0) {
      res = min(L(res), x * p);
    }
  }
  write(res), endl();
  return 0;
}

