void linear_sieve(int n,vector<int>& prime,vector<int>& seive){
  int a=seive.size()-1;
  if(a>=n or n<=1) return;
  seive.resize(n+1,0);
  seive[1]=1;
  rep(i,n/2+1){
    if(df)print("i,a",i,a);
    if(i<a)i=a;
    if(i<2){i=1;continue;}
    if(seive[i]==0){
      seive[i]=i;
      prime.push_back(i);
      if(df)printf("[%d]%d ",i,i);
    }
    for(int p:prime){
      if(p>seive[i] or i*p>n) break;
      seive[i*p]=p;
      if(df)printf("[%d]%d ",i*p,p);
    }
    if(df)print("");
  }
  rep(i,n+1){
    if(i==0) i=n/2;
    if(seive[i]==0){
      seive[i]=i;
      prime.push_back(i);
    } 
  }
}

void factorization(li n,map<li,int>& factors,int q=1){
  // require cmath
  factors.clear();
  static vector<int> prime,seive;
  const static int s_max=80000000;
  int a=seive.size()-1;
  int sq=sqrt(n)+1;
  if(q>sq) sq=n;
  //  if(df)print(sq);
  sq=min(sq,s_max);
  //  if(df)print(sq);
  if(a<sq) linear_sieve(sq,prime,seive);
  a=seive.size()-1;
  //  if(df)print("seive_size",a);
  while(n>a){
    for(int p:prime){
      while(n%p==0){
        factors[p]++;
        n/=p;
      }
      if(n<=a) break;
    }
    if(n>a){
      if(factors.size()==0){
        if(s_max<sqrt(n)+1)
          print(n,"has too large prime as factor!!!!!");
        else factors[n]++;
        return;
      }
      map<li,int> f;
      factorization(n,f);
      for(auto p:f){
        factors[p.first]+=p.second;
      }
      return;
    }
  }
  while(n!=1){
    int p=seive[n];
    factors[p]++;
    n/=p;
  }
}

li pow(li a,int r){
  li b=a,ans=1;
  while(r){
    if(r%2) ans*=b;
    b*=b;
    r/=2;
  }
  return ans;
}


