    n *= 2;
    vector<p> fact = factor(n);
    int N = (1 << fact.size()), ans = INF;
    for (int q = 0; q < N; q++){
        int pr = 1;
        for (int q1 = 0; q1 < fact.size(); q1++){
            if ((q >> q1) & 1){
                pr *= fact[q1].second;
            }
        }
        pair<int, p> ans1 = ax_by(pr, n/pr);
        if (ans1.first == 1){
            int t = min(mul(abs(ans1.second.first), pr), mul(abs(ans1.second.second), n/pr));
            if (t > 0 && ans > t) {
                ans = t;
            }
            if (ans1.second.first > 0){
                ans1.second.first -= n/pr/ans1.first, ans1.second.second += pr/ans1.first;
            }else{
                ans1.second.first += n/pr/ans1.first, ans1.second.second -= pr/ans1.first;
            }
            t = min(mul(abs(ans1.second.first), pr), mul(abs(ans1.second.second), n/pr));
            if (t > 0 && ans > t) {
                ans = t;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

