vector<ll> divisors;
void factorize(ll n){

    for(ll i = 1; i*i <= n; i++){
        if(n % i != 0) continue;
        divisors.push_back(i);
        if(i != n/i)
            divisors.push_back(n/i);
    }
}

ll egcd(ll a, ll b, ll &x, ll &y){
    if(a == 0) {x = 0, y = 1; return b;}

    ll x1, y1, d = egcd(b % a, a, x1, y1);
    x = y1 - (b/a)*x1;
    y = x1;
    return d;
}

