vector<bool> furui_bool(ll n) {
  vector<bool> fu(n + 1, 1);
  fu.at(0) = 0; fu.at(1) = 0;
  for (ll i=2; i <= n/2 + 1; i++) {
    if (fu.at(i) == 1) {
      ll j = 2 * i;
      while (j <= n) {
        fu.at(j) = 0;
        j += i;
      }
    }
  }
  return fu;
}

vector<ll> prime_fac(ll n, ll &mx) {
  ll sq = sqrt(n);
  vector<ll> pr(sq + 1, 0);
  vector<bool> fu = furui_bool(sq + 2);
  for (ll i=2; i <= sq; i++) {
    if (fu.at(i)) {
      while (n % i == 0) {
        n /= i;
        mx = i;
        pr.at(i)++;
      }
    }
  }
  if (n > 1) {
    mx = n;
  }
  return pr;
}

