lint n;

// 素因数分解 O(√N)
vector<pair<lint, lint>> pf_vec(long long int n) {
    vector<pair<lint, lint>> res;
    for (long long int i = 2; i * i <= n; i++)
        if (n % i == 0) {
            lint num = 0;
            while (n % i == 0) {
                num++;
                n /= i;
            }
            res.push_back({i, num});
        }
    if (n != 1) res.push_back({n, 1});
    return res;
}

pair<lint, lint> ext_gcd(lint a, lint b) {
    if (a > b) {
        auto temp = ext_gcd(b, a);
        return make_pair(temp.second, temp.first);
    } else {
        if (a == 0) {
            return make_pair(0, 1);
        } else {
            auto temp = ext_gcd(a, b % a);
            int v = temp.first, w = temp.second;
            return make_pair(v - w * (b / a), w);
        }
    }
}

lint f(lint a, lint q) {
    if (q > 0) {
        return -((q - 1) / a);
    } else if (q == 0) {
        return 1;
    } else {
        return (1 - q + a - 1) / a;
    }
}

// ax-by=1なる最小のbyを求める
lint solve(lint a, lint b) {
    auto sol = ext_gcd(a, b);
    lint p = sol.first;
    lint q = -sol.second;
    lint K = max(f(a, q), f(b, p));
    return b * (a * K + q);
}

template <class T>
bool chmin(T &a, const T &b) {
    if (a > b) {
        a = b;
        return 1;
    }
    return 0;
}

// a^nを計算　O(log n)
long long int powint(long long int a, long long int n) {
    if (n == 0) {
        return 1;
    } else {
        long long int temp = powint(a, n / 2);
        if (n % 2 == 0) {
            return temp * temp;
        } else {
            return temp * temp * a;
        }
    }
}

int main() {
    cin >> n;
    auto pf = pf_vec(2 * n);
    lint num = pf.size();
    lint ans = LLONG_MAX;
    for (lint i = 0; i < (1LL << num); i++) {
        bitset<40> b(i);
        lint A = 1, B;
        for (int j = 0; j < num; j++) {
            if (b[j]) {
                A *= powint(pf[j].first, pf[j].second);
            }
        }
        B = 2 * n / A;
        chmin(ans, solve(A, B));
    }
    cout << ans << endl;
}

