            }
        }
        if(!(k%2))continue;
        if(k==n){
            ret = min(ret,k);
            continue;
        }
        LL kcomp = n/k;
        LL ret_ = extGCD(k,kcomp,x,y);
        //cerr<<k<<" "<<kcomp<<" "<<x<<endl;
        LL kk = ((kcomp-(x+kcomp)%kcomp)*k);
        ret = min(ret,kk);

        kk = (((x+kcomp)%kcomp)*k);
        if(kk!= 1) ret = min(ret,kk-1);
    }
    cout<<ret<<endl;
}

