typedef long long ll;
void exgcd(ll a, ll b, ll& x, ll& y, ll& c)
{
    if(!b) {y = 0; x = 1; c = a; return;}
    exgcd(b, a % b, y, x,c); y -= a / b * x;
}
ll gcd(ll a,ll b){return b==0?a:gcd(b,a%b);}
ll n,x,y,u,v,ans=-1,a,b;
ll solve(ll x,ll y)
{
	ll v,u,d;
	exgcd(x,y,u,v,d);
	if(u>0)u-=y*((u-1)/y+1);
	else u+=y*((-u)/y);
	if(v>0)v-=x*((v-1)/x+1);
	else v+=x*((-v)/x);
	return min(-u*x,-v*y);
}
int main()
{
