	ans=n-1;
	for(int i=2;1ll*i*i<=n;i++)
	{
		if(n%i)continue;
		x=i;y=n/i;
		if(gcd(x,y)>1)continue;
		a=solve(x,y),solve(y,x);
		ans=min(a,ans);
	}
	printf("%lld\n",ans);
	return 0;
}

