int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll n = in1;

    if (n == 1) {
        say(1);
        return 0;
    }

    // min. k s.t. k(k+1)/2 === 0 mod N

    auto nd = divisor(n*2);
    sort(ALLOF(nd));

    ll ans = LINF;
    FOREACH(di, nd) {
        FOREACH(dj, nd) {
            if (gcd(di, dj) != 1) continue;
            ll x, y;
            extgcd(di, -dj, x, y);
            if (x == 0 || y == 0) {
                ll l = lcm(di, dj);
                x += l / di;
                y += l / dj;
            }
            ll k = dj * y;
            if (k*(k+1)/2 % n == 0) {
                chmin(ans, k);
            }
        }
    }
    say(ans);

}

