inline ll exgcd(ll a,ll b,ll &x,ll &y)
{
	if(a==0)
	{
		x=0;
		y=1;
		return b;
	}
	ll gcd=exgcd(b%a,a,x,y);
	swap(x,y);
	x-=(b/a)*y;
	return gcd;
}

