pair<ll, pair<ll, ll>> exGCD(ll a, ll b){
	bool inv = false;
	if(a < b){
		swap(a, b);
		inv = true;
	}
	static vector<ll> r = {a, b}, ks;
    r.resize(2); r[0] = a; r[1] = b;
    ks.clear();
	while(b){
		ks.push_back(a / b);
		r.push_back(a = a % b);
		swap(a, b);
	}
	ll gcd = a;

	ll x = 0, y = 1, u = 1, v = -ks[0];
	for(int i = 1; i < (int)ks.size(); i++){
		ll k = ks[i];
		ll x2 = u, y2 = v,
		   u2 = x - k * u, v2 = y - k * v;
		x = x2; y = y2; u = u2; v = v2;
	}

	if(inv){
		swap(x, y);
	}
	return {gcd, {x, y}};
}

map<ll, int> factorization(ll n){
    map<ll, int> fs;
    auto sq = sqrt(n);
    for(int i = 2; i <= sq; i++){
        while(n % i == 0){
            fs[i]++;
            n /= i;
        }
    }
    if(n > 1){
        fs[n]++;
    }
    return fs;
}

