void solve()
{
    ll n;
    cin>>n;
    n*=2;
    ll mini=0;
    while(n%2==0)
    {
        n/=2;
        mini++;
    }
    if(n==1)
    {
        cout<<(1LL<<mini)-1<<'\n';
        return;
    }
    vl oddfactors;
    for(ll i=1;i*i<=n;i++)
    {
        if((n%i)==0)
        {
            oddfactors.pb(i);
            if((n/i)!=i)
                oddfactors.pb(n/i);
        }
    }
    vl primefactors;
    ll waste=n;
    for(ll i=2;i*i<=waste;i++)
    {
        if((waste%i)==0)
        {
            while((waste%i)==0)
                waste/=i;
            primefactors.pb(i);
        }
    }
    if(waste!=1)
        primefactors.pb(waste);
    vl bad;
    for(auto it:oddfactors)
    {
        if((__gcd(it,n/it))!=1)
            continue;
        bad.pb(it);
    }
    swap(bad,oddfactors);
    mod=n;
    ll ans=1e18;
    for(int i=mini;i<=50;i++)
    {
        ll mult=(1LL<<i);
        for(auto odd:oddfactors)
        {
            long double fun=(long double)mult*odd;
            if(fun>1e16)
                continue;
            ll res;
            ll a=mult*odd;
            ll rem=n/odd;
            if(rem==1)
            {
                res=1;
            }
            else
            {
                mod=n/odd;
                ll phi=mod;
                for(auto it:primefactors)
                {
                    if(mod%it==0)
                    {
                        phi/=it;
                        phi*=(it-1);
                    }
                }
                ll fun=power(a,phi-1);
                res=fun;
            }
            if((((res%rem)*(a%rem)))%rem!=1)
                continue;
            fun=(long double)mult*odd*res;
            if(fun>1e16)
                continue;
            ans=min(ans,mult*res*odd-1);
        }
    }
    for(int i=mini;i<=50;i++)
    {
        ll mult=(1LL<<i);
        for(auto odd:oddfactors)
        {
            long double fun=(long double)mult*odd;
            if(fun>1e16)
                continue;
            ll res;
            ll a=mult*odd;
            ll rem=n/odd;
            if(rem==1)
            {
                res=1;
            }
            else
            {
                mod=n/odd;
                ll phi=mod;
                for(auto it:primefactors)
                {
                    if(mod%it==0)
                    {
                        phi/=it;
                        phi*=(it-1);
                    }
                }
                ll fun=power(a,phi-1);
                res=(fun*(mod-1))%mod;
            }
            if((((res%rem)*(a%rem)))%rem!=rem-1)
                continue;
            fun=(long double)mult*odd*res;
            if(fun>1e16)
                continue;
            ans=min(ans,mult*res*odd);
        }
    }
    cout<<ans<<'\n';
}
