void p_ini(int n) {
	is_prime.resize(n, true);
	is_prime[0] = false;
	is_prime[1] = false;
	for (int i = 2; i < n; i++) {
		if (!is_prime[i])
			continue;
		for (int j = i * 2; j < n; j += i)
			is_prime[j] = false;
	}
	return;
}

vector<pll> prime_factor(ll n) {
	vector<pll> prime_factor_n;
	ll sqrt_n = sqrt(n) + 10;
	p_ini(sqrt_n);
	rep(i, sqrt_n) {
		if (!is_prime[i])
			continue;
		if (n % i == 0) {
			ll count = 0;
			while (1) {
				n /= i;
				count++;
				if (n % i != 0)
					break;
			}
			prime_factor_n.push_back(make_pair(i, count));
		}
	}
	if (n > 1)
		prime_factor_n.push_back(make_pair(n, 1));
	return prime_factor_n;
}

