    auto ma = prime_factor(n);

    vector<ll> factors;
    for (auto it = ma.begin(); it != ma.end(); ++it) {
        ll x = 1;
        for (int i = 0; i < it->second; i++)x *= it->first;
        factors.push_back(x);
    }

    int k = factors.size();
    ll ret = n - 1;
    for (int bit = 1; bit < (1 << k) - 1; bit++) {
        ll a = 1, b = 1;
        for (int i = 0; i < k; i++) {
            if (bit & (1 << i))a *= factors[i];
            else b *= factors[i];
        }

        ll x, y;
        extgcd(a, b, x, y);

        a *= x, b *= y;
        if (a < 0) a = -a;
        else b = -b;

        ret = min(ret, min(a, b));
    }

    cout << ret << endl;
    return 0;
}

