    if(N == 1) {
        cout << 1 << endl;
        return 0;
    } else if(N == 2) {
        cout << 3 << endl;
        return 0;
    }
    auto factor = prime_factor(N);
    factor[2]++;
    vector<pll> bit;
    for(auto x : factor) {
        bit.pb(x);
    }
    int n = bit.size();
    ll res = LINF;
    for(int b = 0; b < (1 << n); b++) {
        ll k1 = 1, k2 = 1;
        for(int i = 0; i < n; i++) {
            if(b & (1 << i)) {
                k1 *= power(bit[i].first, bit[i].second);
            } else {
                k2 *= power(bit[i].first, bit[i].second);
            }
        }
        ll x, y;
        extgcd(k1, k2, x, y);
        if(x < 0) {
            res = min(k1 * (-x), res);
        } else if(y < 0) {
            res = min(k2 * (-y), res);
        } else
            continue;
    }
    cout << res << endl;
}

