}
vector<pair<long long, long long> > FF(long long n) {
	vector<pair<long long, long long> > vec;
	for (long long i = 2; i * i <= n; i++) if (n % i == 0) {
		int cc = 0;
		long long pp = 1;
		while (n % i == 0) {
			cc++;
			n /= i;
			pp *= (long long)i;
		}
		vec.push_back(make_pair(i, pp));
	}
	if (n > 1) vec.push_back(make_pair(n, n));
	return vec;
}
