	for (int i = 0; i < (int)vec.size(); i++) {
		m1[i] = n / vec[i].second;
		m2[i] = calcinv(m1[i] % vec[i].second, vec[i].second);
	}
	long long ans = 0;
	for (int mask = 1; mask < (1 << vec.size()); mask++) {
		long long cur = 0;
		for (int i = 0; i < (int)vec.size(); i++) if (mask >> i & 1) {
			cur += m1[i] * m2[i];
		}
		cur %= n;
		ans = max(ans, cur);
	}
