	    r += x;
	    if (r >= mod) r -= mod;
	}
	x += x;
	if (x >= mod) x -= mod;
    }

    return r;
}

void solve(LL p) {
    LL q = N / p;

    if (gcd(2*p, q) == 1) {
	LL x;
	if (q == 1) {
	    x = 1;
	} else {
	    LL inv_p = inv_mod(2*p % q, q);
	    x = safe_mul(q-1, inv_p, q);
	}
	update(2*x*p);
    }
    if (gcd(2*q, p) == 1) {
	LL y;
	if (p == 1) {
	    y = 1;
	} else {
	    LL inv_q = inv_mod(2*q % p, p);
	    y = safe_mul(p-1, inv_q, p);
	}
	update(2*y*q-1);
    }
}

void MAIN() {
    scanf("%lld", &N);
    ans = 2*N;

    if (N % 2 == 1) {
	amin(ans, N);
    }

    for (LL i=1; i*i<=N; i++) if (N % i == 0) {
	solve(i);
	if (i*i != N) solve(N/i);
    }

    printf("%lld\n", ans);
}

