fun Long.pow(power: Long, mod: Long): BigInteger {
    val mod = BigInteger.valueOf(mod)
    var e = power
    var b = BigInteger.valueOf(this) % mod
    var res = BigInteger.ONE
    while (e > 0) {
        if (e and 1L != 0L) {
            res *= b
            res %= mod
        }
        b *= b
        b %= mod
        e = e shr 1
    }
    return res
}

