inline fun Long.modInvOrElse(base: Long, default: () -> Long): Long {
    var s = 0L
    var os = 1L
    var r = base
    var or = this % base

    while(r != 0L) {
        val q = or / r
        or = r.also { r = or - q * r }
        os = s.also { s = os - q * s }
    }

    return if(or != 1L) default()
    else os.let { if(it >= 0) it else it + base }
}

