    if(this <= 0) return
    val tail = LongList()

    for(p in 1..this) {
        val sq = p * p
        if(sq > this) break
        if(this % p == 0L) {
            yield(p)
            if(sq != this) tail.add(this / p)
        }
    }

    for(i in tail.lastIndex downTo 0) yield(tail[i])
}

