    static class BSumIsMultiple {
        public void solve(int testNumber, LightScanner2 in, LightWriter2 out) {
            long n = in.longs() * 2;
            long ans = 2 * n;
            for (int i = 2; i * i <= n; i++) {
                if (n % i != 0) continue;
                long a = i, b = n / i;
                ans = Math.min(ans, solve(a, b));
                ans = Math.min(ans, solve(b, a));
            }
            out.ans(ans).ln();
        }

        private static long solve(long a, long b) {
            if (IntMath.gcd(a, b) != 1) return Long.MAX_VALUE;
            Vec3l s = LongEuclidSolver.solve(b, -a);
            //System.out.println(a + "*" + s.y + "-" + b + "*" + s.x + "=1");
            return s.y * a;
        }

    }

    static class Vec3i implements Comparable<Vec3i> {
        public int x;
        public int y;
        public int z;

        public Vec3i(int x, int y, int z) {
            this.x = x;
            this.y = y;
            this.z = z;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Vec3i vec3i = (Vec3i) o;
            return x == vec3i.x &&
                    y == vec3i.y &&
                    z == vec3i.z;
        }

        public int hashCode() {
            return Objects.hash(x, y, z);
        }

        public String toString() {
            return "(" + x + ", " + y + ", " + z + ")";
        }

        public int compareTo(Vec3i o) {
            if (x == o.x) {
                if (y == o.y) {
                    return Integer.compare(z, o.z);
                }
                return Integer.compare(y, o.z);
            }
            return Integer.compare(x, o.x);
        }

    }

    static final class IntMath {
        private IntMath() {
        }

        public static long gcd(long a, long b) {
            long t;
            if (a == 0) return b;
            if (b == 0) return a;
            while (a % b > 0) {
                t = b;
                b = a % b;
                a = t;
            }
            return b;
        }

    }

