    static class BSumIsMultiple {
        public void solve(int testNumber, LightScanner2 in, LightWriter2 out) {
            long n = in.longs() * 2;
            if (n == 2) {
                out.ans(1).ln();
                return;
            }
            long ans = n;
            long[] ds = IntMath.getAllDivisors(n);
            for (long d : ds) {
                ans = Math.min(ans, solve(d, n / d));
            }
            out.ans(ans).ln();
        }

        private static long solve(long a, long b) {
            if (IntMath.gcd(a, b) != 1) return Long.MAX_VALUE;
            Vec3l s = LongEuclidSolver.solve(a, -b);
            long x = s.x, y = s.y;
            if (s.z == -1) {
                x *= -1;
                y *= -1;
            }
            // ax - by = 1
            // by = k
            while (y <= 0 || x <= 0) {
                x += b;
                y += a;
            }
            //System.out.println(a + "," + b + "," + s + "," + x + " | " + y);
            return b * y;
        }

    }

    static final class IntMath {
        private IntMath() {
        }

        public static long gcd(long a, long b) {
            long t;
            if (a == 0) return b;
            if (b == 0) return a;
            while (a % b > 0) {
                t = b;
                b = a % b;
                a = t;
            }
            return b;
        }

        public static long[] getAllDivisors(long p) {
            Set<Long> res = new TreeSet<>();
            for (long i = 1; i * i <= p; i++) {
                if (p % i != 0) continue;
                res.add(i);
                if (i * i != p) res.add(p / i);
            }
            return res.stream().mapToLong(x -> x).toArray();
        }

    }

