	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * ACL Contest 1 B問題
		 * 考察メモ
		 *
		 */
		io.setAutoFlush(false);
		io.setAutoOutFlush(false);
		long N = io.nextLong();
		if (N == 1) {
			io.println(1);
			return;
		}
		ArrayList<Long> list = new ArrayList<>();
		for (long i = 2;i * i <= N;++ i) {
			if (N % i == 0) {
				long add = 1;
				do {
					add *= i;
					N /= i;
				} while(N % i == 0);
				list.add(add);
			}
		}
		if (N != 1) list.add(N);
		long ans = (long)1e18;
		for (int i = 1, size = list.size(), l = 1 << size;i < l;++ i) {
			long[] r = new long[size], m = new long[size];
			for (int j = 0;j < size;++ j) {
				m[j] = list.get(j);
				if (m[j] % 2 == 0) m[j] *= 2;
				r[j] = ((i >> j & 1) == 0) ? 0 : m[j] - 1;
			}
			ans = Math.min(ans, ACL.MathLib.crt(r, m)[0]);
		}
		io.println(ans);
	}

