public void solve() {
	long num = nl() * 2;
	long div[] = div(num);
	long min = INF;
	for(long x : div) {
		long y = num / x;
		PairLL ans = chineseRem(new PairLL(0, x), new PairLL(y - 1, y));
		if(ans != null) min = min(min, ans.a == 0 ? ans.b : ans.a);
	}
	prtln(min);
}

// return (g,x) s.t. ax%mod=g=gcd(a,mod) && x>=0
PairLL invGcd(long a, long mod) { // O(loglcm(a,mod))
	PairLL s = new PairLL(mod, 0);
	PairLL t = new PairLL(a, 1);
	while(t.a > 0) {
		long tmp = s.a / t.a;
		PairLL u = new PairLL(s.a - t.a * tmp, s.b - t.b * tmp);
		s = t;
		t = u;
	}
	if(s.b < 0) s.b += mod / s.a;
	return s;
}
// return (g,x,y) s.t. ax+by=g=gcd(a,b) && |x|+|y| is minimal (primarily) && x<=y (secondarily)
TupleLLL extGcd(long a, long b) { // O(loglcm(a,b))
	TupleLLL s = new TupleLLL(a, 1, 0);
	TupleLLL t = new TupleLLL(b, 0, 1);
	while(t.a > 0) {
		long tmp = s.a / t.a;
		TupleLLL u = new TupleLLL(s.a - t.a * tmp, s.b - t.b * tmp, s.c - t.c * tmp);
		s = t;
		t = u;
	}
	return s;
}
// return (x, lcm(p.b)) s.t. x%p.b=p.a && x>=0 if exists otherwise null
PairLL chineseRem(PairLL[] p) { // O(Nloglcm(ps.a))
	int num = p.length;
	PairLL ans = new PairLL(0, 1);
	for(PairLL crt : p) {
		ans = chineseRem(ans, crt);
		if(ans == null) return ans;
	}
	return ans;
}
// return (x,lcm(p1.b,p2.b)) s.t. x%p1.b=p1.a && x%p2.b=p2.a && x>=0 if exists otherwise null
PairLL chineseRem(PairLL p1, PairLL p2) { // O(loglcm(p1.a,p2.a))
	TupleLLL ans = extGcd(p1.b, p2.b);
	if((p2.a - p1.a) % ans.a != 0) return null;
	long lcm = p1.b / ans.a * p2.b;
	long tmp = mul_m((p2.a - p1.a) / ans.a, ans.b, (p2.b / ans.a));
	return new PairLL(mod(p1.a + mul_m(p1.b, tmp, lcm), lcm), lcm);
}
// requirement: gcd(p[i].b,p[j].b)=1 for all (i,j) s.t. i!=j
// return x%mod s.t. x%p.b=p.a && x>=0
long garner(PairLL[] p, long mod) { // O(N^2+Nlogmax(p.a)))
	PairLL p2[] = new PairLL[p.length + 1];
	for(int i = 0; i < p.length; i ++) p2[i] = p[i];
	p = p2;
	p[p.length - 1] = new PairLL(mod, 0);
	long coffs[] = new long[p.length];
	fill(coffs, 1);
	long constants[] = new long[p.length];
	fill(constants, 0);
	for(int i = 0; i < p.length - 1; i ++) {
		long v = mul_m(p[i].b - constants[i], inv(coffs[i], p[i].a), p[i].a);
		for(int j = i + 1; j < p.length; j++) {
			constants[j] += mod(constants[j] + mul_m(coffs[j], v, p[j].a), p[j].a);
			coffs[j] = mul_m(coffs[j], p[i].a, p[j].a);
		}
	}
	return constants[p.length - 1];
}

