// http://www.tbasic.org/reference/old/ExEuclid.html
class ExtendedGcdSolver {
  long x, y, g;

  // Usage: solve(a, b)
  // a * this.x + b * this.y = this.g
  public long solve(long a, long b) {
    long r0 = a;
    long r1 = b;
    long x0 = 1;
    long x1 = 0;
    long y0 = 0;
    long y1 = 1;

    while (r1 > 0) {
      long q1 = r0 / r1;
      long r2 = r0 % r1;
      long x2 = x0 - q1 * x1;
      long y2 = y0 - q1 * y1;
      r0 = r1;
      r1 = r2;
      x0 = x1;
      x1 = x2;
      y0 = y1;
      y1 = y2;
    }
    x = x0;
    y = y0;
    g = r0;
    return g;
  }
}

class Solver {
  final long n;
  List<Long> ps;
  ExtendedGcdSolver extendedGcdSolver;

  Solver(long n) {
    this.n = n;
    this.extendedGcdSolver = new ExtendedGcdSolver();
  }

  /*
  private static long extendGcd(long a, long b, long[] x, long[] y) {
    if (b == 0) {
      x[0] = 1;
      y[0] = 0;
      return a;
    }

    long d = extendGcd(b, a % b, y, x);
    y[0] -= a / b * x[0];
    return d;
  }
  */

  private static long mul(long a, long b) {
    double da = a;
    double db = b;
    if (da * db > 1e16) {
      return Long.MAX_VALUE;
    }
    return a * b;
  }

  private long dfs(int index, long a, long b) {
    if (index == ps.size()) {
      // ax + by = 1
      /*
      long[] x = new long[1];
      long[] y = new long[1];
      extendGcd(a, b, x, y);
      */
      long g = extendedGcdSolver.solve(a, b);
      long x = extendedGcdSolver.x;
      long y = extendedGcdSolver.y;
//      System.err.printf("a: %d, b: %d, x: %d, y: %d, g: %d, a * x + b * y: %d\n", a, b, x, y, g, a * x + b * y);
      long v1 = mul(a, Math.abs(x));
      long v2 = mul(b, Math.abs(y));
      long min = Math.min(v1, v2);
      if (min == 0) {
        return Long.MAX_VALUE;
      }
      return min;
    }
    long p = ps.get(index);
    return Math.min(dfs(index + 1, a * p, b), dfs(index + 1, a, p * b));
  }

  public long solve() {
    if (n == 1) {
      return 1;
    }
    long tempN = 2 * n;
    ps = new ArrayList<>();
    for (long v = 2; v * v <= tempN; v++) {
      if (tempN % v != 0) {
        continue;
      }
      long p = 1;
      while (tempN % v == 0) {
        p *= v;
        tempN /= v;
      }
      ps.add(p);
    }
    if (tempN > 1) {
      ps.add(tempN);
    }
    return dfs(0, 1, 1);
  }
}

public class Main {
  private static void execute(ContestReader reader, ContestWriter out) {
    long n = reader.nextLong();
    out.println(new Solver(n).solve());
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    ContestWriter out = new ContestWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

