class Solver {
  final long n;
  List<Long> ps;

  Solver(long n) {
    this.n = n;
  }

  private static long extendGcd(long a, long b, long[] x, long[] y) {
    if (b == 0) {
      x[0] = 1;
      y[0] = 0;
      return a;
    }

    long d = extendGcd(b, a % b, y, x);
    y[0] -= a / b * x[0];
    return d;
  }

  private static long mul(long a, long b) {
    double da = a;
    double db = b;
    if (da * db > 1e16) {
      return Long.MAX_VALUE;
    }
    return a * b;
  }

  private long dfs(int index, long a, long b) {
    if (index == ps.size()) {
      // ax + by = 1
      long[] x = new long[1];
      long[] y = new long[1];
      extendGcd(a, b, x, y);
      long v1 = mul(a, Math.abs(x[0]));
      long v2 = mul(b, Math.abs(y[0]));
//      System.err.printf("a: %d, b: %d, x: %d, y: %d, v1: %d, v2: %d\n", a, b, x[0], y[0], v1, v2);
      long min = Math.min(v1, v2);
      if (min == 0) {
        return Long.MAX_VALUE;
      }
      return min;
    }
    long p = ps.get(index);
    return Math.min(dfs(index + 1, a * p, b), dfs(index + 1, a, p * b));
  }

  public long solve() {
    if (n == 1) {
      return 1;
    }
    long tempN = 2 * n;
    ps = new ArrayList<>();
    for (long v = 2; v * v <= tempN; v++) {
      if (tempN % v != 0) {
        continue;
      }
      long p = 1;
      while (tempN % v == 0) {
        p *= v;
        tempN /= v;
      }
      ps.add(p);
    }
    if (tempN > 1) {
      ps.add(tempN);
    }
    return dfs(0, 1, 1);
  }
