import java.io.InputStream;
import java.util.Arrays;
import java.util.Objects;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongBinaryOperator;
import java.util.function.LongPredicate;
import java.util.function.LongUnaryOperator;

public class Main {
    public static void main(String[] args) throws Exception {
        ExtendedScanner sc = new ExtendedScanner();
        FastPrintStream pw = new FastPrintStream();
        solve(sc, pw);
        sc.close();
        pw.flush();
        pw.close();
    }

    public static void solve(ExtendedScanner sc, FastPrintStream pw) {
        long n = sc.nextLong();
        long min = Long.MAX_VALUE;
        if (n % 2 == 0) {
            n *= 2;
        }
        var f = MathUtil.factorize(n);
        long[] qp = new long[f.size()];
        int idx = 0;
        for (var e : f.entrySet()) {
            long prd = 1;
            long p = e.getKey();
            for (int i = 0; i < e.getValue(); i++) {
                prd *= p;
            }
            qp[idx++] = prd;
        }
        int m = idx;
        for (int i = 0; i < (1 << m); i++) {
            long q1 = 1, q2 = 1;
            for (int j = 0; j < m; j++) {
                if (((i >> j) & 1) == 1) {
                    q1 *= qp[j];
                } else {
                    q2 *= qp[j];
                }
            }
            long[] xyg1 = MathUtil.extGCD(q1, -q2);
            long x1 = xyg1[0];
            long y1 = xyg1[1];
            if (xyg1[2] < 0) {
                x1 *= -1;
                y1 *= -1;
            }
            if (x1 < 0) {
                long mx = (-x1 + q2 - 1) / q2;
                x1 += q2 * mx;
                y1 += q1 * mx;
            }
            if (y1 < 0) {
                long my = (-y1 + q1 - 1) / q1;
                x1 += q2 * my;
                y1 += q1 * my;
            }
            if (x1 == 0 || y1 == 0) {
                x1 += q2;
                y1 += q1;
            }
            min = Math.min(min, y1 * q2);
        }
        pw.println(min);
    }
}


