	static long[] extgcd(long a, long b) {
	    long x0 = 1, x1 = 0;
	    long y0 = 0, y1 = 1;

	    while (b != 0) {
	        long q = a / b;
	        long r = a % b;
	        long x2 = x0 - q * x1;
	        long y2 = y0 - q * y1;

	        a = b; b = r;
	        x0 = x1; x1 = x2;
	        y0 = y1; y1 = y2;
	    }

	    return new long[]{a, x0, y0};
	}

