		long min = linf;
		for(long a = 2; a * a <= n; a ++) {
			if(n % a == 0) {
				long b = n / a;
				if(a % b == 0 || b % a == 0)continue;
				var res = extgcd(a, b);
				if(res[0] != 1)continue;
				min = min(min, min(Math.abs(a * res[1]), Math.abs(b * res[2])));
			}
		}
		if(min == linf) {
			out.println(n-1);
			return;
		}
		out.println(min);
	}	

	static long[] extgcd(long a, long b) {
	    long x0 = 1, x1 = 0;
	    long y0 = 0, y1 = 1;

	    while (b != 0) {
	        long q = a / b;
	        long r = a % b;
	        long x2 = x0 - q * x1;
	        long y2 = y0 - q * y1;

	        a = b; b = r;
	        x0 = x1; x1 = x2;
	        y0 = y1; y1 = y2;
	    }

