    public static long function(long n){
        n*=2;
        long k = n-1;
        for (long i=1;i*i<=n;i++){
            if (n%i==0){
                long a = i;
                long b = n/i;
                long c = b;
                while (c%a!=1&&c%a!=a-1&&c%a!=0)c+=b;
                if (c%a==1){
                    k=Math.min(k,c-1);
                }else if (c%a==a-1){
                    k=Math.min(k,c);
                }
                c=a;
            }
        }
        return k;
    }

