import java.math.BigInteger;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {

        var sc = new Scanner(System.in);

        long n = Long.parseLong(sc.next());

        BigInteger bn = BigInteger.valueOf(n);
        BigInteger ba = BigInteger.valueOf(n);
        long ans = 0L;
        for(int i = 0; i < 100000; i++){
            long low = 0L;
            long high = 1000000000000000000L;

            while(high - low > 1){
                long mid = (low + high) / 2;
                if(ok(mid, ba)){
                    high = mid;
                }else{
                    low = mid;
                }
            }
            BigInteger x = BigInteger.valueOf(high);
            if(x.multiply(x.add(BigInteger.ONE)).divide(BigInteger.TWO).remainder(ba).equals(BigInteger.ZERO)){
                ans = high;
                break;
            }
            ba = ba.add(bn);
        }
        System.out.println(ans);
    }

    static boolean ok(long mid, BigInteger ba){

        BigInteger x = BigInteger.valueOf(mid);
        return x.multiply(x.add(BigInteger.ONE)).divide(BigInteger.TWO).compareTo(ba) >= 0;
    }
}

import java.io.*;
import java.util.*;

class Solver {
  final long n;
  List<Long> ps;

  Solver(long n) {
    this.n = n;
  }

  private static long extendGcd(long a, long b, long[] x, long[] y) {
    if (b == 0) {
      x[0] = 1;
      y[0] = 0;
      return a;
    }

    long d = extendGcd(b, a % b, y, x);
    y[0] -= a / b * x[0];
    return d;
  }

  private static long mul(long a, long b) {
    double da = a;
    double db = b;
    if (da * db > 1e16) {
      return Long.MAX_VALUE;
    }
    return a * b;
  }

  private long dfs(int index, long a, long b) {
    if (index == ps.size()) {
      // ax + by = 1
      long[] x = new long[1];
      long[] y = new long[1];
      extendGcd(a, b, x, y);
      long v1 = mul(a, Math.abs(x[0]));
      long v2 = mul(b, Math.abs(y[0]));
      long min = Math.min(v1, v2);
      if (min == 0) {
        return Long.MAX_VALUE;
      }
      return min;
    }
    long p = ps.get(index);
    return Math.min(dfs(index + 1, a * p, b), dfs(index + 1, a, p * b));
  }

  public long solve() {
    if (n == 1) {
      return 1;
    }
    long tempN = 2 * n;
    ps = new ArrayList<>();
    for (long v = 2; v * v <= tempN; v++) {
      if (tempN % v != 0) {
        continue;
      }
      long p = 1;
      while (tempN % v == 0) {
        p *= v;
        tempN /= v;
      }
      ps.add(p);
    }
    if (tempN > 1) {
      ps.add(tempN);
    }
    return dfs(0, 1, 1);
  }
}

