    static class BSumIsMultiple {
        long ans = 0;
        long[] powFactors;
        LongExtGCDObject extgcd = new LongExtGCDObject();

        public void solve(int testNumber, FastInput in, FastOutput out) {
            long n = in.readLong();
            LongArrayList primeFactors = Factorization.factorizeNumberPrime(n);
            LongArrayList powFactors = new LongArrayList();
            for (long x : primeFactors.toArray()) {
                long pow = 1;
                while (n / pow % x == 0) {
                    pow *= x;
                }
                powFactors.add(pow);
            }
            this.powFactors = powFactors.toArray();

            ans = (long) 1e18;
            dfs(0, 1, 1);
            out.println(ans);
        }

        public void test(long a, long b) {
            if (a % 2 == 0 && b % 2 == 0) {
                return;
            }
            if (a == 1) {
                ans = Math.min(ans, b);
                return;
            }
            if (b == 1) {
                ans = Math.min(ans, a - 1);
                return;
            }
            extgcd.extgcd(a, b);
            long x = extgcd.getX();
            x = DigitUtils.mod(x, b);
            ans = Math.min(ans, DigitUtils.mul(x, a, (long) 1e18) - 1);
        }

        public void dfs(int i, long a, long b) {
            if (i == powFactors.length) {
                test(a * 2, b);
                test(a, b * 2);
                return;
            }
            dfs(i + 1, a * powFactors[i], b);
            dfs(i + 1, a, b * powFactors[i]);
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public long readLong() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            long val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }

