internal partial class Solver {
    public void Run() {
        var n = nl();

        cout.WriteLine(Solve(n));
    }

    private long Solve(long n) {
        long ans = long.MaxValue;
        if (n % 2 == 0) n *= 2;
        foreach (var d in Divisors(n)) {
            var a = d;
            var b = n / d;
            if (ExtendedGcd(a, b, out var x, out var y) == 1) {
                // a * x + b * y = 1
                // a * x + 1 = b * (-y)
                {
                    while (x >= 0 || y <= 0) { x -= b; y += a; }
                    var s = a * Math.Abs(x);
                    var t = b * Math.Abs(y);
                    // s + 1 = t
                    if (s + 1 != t) throw new Exception();
                    ans = Math.Min(ans, s);
                }
            }
        }
        return ans;
    }

    public static List<long> Divisors(long x) {
        var ret = new List<long>();
        for (long i = 1; i * i <= x; i++) {
            if (x % i == 0) {
                ret.Add(i);
                if (i != x / i) {
                    ret.Add(x / i);
                }
            }
        }
        ret.Sort();
        return ret;
    }


    public static long ExtendedGcd(long s, long t, out long x, out long y) {
        if (t == 0) {
            x = 1; y = 0;
            return s;
        } else {
            long sx = 1, sy = 0, tx = 0, ty = 1;
            while (true) {
                var d = s / t;
                var u = s - t * d;
                if (u == 0) break;
                var ux = sx - tx * d;
                var uy = sy - ty * d;
                s = t; sx = tx; sy = ty;
                t = u; tx = ux; ty = uy;
            }
            x = tx; y = ty;
            return t;
        }
    }
}

