namespace FertiLib.Contest.B
{
	static class Program
	{
		public static void Solve(Scanner cin)
		{
			long n = cin.ReadLong();

			var prime = Factorizer.Factorize(n);
			//if(prime.Count == 1)
			//{
			//	if (prime.ContainsKey(2)) Console.WriteLine(2 * n - 1);
			//	else Console.WriteLine(n - 1);
			//	return;
			//}
			var primeList = prime.ToList();

			long ans = long.MaxValue;
			var anskouho = new List<long>();
			for (int i = 0; i < 1 << prime.Count; i++)
			{
				var r = new List<long>();
				var m = new List<long>();
				for (int j = 0; j < prime.Count; j++)
				{
					var p = primeList[j].Key;
					var pow = primeList[j].Value;
					if (p == 2)
					{
						m.Add(Pow(p, pow + 1));
					}
					else
					{
						m.Add(Pow(p, pow));
					}
					if ((i & (1 << j)) > 0)
					{
						//k = 0 mod p ^ pow
						r.Add(0);
					}
					else
					{
						//k = -1 mod p ^ pow
						r.Add(m[j] - 1);
					}
				}
				var x = Garner(r, m);
				if (x == 0) x += n;
				anskouho.Add(x);
				if ((x * (x + 1) / 2) % n == 0) Chmin(ref ans, x);
			}

			Console.WriteLine(ans);
		}

		public static long Garner(List<long> r, List<long> m)
		{
			int n = r.Count;
			long mProd = 1;
			long x = r[0] % m[0];
			for (int i = 1; i < n; i++)
			{
				mProd *= m[i - 1];
				long t = ((r[i] - x) * InvMod(mProd, m[i])) % m[i];
				if (t < 0) t += m[i];
				x += t * mProd;
			}
			return x;
		}

		public static long InvMod(long a, long m)
		{
			long x = 0;
			long y = 0;
			long d = ExtGcd(a, m, ref x, ref y);
			if(d != 1)
			{
				return -1;
			}
			x %= m;
			if (x < 0) x += m;
			return x;
		}

		public static long ExtGcd(long a, long b, ref long x, ref long y)
		{
			if(b == 0)
			{
				x = 1;
				y = 0;
				return a;
			}
			long x2 = 0;
			long y2 = 0;
			long d = ExtGcd(b, a % b, ref x2, ref y2);
			x = y2;
			y = x2 - (a / b) * y2;
			return d;
		}

		public static long Pow(long x, long pow)
		{
			long ret = 1;
			for (long i = 1; i <= pow; i *= 2, x *= x)
			{
				if (pow / i % 2 == 1) ret *= x;
			}
			return ret;
		}

