	public static long Legendre(long a, long p) {
		long ret = Pow(a, (p-1)/2, p);
		if (ret == p-1) ret = -1;
		return ret;
	}

	// Tonelli–Shanks algorithm　　calculate R such that R^2 = n (mod p)  p is a prime
	// See http://en.wikipedia.org/wiki/Tonelli%E2%80%93Shanks_algorithm
	public static long ModSqrt(long n, long p) {
		if(p <2) return -1;
		if(p==2) return n;
		long r = Legendre(n, p);
		if(r!=1) return r;

		// step 1
		long Q = p-1;
		long S = 0;
		while ((Q & 1) == 0) {
			++S;
			Q >>= 1;
		}
		if (S == 1) return Pow(n, (p+1)/4, p);

		// step 2
		long z = 1;
		var rnd = new System.Random();
		int rm = int.MaxValue <= p ? int.MaxValue : (int)p+1;
	    while (Legendre(z, p) != -1)  z = rnd.Next(rm);
		long c = Pow(z, Q, p);

		// step 3
		long R = Pow(n, (Q+1)/2, p);
		long t = Pow(n, Q, p);
		long M = S;

		// step 4
		while (t != 1) {
			long i;
			long t2 = t;
			for (i = 1; i < M; i++) {
				t2 = t2 * t2 % p;
				if (t2 == 1) break;
			}
			long b = Pow(c, 1L<<(int)(M-i-1), p);
			R = R * b % p;
			t = (t * b % p) * b % p;
			c = b * b % p;
			M = i;
		}

		return R;
	}

	public static long Garner(long[] b, long[] m, bool needpre, long MOD=9223372036854775783L) {
		if(needpre){
			long lcm;
			if((lcm = PreGarner(ref b, ref m, MOD))==-1) return -1;
		}
		var q = new long[m.Length+1];
		Array.Copy(m,q,m.Length);
		q[q.Length-1] = MOD; // 番兵
		long[] coeffs = Enumerable.Repeat(1L,q.Length).ToArray();
		long[] constants = Enumerable.Repeat(0L,q.Length).ToArray();
		for (int k = 0; k < b.Length; ++k) {
			long t = (b[k] - constants[k]) * ModInv(coeffs[k], q[k]) % q[k];
			t += (t<0)?q[k]:0;
			for (int i = k+1; i < q.Length; ++i) {
				constants[i] = (constants[i] + t * coeffs[i]) % q[i];
				coeffs[i] = (coeffs[i] * q[k]) % q[i];
			}
		}
		return constants[constants.Length-1];
	}
	// Garner のアルゴリズムの前処理 mが互いに素ではない場合
	public static long PreGarner(ref long[] b, ref long[] m, long MOD=9223372036854775783L) {
		for (int i = 0; i < b.Length; ++i) {
			for (int j = 0; j < i; ++j) {
				long g = GCD(m[i], m[j]);
				// これを満たさなければ解はない
				if ((b[i] - b[j]) % g != 0) return -1;
				// s = m[i], t = m[j] を仮想的に素因数分解して s = p^k ... q^l ..., t = q^m ... r^n ... となったときに
				m[i] /= g; // p については i の方が大きかったものについての j との差分、と q
				m[j] /= g; // p については j の方が大きかったものについての i との差分、と r
				// 残る g を i と j に振り分ける (i の方が指数大きかった素因子 p の分は最終的に gi に、j の方が指数大きかった素因子 p の分は最終的に gj に)
				// ひとまず j 側にある p については gj のみに行くようにする
				long gi = GCD(m[i], g), gj = g/gi;
				// 本来 i 側に行くべき p で gj 側にあるものを gi 側に寄せていく
				do {
					g = GCD(gi, gj);
					gi *= g; gj /= g;
				} while (g != 1);
				// i 側と j 側に戻していく
				m[i] *= gi; m[j] *= gj;
				// m[i] と m[j] が元より小さくなったのに合わせて余りも計算し直しておく
				b[i] %= m[i]; b[j] %= m[j];
			}
		}
		var bb = new List<long>();
		var mm = new List<long>();
		for (int i = 0; i < b.Length; i++)
		{
			if(1<m[i]){
				bb.Add(b[i]);
				mm.Add(m[i]);
			}
		}
		b = bb.ToArray();
		m = mm.ToArray();
		long lcm = 1;
		for (int i = 0; i < b.Length; ++i) lcm = (lcm * m[i]) % MOD;
		return lcm;
	}

	public static long[] PrimeFactor(long n) {
		var ret = new List<long>();
		if (n < 2) return ret.ToArray();
		while ((n & 1) == 0) {
			ret.Add(2);
			n >>= 1;
		}
		while ((n % 3) == 0) {
			ret.Add(3);
			n /= 3;
		}
		long sqi = Convert.ToInt64(Math.Sqrt(n));
		while(sqi*sqi<=n) sqi++;
		for (long i = 5, f = 2; i < sqi; i += f, f ^= 6) {
			while ((n % i) == 0) {
				ret.Add(i);
				n /= i;
			}
			if(n==1) break;
		}
		if(1<n) ret.Add(n);
		return ret.ToArray();
	}

	public static long Pow(long x, long n, long m=long.MaxValue) {
		long ret = 1;
		while (true) {
			if ((n & 1) == 1) ret = (ret * x) % m;
			if((n >>= 1)<=0) break;
			x = (x * x) % m;
		}
		return ret;
	}

	public static long GCD(long a, long b) {
		while (b != 0) { var t = b; b = a % b; a = t; }
		return a;
	}
	public static long GCD(params long[] z) { long v = z[0]; for(int i=1;i<z.Length;i++) v = GCD(v, z[i]); return v; }
	public static long LCM(long a, long b) => checked(a / GCD(a, b) * b);
	public static long LCM(params long[] z) { long v = z[0]; try{ for(int i=1;i<z.Length;i++) v = LCM(v, z[i]); }catch{ v=long.MaxValue; } return v; }


	// 拡張ユークリッドの互除法   返り値: a と b の最大公約数  ax + by = gcd(a, b) を満たす (x, y) が格納される
	public static long EGCD(long a, long b, out long x, out long y) {
		x = 0; y = 1;
		long u = 1 , v = 0, gcd = 0;
		while (a != 0) {
			var q = b / a; var r = b % a; var m = x - u * q; var n = y - v * q;
			b = a; a = r; x = u; y = v; u = m; v = n; gcd = b;
		}
		return gcd;
	}

	// 逆元
	public static long ModInv(long value, long modulo) {
		long x, y;
		if (1 != EGCD(value, modulo, out x, out y)) throw new ArgumentException("Invalid modulo", "modulo");
		return (x < 0)?x+modulo:x;
	}

	public static KeyValuePair<T,long>[] ElementCount<T>(IEnumerable<T> a, long order=0) where T : IComparable<T> {
		var d = new Dictionary<T, long>();
		foreach (var e in a) {
			if(!d.ContainsKey(e)) d[e] = 0;
			d[e]++;
		}
		var r = d.ToArray();
		switch(order) {
			case  1: Array.Sort(r,(x,y)=>(x.Key.CompareTo(y.Key))); break;
			case -1: Array.Sort(r,(x,y)=>(y.Key.CompareTo(x.Key))); break;
			case  2: Array.Sort(r,(x,y)=>(x.Value.CompareTo(y.Value))); break;
			case -2: Array.Sort(r,(x,y)=>(y.Value.CompareTo(x.Value))); break;
			case  3: Array.Sort(r,(x,y)=>(x.Value!=y.Value?x.Value.CompareTo(y.Value):x.Key.CompareTo(y.Key))); break;
			case  4: Array.Sort(r,(x,y)=>(x.Value!=y.Value?x.Value.CompareTo(y.Value):y.Key.CompareTo(x.Key))); break;
			case -3: Array.Sort(r,(x,y)=>(x.Value!=y.Value?y.Value.CompareTo(x.Value):x.Key.CompareTo(y.Key))); break;
			case -4: Array.Sort(r,(x,y)=>(x.Value!=y.Value?y.Value.CompareTo(x.Value):y.Key.CompareTo(x.Key))); break;
			default: break;
		}
		return r;
	}



