	public static long Garner(long[] b, long[] m, bool needpre, long MOD=9223372036854775783L) {
		if(needpre){
			long lcm;
			if((lcm = PreGarner(ref b, ref m, MOD))==-1) return -1;
		}
		var q = new long[m.Length+1];
		Array.Copy(m,q,m.Length);
		q[q.Length-1] = MOD; // 番兵
		long[] coeffs = Enumerable.Repeat(1L,q.Length).ToArray();
		long[] constants = Enumerable.Repeat(0L,q.Length).ToArray();
		for (int k = 0; k < b.Length; ++k) {
			long t = (b[k] - constants[k]) * ModInv(coeffs[k], q[k]) % q[k];
			t += (t<0)?q[k]:0;
			for (int i = k+1; i < q.Length; ++i) {
				constants[i] = (constants[i] + t * coeffs[i]) % q[i];
				coeffs[i] = (coeffs[i] * q[k]) % q[i];
			}
		}
		return constants[constants.Length-1];
	}
	// Garner のアルゴリズムの前処理 mが互いに素ではない場合
	public static long PreGarner(ref long[] b, ref long[] m, long MOD=9223372036854775783L) {
		for (int i = 0; i < b.Length; ++i) {
			for (int j = 0; j < i; ++j) {
				long g = GCD(m[i], m[j]);
				// これを満たさなければ解はない
				if ((b[i] - b[j]) % g != 0) return -1;
				// s = m[i], t = m[j] を仮想的に素因数分解して s = p^k ... q^l ..., t = q^m ... r^n ... となったときに
				m[i] /= g; // p については i の方が大きかったものについての j との差分、と q
				m[j] /= g; // p については j の方が大きかったものについての i との差分、と r
				// 残る g を i と j に振り分ける (i の方が指数大きかった素因子 p の分は最終的に gi に、j の方が指数大きかった素因子 p の分は最終的に gj に)
				// ひとまず j 側にある p については gj のみに行くようにする
				long gi = GCD(m[i], g), gj = g/gi;
				// 本来 i 側に行くべき p で gj 側にあるものを gi 側に寄せていく
				do {
					g = GCD(gi, gj);
					gi *= g; gj /= g;
				} while (g != 1);
				// i 側と j 側に戻していく
				m[i] *= gi; m[j] *= gj;
				// m[i] と m[j] が元より小さくなったのに合わせて余りも計算し直しておく
				b[i] %= m[i]; b[j] %= m[j];
			}
		}
		var bb = new List<long>();
		var mm = new List<long>();
		for (int i = 0; i < b.Length; i++)
		{
			if(1<m[i]){
				bb.Add(b[i]);
				mm.Add(m[i]);
			}
		}
		b = bb.ToArray();
		m = mm.ToArray();
		long lcm = 1;
		for (int i = 0; i < b.Length; ++i) lcm = (lcm * m[i]) % MOD;
		return lcm;
	}

	public static long Pow(long x, long n, long m=long.MaxValue) {
		long ret = 1;
		while (true) {
			if ((n & 1) == 1) ret = (ret * x) % m;
			if((n >>= 1)<=0) break;
			x = (x * x) % m;
		}
		return ret;
	}

	public static long GCD(long a, long b) {
		while (b != 0) { var t = b; b = a % b; a = t; }
		return a;
	}
	public static long GCD(params long[] z) { long v = z[0]; for(int i=1;i<z.Length;i++) v = GCD(v, z[i]); return v; }
	public static long LCM(long a, long b) => checked(a / GCD(a, b) * b);
	public static long LCM(params long[] z) { long v = z[0]; try{ for(int i=1;i<z.Length;i++) v = LCM(v, z[i]); }catch{ v=long.MaxValue; } return v; }


	// 拡張ユークリッドの互除法   返り値: a と b の最大公約数  ax + by = gcd(a, b) を満たす (x, y) が格納される
	public static long EGCD(long a, long b, out long x, out long y) {
		x = 0; y = 1;
		long u = 1 , v = 0, gcd = 0;
		while (a != 0) {
			var q = b / a; var r = b % a; var m = x - u * q; var n = y - v * q;
			b = a; a = r; x = u; y = v; u = m; v = n; gcd = b;
		}
		return gcd;
	}

	// 逆元
	public static long ModInv(long value, long modulo) {
		long x, y;
		if (1 != EGCD(value, modulo, out x, out y)) throw new ArgumentException("Invalid modulo", "modulo");
		return (x < 0)?x+modulo:x;
	}

	public static long[] Divisor(long n) {
		var ret1 = new List<long>();
		var ret2 = new List<long>();
		long i2;
		for(long i = 1; (i2 = i*i) <= n; i++) {
			if(n % i == 0) {
				ret1.Add(i);
				if(i2 != n) ret2.Add(n / i);
			}
		}
		long[] ret = new long[ret1.Count+ret2.Count];
		for (int i = 0; i < ret1.Count; i++) ret[i] = ret1[i];
		for (int i = ret2.Count-1; 0 <= i; i--) ret[ret1.Count+ret2.Count-i-1] = ret2[i];
		return ret;
	}




