public class Solver
{
    private const int SIEVE_SIZE = 4000000;
    private readonly bool[] isComposite = new bool[SIEVE_SIZE + 1];
    private readonly IList<int> primes = new List<int>();
    void Sieve()
    {
        for (int i = 2; i * i <= SIEVE_SIZE; i++)
            if (!isComposite[i])
                for (int j = i * i; j <= SIEVE_SIZE; j += i)
                    isComposite[j] = true;
        for (int i = 2; i <= SIEVE_SIZE; i++)
            if (!isComposite[i])
                primes.Add(i);
    }

    long Gcd(long a, long b, out long x, out long y)
    {
        if (a == 0)
        {
            x = 0;
            y = 1;
            return b;
        }
        long x1, y1;
        long d = Gcd(b % a, a, out x1, out y1);
        x = y1 - (b / a) * x1;
        y = x1;
        return d;
    }

    void FindAnySolution(long a, long b, out long x0, out long y0)
    {
        Gcd(Math.Abs(a), Math.Abs(b), out x0, out y0);
        if (a < 0) 
            x0 *= -1;
        if (b < 0)
            y0 *= -1;
    }

    int Brute(long n)
    {
        for (int i = 1; ; i++)
            if (i * (i + 1) / 2 % n == 0)
                return i;
    }

    long Fun(long n)
    {
        long o = n;
        if (n == 1)
            return 1;
        if (n == 2)
            return 3;
        var f = new List<long>();
        for (int i = 0; 1L * primes[i] * primes[i] <= n; i++)
            if (n % primes[i] == 0)
            {
                long v = 1;
                while (n % primes[i] == 0)
                {
                    v *= primes[i];
                    n /= primes[i];
                }
                if (primes[i] == 2)
                    v *= 2;
                f.Add(v);
            }
        if (n > 1)
            f.Add(n);

        if (f.Count == 1)
            return f[0] - 1;

        long ret = long.MaxValue;
        for (int mask = 1; mask < 1 << f.Count; mask++)
        {
            long u = 1, v = 1;
            for (int i = 0; i < f.Count; i++)
                if ((mask >> i & 1) == 1)
                    u *= f[i];
                else
                    v *= f[i];
            //if ((u - 1) % v == 0)
            //    ret = Math.Min(ret, u - 1);
            //if ((u + 1) % v == 0)
            //    ret = Math.Min(ret, u);
            long x, y;
            FindAnySolution(-u, v, out x, out y);
            if (x <= 0 || y <= 0)
            {
                x += v;
                y += u;
            }
            ret = Math.Min(ret, u * x);
        }

        return ret;
    }

    public void Solve()
    {
        Sieve();

        //for (int i = 2; i < 1000; i++)
        //{
        //    int x = Brute(i);
        //    long y = Fun(i);
        //    if (x != y)
        //        Write(i, x, y);
        //}

        long n = ReadLong();
        Write(Fun(n));
    }

