class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        long n = sc.Long * 2;
        var prs = new List<long>();
        for (long i = 2; i * i <= n; i++)
        {
            if (n % i == 0) {
                long r = 1;
                while (n % i == 0) {
                    n /= i;
                    r *= i;
                }
                prs.Add(r);
            }
        }
        if (n > 1) {
            prs.Add(n);
        }
        long ans = LM;
        int m = prs.Count;
        for (int i = 0; i < (1 << m); i++)
        {
            long a = 1, b = 1;
            for (int j = 0; j < m; j++)
            {
                if (((i >> j) & 1) == 1) {
                    a *= prs[j];
                }
                else {
                    b *= prs[j];
                }
            }
            // DBG(a, b);
            long x, y;
            MyMath.extgcd(a, b, out x, out y);
            // DBG(x, y);
            {
                long xx = x;
                long yy = y;
                for (int j = 0; j < 5; j++)
                {
                    if (Math.Abs(xx) * a + 1 == Math.Abs(yy) * b) {
                        if (Math.Abs(xx) * a != 0) {
                            ans = Math.Min(ans, Math.Abs(xx) * a);
                        }
                    }
                    if (Math.Abs(xx) * a == Math.Abs(yy) * b + 1) {
                        if (Math.Abs(yy) * b != 0) {
                            ans = Math.Min(ans, Math.Abs(yy) * b);
                        }
                    }
                    xx += b;
                    yy -= a;
                }
            }
            {
                long xx = x;
                long yy = y;
                for (int j = 0; j < 5; j++)
                {
                    if (Math.Abs(xx) * a + 1 == Math.Abs(yy) * b) {
                        if (Math.Abs(xx) * a != 0) {
                            ans = Math.Min(ans, Math.Abs(xx) * a);
                        }
                    }
                    if (Math.Abs(xx) * a == Math.Abs(yy) * b + 1) {
                        if (Math.Abs(yy) * b != 0) {
                            ans = Math.Min(ans, Math.Abs(yy) * b);
                        }
                    }
                    xx -= b;
                    yy += a;
                }
            }
        }
        Prt(ans);
    }
}

class pair<T, U> : IComparable<pair<T, U>> {
    public T v1;
    public U v2;
    public pair() : this(default(T), default(U)) {}
    public pair(T v1, U v2) { this.v1 = v1; this.v2 = v2; }
    public int CompareTo(pair<T, U> a) {
        int c = Comparer<T>.Default.Compare(v1, a.v1);
        return c != 0 ? c : Comparer<U>.Default.Compare(v2, a.v2);
    }
    public override string ToString() => v1 + " " + v2;
    public void Deconstruct(out T a, out U b) { a = v1; b = v2; }
}
static class util {
    public static readonly int M = 1000000007;
    // public static readonly int M = 998244353;
    public static readonly long LM = 1L << 60;
