public class Pf{
	public Dictionary<long,int> hs=new Dictionary<long,int>();
	public Pf(long n){
		if(n%2==0){
			int p=0;
			while((n&1)==0){n>>=1;p++;}
			hs.Add(2,p);
		}
		var q=(int)Sqrt(n)+1;
		for(int i=3;n!=1&&i<q;i+=2){
			if(n%i==0){
				int p=0;
				while(n%i==0){n/=i;p++;}
				q=(int)Sqrt(n)+1;
				hs.Add(i,p);
			}
		}
		if(n!=1){hs.Add(n,1);}
	}
	public void Get(Action<long,int> f){
		foreach(var e in hs){f(e.Key,e.Value);}
	}
}
