		for(int i=2;i<M;i++) isPrime[i] = true;
		for(int i=2;i<M;i++){
			if(!isPrime[i]) continue;
			for(int j=i+i;j<M;j+=i) isPrime[j] = false;
		}

		List<long> L = new List<long>();
		for(long i=2;i*i<=M;i++){
			if(N % i == 0){
				L.Add(i);
				if(N / i != i) L.Add(N / i);
			}
		}

		long n = N;
		for(int i=2;i<M;i++){
			if(!isPrime[i]) continue;
			while(n % i == 0) n /= i;
		}

		List<long> P = new List<long>();
		if(n > 1){
			if(MyMath.MillerRabinTest(n)){
				P.Add(n);
			} else {
				long l = 0, r = (long)4e7;
				while(r - l > 1){
					var c = (l + r) / 2;
					if(c * c < n){
						l = c;
					} else {
						r = c;
					}
				}

				if(r * r == n){
					P.Add(r);
					P.Add(r);
				} else {
					P = Rho(n).Select(n => (long) n).ToList();
				}
			}
		}

		P.Add(1);
		P.Add(N);

		var hs = new HashSet<BI>();
		for(BI v = 1; v <= 2; v++){
			foreach(var nn in L){
				foreach(var p in P){
					BI k = v * nn * p;
					if((k * (k + 1) / 2 ) % (BI)N == 0) hs.Add(k);
					if((k * (k - 1) / 2 ) % (BI)N == 0) hs.Add(k-1);
				}
			}
		}
		Console.WriteLine(hs.ToArray().Min());

	}
