	BI gcd(BI a, BI b){ return a == 0 ? b : gcd(b % a, a);}
	List<BI> Rho(BI n){
		int[] seed = new int[]{3,5,7,11,13,17};
		var hs = new HashSet<BI>();
		foreach(var s in seed){
			BI x = 2, y = 2, d = 1;
			Func<BI,BI> f = x => ((x * x)+ s) % n;
			while(d == 1){
				x = f(x);
				y = f(f(y));
				d = gcd(BI.Abs(x - y), n);
			}
			if(d == n) continue;
			if(n % d == 0){
				hs.Add(d); hs.Add(n / d);
			}
		}
		return hs.ToList();

	}




