class MyMath{

	public static bool IsPrime(BI x){
		if(x==2)return true;
		if((x==1) || (x&1)==0)return false;
		if(x<(BI)1e12){
			for(BI t=2;t*t<=x;t++){
				if(x%t==0)return false;
			}
			return true;
		}
		return MillerRabinTest(x);
	}

	public static bool MillerRabinTest(BI n){
		int rep=20;
		BI d=n-1;
		// (n-1)=2^s*d
		while((d&1)==0)d>>=1;

		var rnd=new Xor128();
		BI a=1+((BI)rnd.Next())%(n-2);

		while(rep>0){
			rep--;
			a=1+((BI)rnd.Next()*a)%(n-2);
			BI t=d;
			BI y=ModPowBI(a,t,n);
			while(t!=(n-1) && y!=1 && y!=n-1){
				y=y*y%n;
				t<<=1;
			}
			if(y!=(n-1) && (t&1)==0)return false;
		}
		return true;
	}

	static BI ModPowBI(BI a,BI t,BI mod){
		BI ret=1;
		while(t>0){
			if((t&1)==1){ret*=a;ret%=mod;};
			a=a*a;a%=mod;
			t>>=1;
		}
		return ret;
	}

}


class Xor128{
	uint x = 123456789;
	uint y = 362436069;
	uint z = 521288629;
	uint w = 88675123; 
	uint t;

	public Xor128(){
	}

	public Xor128(uint seed){
		z ^= seed;
		z ^= z >> 21; z ^= z << 35; z ^= z >> 4;
	}


	public uint Next(){
		t = x ^ (x << 11);
		x = y; y = z; z = w;
		return w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
	}
	public int Next(int ul){
		return NextI(0,ul-1);
	}
	public int NextI(int from,int to){
		int mod=to-from+1;
		int ret=(int)(Next()%mod);
		return ret+from;
	}
}

