	public void Solve(bool assert = false){
		List<long> L = new List<long>();
		long N2 = N * 2;
		for(long x=1;x*x<=N2;x++){
			if(N2 % x == 0){
				L.Add(x);
				if(N2 / x != x) L.Add(N2 / x);
			}
		}

		//Console.WriteLine(String.Join(" ",L));

		long ans = (long) long.MaxValue;
		foreach(var p in L){
			long q = N2 / p;
			// k includes p, (k + 1) includes q;
			// <=> k = 0 mod p, (k + 1) = 0 mod q;
			if(gcd(p, q) != 1) continue;
			var k = MyMath.CRT(p, 0, q, q - 1);
			while(k <= 0) k += N2;
			//Console.WriteLine("{0} {1} {2}",p, q, k);
			ans = Math.Min(ans, (long) k);
		}
		if(!assert){
			Console.WriteLine(ans);
		} else {
			long kk = naive();
			if(kk != ans){
				Console.WriteLine("naive: {0}, ans: {1}", kk, ans);
				throw new Exception("aaa");
			}
		}
	}

