class MyMath{
	public static BI CRT(BI m1,BI a,BI m2,BI b){
		// ChineseReminderTheorem
		// m1,m2:coprime
		// x%m1==a,x%m2==b => return x%m1m2
		//
		// ∃u,v  s.t.  u*m1+v*m2==1;
		//   return x=(b*u*m1+a*v*m2)%(m1m2);
		BI u = 0, v = 0, c = 0;
		ExtGCD(m1, m2, ref u, ref v, ref c);
		BI mm = m1 * m2;
		b *= u; b %= mm; b *= m1; b %= mm;
		a *= v; a %= mm; a *= m2; a %= mm;
		return (a + b) % mm;
	}


	public static void ExtGCD(BI x,BI y,ref BI a,ref BI b,ref BI c){
		BI r0 = x, r1 = y, a0 = 1, a1 = 0, b0 = 0, b1 = 1;
		BI q1, r2, a2, b2;
		while(r1 > 0){
			q1 = r0 / r1;
			r2 = r0 % r1;
			a2 = a0 - q1 * a1;
			b2 = b0 - q1 * b1;
			r0 = r1; r1=r2;
			a0 = a1; a1=a2;
			b0 = b1; b1=b2;
		}
		c = r0;
		a = a0;
		b = b0;
	}
}

