	public class Program
	{
		static void Main()
		{
			using var cin = new Scanner();
			long n = cin.Long();
			if (n == 1) {
				Console.WriteLine(1);
				return;
			}

			var temp = GetPrimeFactors(n);
			bool is2 = temp.ContainsKey(2);
			if (is2 == false) {
				//temp.Add(2, 1);
			}

			var divs = GetDivisors(n);

			bool Check(long ll, long rr)
			{
				if (Math.Abs(ll - rr) != 1) {
					return false;
				}

				BigInteger big = ll;
				big *= rr;
				if (big % 2 == 0 && big / 2 % n == 0) {
					return true;
				} else {
					return false;
				}
			}

			long ans = n % 2 == 0 ? n * 2 - 1 : n - 1;
			long left = 1;
			long right = n;
			for (int i = 0; i < divs.Count; i++) {
				left = divs[i];
				right = n / divs[i];
				if (right < left) {
					continue;
				}

				var gcd = GCD(left, right);
				if (gcd != 1 && gcd != 2) {
					continue;
				}

				long ll = left;
				long rr = right;
				while (rr >= 0 && ll >= 0 && rr <= n && ll <= n && rr <= ans && ll <= ans) {
					if (ll > rr) {
						long mul = (ll - rr) / right;
						rr += mul * right;
						if (Check(ll, rr)) {
							break;
						}

						rr += right;
					} else {
						long mul = (rr - ll) / left;
						ll += mul * left;
						if (Check(ll, rr)) {
							break;
						}

						ll += left;
					}

					if (Check(ll, rr)) {
						break;
					}
				}

				if (ll >= 0
					&& rr >= 0
					&& rr <= n 
					&& ll <= n
					&& Check(ll, rr)) {
					long min = Math.Min(ll, rr);
					ans = Math.Min(ans, min);
				}
			}

			Console.WriteLine(ans);
		}

		public static long GCD(long a, long b)
		{
			if (b == 0) {
				return a;
			}

			return GCD(b, a % b);
		}

		public static List<long> GetDivisors(long value)
		{
			long max = (long)Math.Ceiling(Math.Sqrt(value));
			var divisors = new List<long>();
			for (int i = 1; i <= max; i++) {
				if (value % i == 0) {
					divisors.Add(i);
					if (i != value / i) {
						divisors.Add(value / i);
					}
				}
			}

			divisors.Sort();
			return divisors;
		}

		public static Dictionary<long, long> GetPrimeFactors(long value)
		{
			var factors = new Dictionary<long, long>();
			for (long i = 2; i * i <= value; ++i) {
				while (value % i == 0) {
					if (factors.ContainsKey(i) == false) {
						factors[i] = 1;
					} else {
						factors[i] += 1;
					}

					value /= i;
				}
			}

			if (value != 1) {
				factors[value] = 1;
			}

			return factors;
		}
	}

