function exgcd(x,y){
  var a0 = 1n, a1 = 0n, b0 = 0n, b1 = 1n;
  x = BigInt(x), y = BigInt(y);
  while(y){
    var q1 = x / y;
    var r2 = x % y;
    var a2 = a0 - q1*a1;
    var b2 = b0 - q1*b1
    x = y, y = r2;
    a0 = a1, a1 = a2;
    b0 = b1, b1 = b2;
  }
  return [Number(a0),Number(b0),x];
}

