func main() {
	fp := os.Stdin
	wfp := os.Stdout
	extra := 0
	if os.Getenv("I") == "IronMan" {
		fp, _ = os.Open(os.Getenv("END_GAME"))
		extra = 100
	}
	scanner := bufio.NewScanner(fp)
	configure(scanner)
	writer := bufio.NewWriter(wfp)
	defer func() {
		r := recover()
		if r != nil {
			fmt.Fprintln(writer, r)
		}
		writer.Flush()
	}()
	solve(scanner, writer)
	for i := 0; i < extra; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
}
func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	if n == 1 {
		fmt.Fprintln(writer, 1)
		return
	}
	dd := make([]int, 0)
	for i := 2; i*i < n+1; i++ {
		if n%i == 0 {
			dd = append(dd, i)
			if i == n/i {
				continue
			}
			dd = append(dd, n/i)
		}
	}
	dd = append(dd, 1)
	dd = append(dd, n)
	sort.Ints(dd)
	n <<= 1
	var ans int = math.MaxInt64
	for i := 0; i < len(dd); i++ {
		for j := 0; j < i; j++ {
			if gcd(dd[i], dd[j]) != 1 {
				continue
			}
			x, y := eucrid(dd[i], dd[j])
			if x == 0 || y == 0 {
				continue
			}
			if abs(x*dd[i])*abs(y*dd[j]) < n {
				continue
			}
			if abs(x*dd[i])*abs(y*dd[j])%n != 0 {
				continue
			}
			ans = min(min(abs(y*dd[j]), abs(x*dd[i])), ans)
		}
	}
	if ans == math.MaxInt64 {
		if n>>1&1 == 0 {
			fmt.Fprintln(writer, n-1)
			return
		}
		fmt.Fprintln(writer, n>>1-1)
		return
	}
	fmt.Fprintln(writer, ans)
}
func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
}
func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
func eucrid(a, b int) (int, int) {
	if b == 0 {
		return 1, 0
	}
	x, y := eucrid(b, a%b)
	return y, x - a/b*y
}
func gcd(m, n int) int {
	if n == 0 {
		return m
	}
	return gcd(n, m%n)
}

