func factorize(n int) map[int]int {
	res := map[int]int{}
	for i := 2; i*i <= n; i++ {
		for n%i == 0 {
			res[i]++
			n /= i
		}
	}
	if n != 1 {
		res[n] = 1
	}
	return res
}

func extgcd(a, b int, x, y *int) int {
	if b == 0 {
		*x, *y = 1, 0
		return a
	}
	d := extgcd(b, a%b, y, x)
	*y -= a / b * (*x)
	return d
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

