def fac(n, try_small_factor = True):
    """
    引数 n の素因数分解をして、素因数を昇順に格納したリストを返す。
    ex. fac_small(60) == [2, 2, 3, 5]
    計算量は O(n ^ 1/4) 程度。
    """
    if n == 1:
        return []
    if is_prime(n):
        return [n]

    ret = []
    if try_small_factor:
        for p in prime_numbers_200:
            while n % p == 0:
                ret.append(p)
                n //= p
            if n == 1:
                return ret

    while n != 1 and not is_prime(n):
        f = find_factor(n)
        if is_prime(f):
            while n % f == 0:
                ret.append(f)
                n //= f
        elif is_prime(n // f):
            ret.append(n // f)
            n = f
        else:
            return sorted(ret + fac(f, False) + fac(n // f, False))

    if n == 1:
        return sorted(ret)
    else:
        ret.append(n)
        return sorted(ret)


