fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let mut p = vec![];
    let n: i128 = sc.read();

    let mut t = n * 2;
    for x in 2.. {
        if x * x > n {
            break;
        }
        let mut cur = 1;
        while t % x == 0 {
            cur *= x;
            t /= x;
        }
        if cur > 1 {
            p.push(cur);
        }
    }
    if t > 1 {
        p.push(t);
    }

    let p_len = p.len();
    let mut ans = if (n * (n + 1) / 2) % n == 0 { n } else { 2 * n };
    for mask in 0..(1 << p_len) {
        let mut a = 1;
        let mut b = 1;
        for i in 0..p_len {
            if mask & (1 << i) != 0 {
                a *= p[i];
            } else {
                b *= p[i];
            }
        }

        if a == 1 || b == 1 {
            continue;
        }

        let mut x = 0;
        let mut y = 0;
        let g = ext_gcd(a, b, &mut x, &mut y);
        assert_eq!(g, 1);
        assert_eq!(a * x + b * y, 1);
        let k = min((a * x).abs(), (b * y).abs());

        let z = k * (k + 1) / 2;
        assert_eq!(z % n, 0);
        ans = min(ans, k);
    }

    println!("{}", ans);
}

