fn solve(n: i128) -> i128 {
    let mut c = vec![];
    for i in 1.. {
        if i * i > n {
            break;
        }
        if (2 * n) % i == 0 {
            let j = (2 * n) / i;
            c.push((i, j));
        }
    }

    let mut ans = 2 * n;
    for (x, y) in c {
        if y > 1 {
            let m = vec![x, y];
            let b = vec![0, y - 1];
            if let Some((k, _)) = chinese_remainder_theorem(&b, &m) {
                assert_eq!(k % x, 0);
                assert_eq!(k % y, y - 1);
                assert_eq!((k * (k + 1) / 2) % n, 0);
                ans = min(ans, k);
            }
        }

        let (y, x) = (x, y);
        if y > 1 {
            let m = vec![x, y];
            let b = vec![0, y - 1];
            if let Some((k, _)) = chinese_remainder_theorem(&b, &m) {
                assert_eq!(k % x, 0);
                assert_eq!(k % y, y - 1);
                assert_eq!((k * (k + 1) / 2) % n, 0);
                ans = min(ans, k);
            }
        }
    }
    ans
}

pub fn extended_gcd(a: i128, b: i128, p: &mut i128, q: &mut i128) -> i128 {
    if b == 0 {
        *p = 1;
        *q = 0;
        a
    } else {
        let d = extended_gcd(b, a % b, q, p);
        *q -= a / b * *p;
        d
    }
}

pub fn chinese_remainder_theorem(b: &[i128], modulo: &[i128]) -> Option<(i128, i128)> {
    let (mut result, mut m) = (0, 1);
    for i in 0..b.len() {
        let (mut p, mut q) = (0, 0);
        let d = extended_gcd(m, modulo[i], &mut p, &mut q);
        if (b[i] - result) % d != 0 {
            return None;
        }
        let tmp = ((b[i] - result) / d * p) % (modulo[i] / d);
        result += m * tmp;
        m *= modulo[i] / d;
    }
    Some(((result % m + m) % m, m))
}

