            let b = m as i64 / a;

            let mut ext = a.extended_gcd(&b);
            if ext.gcd != 1 {
                return None;
            }
            if ext.x >= 0 {
                let dec = ext.x / b + 1;
                ext.x -= dec * b;
                ext.y += dec * a;
            }
            Some(-ext.x * a)
        })
        .min()
        .unwrap();

