fn divisors(n: u64) -> Vec<u64> {
    let mut ret = Vec::new();
    for x in 1.. {
        if x * x > n {
            break;
        }
        if n % x == 0 {
            ret.push(x);
            if x * x < n {
                ret.push(n / x)
            }
        }
    }
    ret
}

