    let div = divisors(m);
    let ks = div.iter().filter_map(|&a| {
        // m = ab
        let a = a as i64;
        let b = m as i64 / a;

        // k = -ax, k+1 = by
        // ax + by = 1
        let mut ext = a.extended_gcd(&b);
        if ext.gcd != 1 {
            return None;
        }
        if ext.x >= 0 {
            let dec = ext.x / b + 1;
            ext.x -= dec * b;
            // ext.y += dec * a;
        }

        Some(-a * ext.x)
    });
    let ans = ks.min().unwrap();

    println!("{}", ans);
}

fn divisors(n: u64) -> Vec<u64> {
    let mut ret = Vec::new();
    for x in 1.. {
        if x * x > n {
            break;
        }
        if n % x == 0 {
            ret.push(x);
            if x * x < n {
                ret.push(n / x)
            }
        }
    }
    ret
}

