fn answer(n: i64) -> i64 {
    let mut l = 0;
    let k = 'outer: loop {
        l += 1;

        let m = 2 * l * n;
        let k_max = (m as f64).sqrt() as i64 + 1;
        let mut k = k_max;
        while k * (k + 1) >= m {
            if k * (k + 1) == m {
                break 'outer k;
            }
            k -= 1;
        }
    };
    k
}

