fn main() -> io::Result<()> {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024)
        .spawn(|| {
            let stdin = io::stdin();
            let stdout = io::stdout();
            run(KInput::new(stdin.lock()), io::BufWriter::new(stdout.lock()))
        })?
        .join()
        .unwrap()
}

fn run<I: Input, O: Write>(mut kin: I, mut out: O) -> io::Result<()> {
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+)?; }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush()?; } }
    }

    let n: i64 = kin.input();
    if n == 1 {
        outputln!("1");
        return Ok(());
    }
    let ps = primes(((n as f64).sqrt() + 1.) as usize);

    let mut fs = Vec::new();
    let mut x = 2 * n;
    for p in ps {
        let p = p as i64;
        if x % p == 0 {
            let mut d = 1;
            while x % p == 0 {
                x /= p;
                d *= p;
            }
            fs.push(d);
        }
    }
    if x > 1 {
        fs.push(x);
    }

    let mut ans = n - 1;
    for s in 0..1 << fs.len() {
        let mut x = 1;
        for i in 0..fs.len() {
            if s & (1 << i) != 0 {
                x *= fs[i];
            }
        }
        let y = 2 * n / x;
        let (g, a, b) = extgcd(x, y);
        if a < 0 && b > 0 {
            ans = ans.min(-a * x);
        }
    }
    outputln!("{}", ans);

    Ok(())
}

pub fn primes(n: usize) -> Vec<usize> {
    // 1, 7, 11, 13, 17, 19, 23, 29
    const SKIP: [u8; 8] = [6, 4, 2, 4, 2, 4, 6, 2];
    const XTOI: [u8; 15] = [
        0, 0, 0, 1, 0, 2, 3, 0, 4, 5, 0, 6, 0, 0, 7,
    ];
    let mut sieve = vec![0u8; n / 30 + 1];
    let mut ps = vec![2, 3, 5];
    if n <= 4 {
        ps.truncate([0, 0, 1, 2, 2][n]);
        return ps;
    }
    let mut x = 7;
    let mut i = 1;
    while x <= n {
        if sieve[i / 8] & 1 << i % 8 == 0 {
            ps.push(x);
            let mut j = i;
            let mut y = x * x;
            while y <= n {
                sieve[y / 30] |= 1 << XTOI[y / 2 % 15];
                y += x * SKIP[j % 8] as usize;
                j += 1;
            }
        }
        x += SKIP[i % 8] as usize;
        i += 1;
    }
    ps
}
pub fn extgcd(a: i64, b: i64) -> (i64, i64, i64) {
    if b != 0 {
        let (g, y, x) = extgcd(b, a.rem_euclid(b));
        (g, x, y - a / b * x)
    } else {
        (a, 1, 0)
    }
}

