fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: u128);
    let ps: Vec<_> = factor(n as usize).into_iter().collect();
    let m = ps.len();
    let mut ret = n - 1;
    for i in 0..(1 << m) {
        let mut x = 1u128;
        for j in 0..m {
            if i & (1 << j) != 0 {
                let (p, v) = ps[j];
                x *= p.pow(v as u32) as u128;
            }
        }
        let y = 2 * n / x;
        let (d, a, b) = ext_gcd(x, y);
        if a < 0 && b < 0 || a > 0 && b > 0 || d != 1 {
            continue;
        }
        let a = a.abs() as u128;
        let b = b.abs() as u128;
        let pret = min(a * x, b * y);
        if pret > 0 {
            ret.chmin(pret);
        }
    }
    println!("{}", ret);
}

fn ext_gcd(a: u128, b: u128) -> (u128, i128, i128) {
    if b == 0 {
        return (a, 1, 0);
    }
    let (d, y, x) = ext_gcd(b, a % b);
    (d, x, y - ((a / b) as i128) * x)
}

pub fn factor(mut n: usize) -> HashMap<usize, usize> {
    let mut ret = std::collections::HashMap::new();
    let n0 = n;
    let mut cur = 2;
    while cur * cur <= n0 {
        if n % cur != 0 {
            cur += 1;
            continue;
        }
        let mut count = 0;
        while n % cur == 0 {
            n /= cur;
            count += 1;
        }
        ret.insert(cur, count);
        cur += 1;
    }
    if n > 1 {
        ret.insert(n, 1);
    }
    ret
}

