pub fn solve<R: BufRead>(mut reader: StdinReader<R>) {
    let n = reader.u();

    let mut d = HashMap::new();
    let mut l = 2;
    let mut k = n;
    while l * l <= k {
        if k % l != 0 {
            l += 1;
        } else {
            *d.entry(l).or_insert(0) += 1;
            k /= l;
        }
    }
    *d.entry(k).or_insert(0) += 1;
    *d.entry(2).or_insert(0) += 1; // 2nm = k(k+1)を作る

    let mut m = Vec::new();
    for (&p, &c) in &d {
        let mut l = 1;
        for _ in 0..c {
            l *= p;
        }
        m.push(l);
    }

    //bit全探索する
    let p = 1 << d.len();
    let mut ans = std::usize::MAX;
    for i in 0..p {
        let mut a = vec![1, 1];
        //片側に全部入れる
        for j in 0..d.len() {
            a[if i >> j & 1 == 1 { 0 } else { 1 }] *= m[j];
        }
        a.sort();

        ans = min(ans, sol(a[1], a[0]));
    }
    println!("{}", ans);
}

fn sol(large: usize, small: usize) -> usize {
    if small == 1 {
        return large - 1;
    }
    let a = div(1, large, small) * large - 1;
    let b = div(large - 1, small, large) * large;
    min(a, b)
}

pub fn div(p: usize, e: usize, m: usize) -> usize {
    p * pow(e % m, m - 2, m) % m
}
pub fn pow(p: usize, e: usize, m: usize) -> usize {
    let mut result = 1;
    let mut cur = p;
    let mut e = e;
    while e > 0 {
        if e & 1 == 1 {
            result = (cur * result) % m;
        }
        e >>= 1;
        cur = cur * cur % m;
    }
    result
}

