fn answer(n: i64) -> i64 {
    let mut l = 0;
    let k = 'outer: loop {
        l += 1;

        let m = 2.0 * l as f64 * n as f64;
        let k_max = m.sqrt() as i64 + 1;
        let mut k = k_max;
        while k as f64 * (k + 1) as f64 >= m {
            if k as f64 * (k + 1) as f64 == m {
                break 'outer k;
            }
            k -= 1;
        }
    };
    k
}

