fn factorize(mut n: u128) -> Vec<u128> {
    let mut fac = Vec::new();
    for i in 2.. {
        if n < i * i {
            break;
        }
        if n % i == 0 {
            let mut count = 0;
            while n % i == 0 {
                count += 1;
                n /= i;
            }
            fac.push(i.pow(count));
        }
    }
    if n != 1 {
        fac.push(n);
    }
    fac
}

fn solve(n: u128) -> u128 {
    let fac = factorize(2 * n);

    let k = (1..1 << fac.len())
        .map(|bs| {
            let xm = fac
                .iter()
                .enumerate()
                .map(|(i, &q)| {
                    let r = if bs >> i & 1 == 1 { q - 1 } else { 0 };
                    (r, q)
                })
                .collect::<Vec<_>>();
            crt::crt(&xm).unwrap().0
        })
        .min()
        .unwrap();
    assert!(k * (k + 1) / 2 % n == 0);
    assert!(k <= 2 * n);
    k
}

fn main() {
    let mut buf = ngtio::Buffer::new();
    let n = buf.u128();
    let k = solve(n);
    println!("{}", k);
}

