    println!("{}", answer(n));
}

fn answer(n: u128) -> u64 {
    let mut l = 0;
    let k = 'outer: loop {
        l += 1;

        let m = 2 * l * n;
        let k_max = (m as f64).sqrt() as u128 + 1;
        let mut k = k_max;
        while k * (k + 1) >= m {
            if k * (k + 1) == m {
                break 'outer k;
            }
            k -= 1;
        }
    };
    k as u64
}

