pub fn binary_gcd(mut a: u64, mut b: u64) -> u64 {
  if a == 0 || b == 0 {
    return a + b;
  }
  let k = (a | b).trailing_zeros();
  a >>= a.trailing_zeros();
  b >>= b.trailing_zeros();
  while a != b {
    if a < b {
      std::mem::swap(&mut a, &mut b);
    }
    a -= b;
    a >>= a.trailing_zeros();
  }
  a << k
}

fn squfof_internal(n: u64) -> Option<u64> {
  let (sqrt_n, rem) = n.isqrt_rem();
  if rem == 0 {
    return Some(sqrt_n);
  }
  let D = if n % 4 == 1 { 2 * n } else { n };
  let (sqrt_D, mut Q) = D.isqrt_rem();
  let mut Q_hat = 1_u64;
  let mut P = sqrt_D;
  let L = (2.0 * (2.0 * (D as f64).sqrt()).sqrt()) as u64;
  let B = 2 * L;

  let mut queue = VecDeque::new();

  // println!("Step 1: {} {} {}", P, Q, L);

  let mut i = 1;
  let r = loop {
    // eprintln!("Step 2 {}: {} {}", i, P, Q);
    // 2a
    let q = (sqrt_D + P) / Q;
    let P_prime = q * Q - P;

    // 2b
    if Q <= L {
      if Q % 2 == 0 {
        queue.push_back((Q / 2, P % (Q / 2)));
      } else if 2 * Q <= L {
        queue.push_back((Q, P % Q));
      }
    }

    // 2c
    let t = Q_hat.wrapping_add(q.wrapping_mul(P.wrapping_sub(P_prime)));
    Q_hat = Q;
    Q = t;
    P = P_prime;

    // 2d
    let (r, rem) = Q.isqrt_rem();
    // maybe a typo in the paper (odd / even)
    if i % 2 == 1 && rem == 0 {
      let mut idx = 0;
      while idx < queue.len() {
        let (r_, t) = queue[idx];
        if r == r_ && P % r == t % r {
          break;
        }
        idx += 1;
      }
      if idx == queue.len() {
        break r;
      } else if r > 1 {
        queue = queue.split_off(idx + 1);
      } else {
        return None;
        //unreachable!()
      }
    }
    i += 1;

    if i >= B {
      return None;
    }
  };
  // 3
  // eprintln!("Step 3: Q_hat = {}, P = {}, r = {}", Q_hat, P, r);
  Q_hat = r;
  P = P + r * ((sqrt_D - P) / r);
  Q = (D - P * P) / Q_hat;
  assert!((D - P * P) % Q_hat == 0);

  // 4
  loop {
    // eprintln!("{} {}", P, Q);
    let q = (sqrt_D + P) / Q;
    let P_prime = q * Q - P;
    if P == P_prime {
      break;
    }
    let t = Q_hat.wrapping_add(q.wrapping_mul(P.wrapping_sub(P_prime)));
    Q_hat = Q;
    Q = t;
    P = P_prime;
  }
  // step 5
  if Q % 2 == 0 {
    return Some(Q / 2);
  } else {
    return Some(Q);
  }
}
pub fn squfof(n: u64) -> u64 {
  for m in 2.. {
    if m > 1 && n % m == 0 {
      return m;
    }
    if let Some(k) = squfof_internal(m * n) {
      let g = binary_gcd(k, n);
      if g != 1 && g != n {
        return g;
      }
    }
  }
  unreachable!();
}

pub trait Factorize: MillerRabin {
  type Output;
  fn factorize(self) -> HashMap<Self::Output, u64>;
}
impl Factorize for u64 {
  type Output = u64;
  fn factorize(self) -> HashMap<Self::Output, u64> {
    let mut result = HashMap::new();
    let mut stack = vec![self];
    while let Some(n) = stack.pop() {
      if n == 1 {
        continue;
      } else if n.is_prime() {
        *result.entry(n).or_insert(0) += 1;
      } else {
        let x = squfof(n);
        stack.push(x);
        stack.push(n / x);
      }
    }
    result
  }
}

fn extended_euclidean(u: i64, v: i64) -> i64 {
    let mut r0 = u;
    let mut r1 = v;
    let mut s0 = 1;
    let mut s1 = 0;
    let mut t0 = 0;
    let mut t1 = 1;
    while r1 != 0 {
        let q = r0 / r1;
        let r = r0 - q * r1;
        let s = s0 - q * s1;
        let t = t0 - q * t1;
        r0 = r1;
        s0 = s1;
        t0 = t1;
        r1 = r;
        s1 = s;
        t1 = t;
    }
    // println!("{} * {} + {} * {} = {}", s0, u, t0, v, r0);
    if t0 < 0 {
        t0 + u
    } else {
        t0
    }
}

