pub fn solve<R: BufRead>(mut reader: StdinReader<R>) {
    let n = reader.u();

    let mut d = HashMap::new();
    let mut l = 2;
    let mut k = n;
    while l * l <= k {
        if k % l != 0 {
            l += 1;
        } else {
            *d.entry(l).or_insert(0) += 1;
            k /= l;
        }
    }
    *d.entry(k).or_insert(0) += 1;
    *d.entry(2).or_insert(0) += 1; // 2nm = k(k+1)を作る

    let mut m = Vec::new();
    for (&p, &c) in &d {
        let mut l = 1;
        for _ in 0..c {
            l *= p;
        }
        m.push(l);
    }

    let mut pr = primes(10000000);
    //bit全探索する
    let p = 1 << d.len();
    let mut ans = std::usize::MAX;
    for i in 0..p {
        let mut a = vec![1, 1];
        //片側に全部入れる
        for j in 0..d.len() {
            a[if i >> j & 1 == 1 { 0 } else { 1 }] *= m[j];
        }
        a.sort();

        //大きい方*素数+1か、大きい方*素数-1が作れるならば、そのときの小さい方の値を保持する
        for p in &pr {
            if (a[1] * p - 1) % a[0] == 0 {
                ans = min(ans, a[1] * p - 1);
            }
            if (a[1] * p + 1) % a[0] == 0 {
                ans = min(ans, a[1] * p);
            }
        }
    }
    println!("{}", ans);
}

