fn answer(n: i64) -> i64 {
    let n = 2 * n as u128;
    let mut k = ((-1.0 + ((1 + 4 * n) as f64).sqrt()) / 2.0) as u128 / 2;
    let k = loop {
        if k * (k + 1) % n == 0 {
            break k;
        }

        k += 1;
    };
    k as i64
}

