                    ans = min(ans, x);
                }
            }
            let r = [i - 1, 0];
            if m[0] != 1 && m[1] != 1 {
                let m = [i, n / i];
                let x = crt(&r, &m);
                if let Some((x, y)) = x {
                    ans = min(ans, x);
                }
            }
        }
    }
    println!("{}", ans);
}

