fn ext_gcd(a: i64, b: i64, x: &mut i64, y: &mut i64) -> i64 {
  if b == 0 {
    *x = 1;
    *y = 0;
    a 
  } else {
    let d = ext_gcd(b, a % b, y, x);
    *y -= (a / b) * (*x);
    d
  }
}

fn chinese_rem(b1: i64, m1: i64, b2: i64, m2: i64) -> Option<(i64, i64)> {
  let mut x = 1i64;
  let mut y = 1i64;
  let d = ext_gcd(m1, m2, &mut x, &mut y);

  if (b2 - b1) % d != 0 {
    None
  } else {
    let m = m1 * (m2 / d);
    let t = ((b2 - b1) / d * x) % (m2 / d);
    let r = ((b1 + m1 * t) + m) % m;
    Some((r, m))
  }
}

