use proconio::{fastout, input};

#[fastout]
fn main() {
    input! {
        n: usize,
    }
    // Sieve of Eratosthenes
    const PMAX: usize = 32000000;
    let mut prime_factor: Vec<usize> = vec![1; PMAX];
    prime_factor[0] = 0;
    prime_factor[1] = 0;
    let mut primes_vec: Vec<usize> = Vec::new();
    for i in 2..PMAX {
        if prime_factor[i] == 1 {
            for j in i..=(PMAX - 1) / i {
                prime_factor[i * j] = i;
            }
            primes_vec.push(i);
        }
    }
    let _ = prime_factor;
    let primes_vec = primes_vec;

    let mut nn_primary_factors = Vec::new();
    let mut crt_m = Vec::new();
    let mut nn = n * 2;
    for &p in &primes_vec {
        if nn % p != 0 {
            continue;
        }
        let mut count = 0;
        let mut crt_mi = 1;
        while nn % p == 0 {
            nn /= p;
            count += 1;
            crt_mi *= p;
        }
        nn_primary_factors.push((p, count));
        crt_m.push(crt_mi as i64);
    }

    let mut kmin: i64 = std::i64::MAX;
    let mlen = crt_m.len();
    let mut r = vec![0; mlen];
    for i in 0..1 << mlen {
        let mut ii = i;
        for j in 0..mlen {
            if ii % 2 == 0 {
                r[j] = 0;
            } else {
                r[j] = crt_m[j] - 1;
            }
            ii /= 2;
        }
        let mut k = crt(&r, &crt_m).0;
        if k == 0 {
            k = (n * 2) as i64;
        }
        kmin = kmin.min(k);
    }
    println!("{}", kmin);
