    for d in d {
        let dp = m / d;
        let g = gcd(dp as u64, d as u64);
        if g == 1 {
            let (_, y, x) = extgcd(dp as i64, -(d as i64));
            if x > 0 && y > 0 && y as i128 * dp as i128 - x as i128 * d as i128 == 1 {
                chmin!(ans, x.saturating_mul(d as i64) as usize);
            }
            if x > 0 && y > 0 && x as i128 * d as i128 - y as i128 * dp as i128 == 1 {
                chmin!(ans, y.saturating_mul(dp as i64) as usize);
            }
        }
